(function initHeroineStatusWidget() {
    'use strict';

    // ==================== Cấu hình hằng số ====================
    const WIDGET_ID = 'heroine-status-widget-root';
    const CONFIG_KEY = 'heroine_status_widget_config_v1';
    const DATA_KEY = 'heroine_status_widget_data_v1';
    const HISTORY_KEY = 'heroine_status_widget_history_v1';
    const Z_INDEX_BALL = 5000;
    const Z_INDEX_PANEL = 5001;
    const SAFE_MARGIN = 16;
    const CLICK_DIST_THRESHOLD = 4;
    const BALL_SIZE = 58;
    const PANEL_WIDTH = 920;
    const PANEL_ZOOM = 1.15;
    const TABS_KEY = 'heroine_status_widget_tabs_v1';
    const ADAPTIVE_TAB_ID = 'adaptive';
    const MEN_TAB_ID = 'men_archive';
    // Bản dành cho nhà phát triển: ghi lại yêu cầu và câu trả lời gốc của mô hình ở mỗi lần đồng bộ (bản thường là false)
    const DEV_MODE = true;
    const DEV_LOG_KEY = 'heroine_status_widget_devlog_v1';
    const DEV_LOG_MAX = 15;

    // Khi cập nhật lên phiên bản này sẽ xóa nhật ký thử nghiệm cũ một lần; sau đó vẫn ghi nhật ký mới bình thường
    const DEV_LOG_RESET_KEY = DEV_LOG_KEY + '_reset_20261019';
    try {
        if (DEV_MODE && !localStorage.getItem(DEV_LOG_RESET_KEY)) {
            localStorage.removeItem(DEV_LOG_KEY);
            localStorage.setItem(DEV_LOG_RESET_KEY, '1');
        }
    } catch (e) {}

    // 1.90: prompt “phá giới hạn” tích hợp sẵn ở bản cũ không phải do người dùng tự viết nên sẽ bị xóa khi nâng cấp; nếu người dùng đã sửa thì giữ lại
    const LEGACY_JAILBREAK_MARKER = '[Core Role] - 身份';
    try {
        const rawCfg = localStorage.getItem(CONFIG_KEY);
        if (rawCfg) {
            const savedCfg = JSON.parse(rawCfg);
            if (savedCfg && typeof savedCfg.jailbreakPrompt === 'string'
                && savedCfg.jailbreakPrompt.trim().startsWith(LEGACY_JAILBREAK_MARKER)) {
                savedCfg.jailbreakPrompt = '';
                localStorage.setItem(CONFIG_KEY, JSON.stringify(savedCfg));
            }
        }
    } catch (e) {}

    // ==================== Biến trạng thái ====================
    let currentState = 'IDLE'; // IDLE | BALL_DRAGGING | PANEL_OPEN | PANEL_DRAGGING
    let currentPanelView = 'dashboard'; // dashboard | settings | devlog
    let isSyncing = false;
    let isBulkSyncing = false;
    // Cấu hình dùng trong lúc tự động đồng bộ (cấu hình đã lưu, cách chạy theo cài đặt); khi là null các hàm đồng bộ vẫn đọc cấu hình từ giao diện
    let syncCfgOverride = null;
    // Tiền tố nhắc ở thông tin cuối thanh trạng thái khi đang tự động đồng bộ
    const AUTO_SYNC_FOOTER_PREFIX = '⚠ Đang tự động đồng bộ (đừng gửi tin nhắn)';
    const withAutoSyncPrefix = (text) => (syncCfgOverride ? AUTO_SYNC_FOOTER_PREFIX + ' · ' : '') + text;
    // Thời điểm bắt đầu của lần đồng bộ hàng loạt gần nhất đã hoàn tất (tự động đồng bộ dựa vào đây để tránh đồng bộ trùng)
    let lastCompletedSyncStartedAt = 0;
    let charAvatarUrl = '';
    let selectedTimelineIndex = -1;
    let timelineNodes = [];
    let tabs = [];
    let currentTabId = ADAPTIVE_TAB_ID;
    // Tab đang được ghi khi đồng bộ hàng loạt: lưu trữ chỉ theo tab này, không bị ảnh hưởng nếu người dùng bấm tab khác giữa chừng
    let syncTargetTabId = null;

    // ==================== Phát hiện môi trường ====================
    let targetWindow = window;
    let targetDocument = document;
    try {
        if (window.parent && window.parent.document) {
            targetWindow = window.parent;
            targetDocument = window.parent.document;
        }
    } catch (e) {
        console.warn('[ heroine_status_widget ] Bị giới hạn khác miền, chuyển xuống môi trường hiện tại.');
    }

    // Thử lấy ảnh đại diện nhân vật (tương thích nhiều phiên bản trường dữ liệu)
    function getCharAvatarUrlCompat() {
        try {
            const pw = window.parent;
            if (!pw || !pw.SillyTavern) return '';
            const ctx = pw.SillyTavern.getContext();
            if (!ctx) return '';
            const chars = ctx.characters || [];
            let charId = ctx.characterId ?? ctx.currentCharacterId ?? ctx.mainCharacterId;
            let char = chars[charId];
            if (!char && ctx.character) char = ctx.character;
            if (!char && chars.length === 1) char = chars[0];
            if (char && char.avatar) return char.avatar;
            return '';
        } catch (e) {
            return '';
        }
    }
    charAvatarUrl = getCharAvatarUrlCompat();

    function getCurrentCardName() {
        try {
            const pw = window.parent;
            if (!pw || !pw.SillyTavern) return '';
            const ctx = pw.SillyTavern.getContext();
            if (!ctx) return '';
            const chars = ctx.characters || [];
            const charId = ctx.characterId ?? ctx.currentCharacterId ?? ctx.mainCharacterId;
            let char = chars[charId];
            if (!char && ctx.character) char = ctx.character;
            if (!char && chars.length === 1) char = chars[0];
            return char ? (char.name || '') : '';
        } catch (e) {
            return '';
        }
    }

    // ==================== Hàm tiện ích ====================
    const escapeForST = (str) => {
        if (typeof str !== 'string') return str;
        return str.replace(/(\\+)?([|{}])/g, (match, slashes, char) => {
            const s = slashes || '';
            return s + s + '\\' + char;
        });
    };

    const showToast = (msg, type = 'info') => {
        if (typeof triggerSlash === 'function') {
            triggerSlash(`/echo severity=${type} ${escapeForST(msg)}`);
        } else {
            console.log(`[Toast - ${type}] ${msg}`);
        }
    };
    // Thông báo trong quá trình đồng bộ: khi tự động đồng bộ (đã đặt syncCfgOverride) chỉ giữ thông báo lỗi, còn lại chỉ ghi ra console
    const syncToast = (msg, type = 'info') => {
        if (syncCfgOverride && type !== 'error') { console.log(`[Thanh trạng thái nữ chính·Tự động đồng bộ] ${msg}`); return; }
        showToast(msg, type);
    };

    const debounce = (fn, wait) => {
        let timer;
        return (...args) => {
            clearTimeout(timer);
            timer = setTimeout(() => fn(...args), wait);
        };
    };

    // ==================== Dọn phiên bản cũ ====================
    const oldContainer = targetDocument.getElementById(WIDGET_ID);
    if (oldContainer) oldContainer.remove();

    // Tạo container chủ
    const container = targetDocument.createElement('div');
    container.id = WIDGET_ID;
    container.style.position = 'fixed';
    container.style.top = '0';
    container.style.left = '0';
    container.style.width = '0';
    container.style.height = '0';
    container.style.overflow = 'visible';
    container.style.pointerEvents = 'none';
    container.style.zIndex = Z_INDEX_BALL;
    targetDocument.body.appendChild(container);

    const shadow = container.attachShadow({ mode: 'open' });

    // ==================== Phông chữ tiếng Việt ====================
    // Be Vietnam Pro (chữ thường), Lora (tiêu đề), JetBrains Mono (nhật ký); không tải được thì dùng phông hệ thống
    const FONT_LINK_ID = 'heroine-status-vi-fonts';
    if (!targetDocument.getElementById(FONT_LINK_ID)) {
        const fontLink = targetDocument.createElement('link');
        fontLink.id = FONT_LINK_ID;
        fontLink.rel = 'stylesheet';
        fontLink.href = 'https://fonts.googleapis.com/css2?family=Be+Vietnam+Pro:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400&family=Lora:ital,wght@0,600;0,700;1,600&family=JetBrains+Mono:wght@400;600&display=swap&subset=vietnamese';
        (targetDocument.head || targetDocument.documentElement).appendChild(fontLink);
    }

    // ==================== Font Awesome ====================
    const faLink = targetDocument.createElement('link');
    faLink.rel = 'stylesheet';
    faLink.href = 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css';
    shadow.appendChild(faLink);

    // ==================== Chèn style ====================
    const style = targetDocument.createElement('style');
    style.textContent = `
        :host {
            --font: "Be Vietnam Pro", "Segoe UI", Roboto, "Helvetica Neue", Arial, "PingFang SC", "Microsoft YaHei", sans-serif;
            --font-display: "Lora", "Noto Serif", Georgia, "Times New Roman", serif;
            --font-mono: "JetBrains Mono", Consolas, "SF Mono", Menlo, monospace;
            --font-size-xl: 22px;
            --coral: #f0976e;
            --peach: #f5b894;
            --gold: #e6c47a;
            --cream: #fff6ed;
            --card: rgba(255, 245, 235, 0.72);
            --border: rgba(255, 205, 175, 0.55);
            --text-main: #5a3d2b;
            --text-sub: #8a6b55;
            --text-soft: #b09278;
            --glow: #f5cba7;
            --success: #7ca86a;
            --danger: #d45d4d;
            --warning: #d9a44a;
            --info: #6a9ec4;
            --radius-sm: 10px;
            --radius-md: 16px;
            --radius-lg: 22px;
            --radius-pill: 999px;
            --shadow-soft: 0 2px 10px rgba(200, 140, 90, 0.14);
            --shadow-window: 0 6px 24px rgba(180, 120, 70, 0.22);
            --shadow-raised: 0 10px 32px rgba(180, 110, 60, 0.28);
            --shadow-glow: 0 0 18px rgba(245, 190, 140, 0.75);
            --blur: blur(14px);
            --transition-base: 0.28s cubic-bezier(0.4, 0, 0.2, 1);
            --transition-bounce: 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
            all: initial;
        }
        /* Chặn bóng chữ do theme của Tavern kế thừa qua shadow DOM, giữ chữ rõ nét */
        :host { text-shadow: none !important; }
        *, *::before, *::after { box-sizing: border-box; font-family: var(--font); margin: 0; padding: 0; text-shadow: none !important; }
        .fas, .far, .fab, .fa-solid, .fa-regular, .fa-brands {
            font-family: "Font Awesome 6 Free", "Font Awesome 6 Brands" !important;
            font-weight: 900 !important;
            font-style: normal !important;
            font-variant: normal !important;
            line-height: 1 !important;
            text-rendering: auto !important;
            -webkit-font-smoothing: antialiased !important;
            -moz-osx-font-smoothing: grayscale !important;
        }
        .far, .fa-regular { font-weight: 400 !important; }
        .fab, .fa-brands { font-weight: 400 !important; }

        /* ========== Bóng nổi ========== */
        .float-ball {
            position: absolute;
            width: ${BALL_SIZE}px;
            height: ${BALL_SIZE}px;
            border-radius: 50%;
            background: linear-gradient(135deg, rgba(255, 230, 205, 0.96), rgba(245, 170, 130, 0.92));
            border: 2px solid rgba(255, 220, 190, 0.85);
            box-shadow: 0 0 16px rgba(240, 160, 110, 0.5), inset 0 2px 6px rgba(255,255,255,0.45);
            cursor: grab;
            pointer-events: auto;
            display: flex;
            justify-content: center;
            align-items: center;
            color: #fff;
            font-size: 24px;
            user-select: none;
            transition: transform var(--transition-base), box-shadow var(--transition-base);
            z-index: 10;
            animation: ball-breathe 2.6s ease-in-out infinite;
        }
        .float-ball:hover {
            transform: scale(1.06);
            box-shadow: 0 0 26px rgba(240, 150, 90, 0.8), inset 0 2px 8px rgba(255,255,255,0.55);
        }
        .float-ball:active { cursor: grabbing; transform: scale(0.97); }
        .float-ball.dragging {
            transition: none;
            animation: none;
            transform: scale(1.08);
            opacity: 0.9;
        }
        .float-ball.hidden { transform: scale(0); opacity: 0; pointer-events: none; }
        @keyframes ball-breathe {
            0%, 100% { box-shadow: 0 0 12px rgba(240, 160, 110, 0.45), inset 0 2px 6px rgba(255,255,255,0.4); }
            50% { box-shadow: 0 0 24px rgba(240, 160, 110, 0.85), inset 0 2px 8px rgba(255,255,255,0.55); }
        }

        /* ========== Bảng điều khiển ========== */
        .panel {
            position: absolute;
            zoom: ${PANEL_ZOOM};
            width: min(${PANEL_WIDTH}px, calc((100vw - 40px) / ${PANEL_ZOOM}));
            max-height: min(calc(92vh / ${PANEL_ZOOM}), 680px);
            display: flex;
            flex-direction: column;
            background: var(--cream);
            border: 2px solid var(--border);
            border-radius: var(--radius-lg);
            box-shadow: var(--shadow-window);
            opacity: 0;
            transform: scale(0.9) translateY(16px);
            pointer-events: none;
            transition: opacity var(--transition-base), transform var(--transition-base);
            z-index: 20;
            overflow: hidden;
            background-image:
                radial-gradient(ellipse at 12% 8%, rgba(255, 210, 170, 0.35) 0%, transparent 50%),
                radial-gradient(ellipse at 88% 22%, rgba(250, 180, 150, 0.25) 0%, transparent 45%),
                radial-gradient(ellipse at 50% 92%, rgba(240, 200, 160, 0.3) 0%, transparent 50%);
        }
        .panel.show {
            opacity: 1;
            transform: scale(1) translateY(0);
            pointer-events: auto;
        }
        .panel.dragging { transition: none; }
        .panel:not(.show) * { pointer-events: none !important; }

        /* Thanh tiêu đề */
        .panel-header {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 12px 18px;
            cursor: move;
            background: linear-gradient(135deg, rgba(255, 242, 228, 0.95), rgba(255, 220, 195, 0.92));
            border-bottom: 2px solid var(--border);
            user-select: none;
            flex-shrink: 0;
        }
        .header-icon {
            width: 36px;
            height: 36px;
            border-radius: 10px;
            background: linear-gradient(135deg, #f8b28a, #e88d68);
            display: flex;
            align-items: center;
            justify-content: center;
            color: #fff;
            font-size: 17px;
            box-shadow: var(--shadow-soft);
            animation: header-breathe 2.5s ease-in-out infinite;
            flex-shrink: 0;
        }
        @keyframes header-breathe {
            0%, 100% { box-shadow: 0 0 6px rgba(245, 140, 90, 0.5); }
            50% { box-shadow: 0 0 18px rgba(245, 160, 110, 0.85); }
        }
        .header-text {
            display: flex;
            flex-direction: column;
            gap: 2px;
            flex: 1;
            min-width: 0;
        }
        .header-title {
            font-size: 16px;
            font-weight: 700;
            letter-spacing: 0.04em;
            background: linear-gradient(135deg, #6a422c, #a06a45);
            -webkit-background-clip: text;
            background-clip: text;
            -webkit-text-fill-color: transparent;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .header-subtitle {
            font-size: 11px;
            color: var(--text-soft);
            letter-spacing: 0.06em;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .header-actions {
            display: flex;
            align-items: center;
            justify-content: flex-end;
            gap: 6px;
            flex-shrink: 0;
            flex-wrap: wrap;
        }
        .header-tools {
            display: flex;
            align-items: center;
            gap: 6px;
            flex-shrink: 0;
        }
        .header-btn {
            width: 32px;
            height: 32px;
            border-radius: 8px;
            border: 1.5px solid rgba(240, 170, 120, 0.45);
            background: rgba(255, 245, 235, 0.7);
            color: var(--text-sub);
            font-size: 14px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all var(--transition-base);
            pointer-events: auto;
        }
        .header-btn:hover {
            border-color: var(--coral);
            color: var(--coral);
            box-shadow: 0 0 10px rgba(240, 160, 110, 0.35);
            transform: translateY(-1px);
        }
        .header-btn:active { transform: scale(0.95); }
        .header-text-btn {
            display: inline-flex;
            align-items: center;
            gap: 5px;
            padding: 6px 11px;
            border-radius: 999px;
            border: 1.5px solid rgba(240, 170, 120, 0.45);
            background: rgba(255, 245, 235, 0.75);
            color: var(--text-sub);
            font-size: 11px;
            font-weight: 700;
            cursor: pointer;
            pointer-events: auto;
            transition: all var(--transition-base);
            white-space: nowrap;
        }
        .header-text-btn:hover {
            border-color: var(--coral);
            color: var(--coral);
            box-shadow: 0 0 10px rgba(240, 160, 110, 0.35);
            transform: translateY(-1px);
        }
        .header-text-btn:active { transform: scale(0.97); }
        .header-btn.close-btn:hover {
            border-color: var(--danger);
            color: var(--danger);
            box-shadow: 0 0 10px rgba(212, 93, 77, 0.35);
        }

        /* Thanh tab nhân vật */
        .char-tab-bar {
            display: flex;
            align-items: center;
            gap: 6px;
            padding: 8px 14px;
            background: rgba(255, 238, 220, 0.7);
            border-bottom: 1px solid var(--border);
            backdrop-filter: var(--blur);
            -webkit-backdrop-filter: var(--blur);
            flex-shrink: 0;
            flex-wrap: nowrap;
            min-width: 0;
            overflow: hidden;
        }
        .char-tabs {
            display: flex;
            align-items: center;
            gap: 6px;
            flex: 1 1 auto;
            flex-wrap: nowrap;
            min-width: 0;
            overflow-x: auto;
            overscroll-behavior-x: contain;
            -webkit-overflow-scrolling: touch;
            scrollbar-width: thin;
            scrollbar-color: rgba(240, 170, 120, 0.4) transparent;
        }
        .char-tabs::-webkit-scrollbar { height: 4px; }
        .char-tabs::-webkit-scrollbar-thumb { background: rgba(240, 170, 120, 0.4); border-radius: 999px; }
        .char-tab {
            display: inline-flex;
            flex: 0 0 auto;
            align-items: center;
            gap: 6px;
            padding: 6px 10px 6px 14px;
            border-radius: 999px;
            background: rgba(255, 250, 244, 0.7);
            border: 1.5px solid rgba(240, 195, 155, 0.4);
            color: var(--text-sub);
            font-size: 12px;
            font-weight: 600;
            cursor: pointer;
            white-space: nowrap;
            transition: all var(--transition-base);
            pointer-events: auto;
            max-width: 190px;
            min-width: 0;
        }
        .char-tab:hover {
            border-color: var(--coral);
            color: var(--text-main);
            background: rgba(240, 170, 120, 0.22);
        }
        .char-tab.active {
            background: linear-gradient(135deg, #f8b28a, #e88d68);
            color: #fff;
            border-color: rgba(255, 220, 190, 0.6);
            box-shadow: 0 2px 10px rgba(230, 130, 80, 0.45);
        }
        .char-tab-check {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 16px;
            height: 16px;
            border-radius: 4px;
            border: 1.5px solid rgba(240, 170, 120, 0.6);
            background: rgba(255, 250, 244, 0.85);
            color: transparent;
            font-size: 11px;
            line-height: 1;
            flex-shrink: 0;
            cursor: pointer;
        }
        .char-tab-check.checked {
            background: linear-gradient(135deg, #f8b28a, #e88d68);
            border-color: transparent;
            color: #fff;
        }
        .char-tab-check:focus-visible {
            outline: 2px solid var(--coral);
            outline-offset: 2px;
        }
        .char-tab-name {
            max-width: 130px;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .char-tab-close {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 18px;
            height: 18px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.35);
            color: inherit;
            font-size: 12px;
            font-weight: 700;
            line-height: 1;
            transition: all var(--transition-base);
            flex-shrink: 0;
        }
        .char-tab:not(.active) .char-tab-close {
            background: rgba(200, 150, 100, 0.18);
        }
        .char-tab-close:hover {
            background: var(--danger);
            color: #fff;
            transform: scale(1.15);
        }
        .char-tab-add {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 28px;
            height: 28px;
            border-radius: 50%;
            border: 1.5px dashed rgba(240, 160, 110, 0.55);
            background: rgba(255, 245, 235, 0.8);
            color: var(--coral);
            font-size: 18px;
            font-weight: 700;
            cursor: pointer;
            transition: all var(--transition-base);
            pointer-events: auto;
            flex-shrink: 0;
        }
        .char-tab-add:hover {
            border-style: solid;
            background: rgba(240, 170, 120, 0.22);
            box-shadow: 0 0 10px rgba(240, 160, 110, 0.35);
            transform: scale(1.08);
        }
        .char-tab-add:active { transform: scale(0.95); }

        /* Vùng nội dung */
        .panel-body {
            flex: 1;
            overflow-y: auto;
            overflow-x: hidden;
            position: relative;
            min-height: 0;
            scrollbar-width: thin;
            scrollbar-color: rgba(240, 170, 120, 0.4) transparent;
        }
        .panel-body::-webkit-scrollbar { width: 5px; }
        .panel-body::-webkit-scrollbar-track { background: transparent; }
        .panel-body::-webkit-scrollbar-thumb {
            background: rgba(240, 170, 120, 0.4);
            border-radius: 999px;
        }

        /* Thanh công cụ dưới cùng */
        .panel-footer {
            display: flex;
            flex-direction: column;
            align-items: stretch;
            gap: 8px;
            padding: 10px 16px;
            background: rgba(255, 238, 220, 0.85);
            border-top: 1.5px solid var(--border);
            backdrop-filter: var(--blur);
            -webkit-backdrop-filter: var(--blur);
            flex-shrink: 0;
        }
        .footer-debug-row { display: flex; width: 100%; }
        .footer-debug-row .debug-input { width: 100%; flex: 1 1 auto; }
        .footer-actions-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
        .repair-btn { background: linear-gradient(135deg, #e6c47a, #d9a44a); }
