        /* ========== Bảng trạng thái (chuyển từ code regex gốc) ========== */
        .hs-main {
            container-type: inline-size;
            font-family: var(--font);
            font-size: 14px;
            color: var(--text-main);
            line-height: 1.5;
            width: 100%;
            background: transparent;
            padding: 12px;
            box-sizing: border-box;
        }
        .history-area {
            display: flex;
