            gap: 10px;
            margin-bottom: 10px;
            flex-wrap: wrap;
        }
        .history-track {
            display: flex;
            align-items: center;
            gap: 8px;
            flex: 1 1 300px;
            overflow-x: auto;
            padding: 6px;
            background: rgba(255, 238, 220, 0.55);
            border: 1px solid var(--border);
            border-radius: 999px;
            scrollbar-width: thin;
        }
        .history-track::-webkit-scrollbar { height: 4px; }
        .history-track::-webkit-scrollbar-thumb { background: rgba(240, 170, 120, 0.4); border-radius: 999px; }
        .history-node {
            width: 26px;
            height: 26px;
            min-width: 26px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 11px;
            font-weight: 700;
            color: var(--text-sub);
            background: rgba(255, 250, 244, 0.7);
            border: 1.5px solid rgba(240, 160, 110, 0.3);
            cursor: pointer;
            transition: all var(--transition-base);
            flex-shrink: 0;
        }
        .history-node:hover {
            border-color: var(--coral);
            box-shadow: 0 0 8px rgba(240, 160, 110, 0.35);
        }
        .history-node.current {
            background: linear-gradient(135deg, #f8b28a, #e88d68);
            color: #fff;
            border-color: rgba(255, 220, 190, 0.6);
            box-shadow: 0 0 8px rgba(230, 130, 80, 0.45);
        }
        .history-node.selected {
            outline: 2px solid var(--gold);
            outline-offset: 1px;
        }
        .history-empty {
            font-size: 12px;
            color: var(--text-soft);
            padding: 0 8px;
        }
        .history-btn { flex-shrink: 0; }
        .hs-font-xs { font-size: clamp(0.65rem, 0.5rem + 0.45cqw, 0.78rem); }
        .hs-font-sm { font-size: clamp(0.75rem, 0.6rem + 0.55cqw, 0.88rem); }
        .hs-font-md { font-size: clamp(0.95rem, 0.82rem + 0.8cqw, 1.2rem); }
        .hs-font-lg { font-size: clamp(1.1rem, 0.95rem + 1cqw, 1.5rem); }
        .hs-font-xl { font-size: clamp(1.3rem, 1.1rem + 1.3cqw, 1.9rem); }
        .hs-text-sub { color: var(--text-sub); }

        .hs-nav {
            display: flex;
