            border-radius: 999px;
            overflow-x: auto;
            scrollbar-width: none;
            flex-wrap: wrap;
            justify-content: center;
            margin-bottom: 12px;
        }
        .hs-nav::-webkit-scrollbar { display: none; }
        .hs-tab-btn {
            display: flex;
            align-items: center;
            gap: 4px;
            padding: 6px 12px;
            border-radius: var(--radius-pill);
            border: 1.5px solid transparent;
            background: transparent;
            color: var(--text-sub);
            font-size: 12px;
            font-weight: 600;
            cursor: pointer;
            white-space: nowrap;
            transition: all var(--transition-bounce);
