        .hs-tab-btn:hover {
            background: rgba(240, 170, 120, 0.28);
            color: var(--text-main);
            border-color: rgba(240, 160, 110, 0.45);
        }
        .hs-tab-btn:active { transform: scale(0.94); }
        .hs-tab-btn.active {
            background: linear-gradient(135deg, #f8b28a, #e88d68);
            color: #fff;
            box-shadow: 0 2px 8px rgba(230, 130, 80, 0.45);
            transform: translateY(-2px);
            animation: tab-breathe 2.5s ease-in-out infinite;
            border-color: rgba(255, 220, 190, 0.6);
