        .hs-tab-panel { display: none; animation: hs-fade-in 0.35s ease-out; }
        .hs-tab-panel.active { display: block; }
        @keyframes hs-fade-in {
            from { opacity: 0; transform: translateY(8px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .hs-card {
