            margin-bottom: 10px;
            display: flex;
            align-items: center;
            gap: 6px;
            color: var(--text-main);
        }
        .hs-card-title .title-icon {
            width: 22px;
            height: 22px;
            border-radius: 6px;
            background: rgba(240, 170, 120, 0.22);
