            align-items: center;
            justify-content: center;
            font-size: 12px;
            color: var(--coral);
            flex-shrink: 0;
        }
        .hs-grid-2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); gap: 14px; }
        .hs-charm-row { display: flex; align-items: flex-start; gap: 10px; }
