        .hs-grid-3 { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 190px), 1fr)); gap: 10px; }
        .hs-grid-4 { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr)); gap: 8px; }
        .hs-flex-wrap { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }

        .hs-flat-stat {
            display: flex;
            flex-direction: column;
            gap: 3px;
            padding: 8px 10px;
            border-radius: 10px;
            background: rgba(255, 250, 244, 0.55);
            border: 1px solid rgba(240, 195, 155, 0.35);
            transition: all var(--transition-base);
        }
        .hs-flat-stat:hover { border-color: var(--peach); box-shadow: var(--shadow-soft); }
        .hs-flat-stat .flat-label {
            font-size: 12px;
            font-weight: 700;
            color: var(--text-main);
            letter-spacing: 0.03em;
            line-height: 1.4;
            word-break: break-word;
        }
        .hs-flat-stat .flat-value {
            font-size: 12px;
            color: var(--text-main);
            line-height: 1.6;
            word-break: break-word;
        }

        .hs-progress {
            width: 100%;
            height: 10px;
            background: rgba(230, 200, 170, 0.45);
            border-radius: var(--radius-pill);
            overflow: hidden;
            position: relative;
        }
        .hs-progress-fill {
            height: 100%;
            background-color: #e87d5e;
            background-image: linear-gradient(90deg, #f5a87a, #e87d5e);
            border-radius: var(--radius-pill);
            transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
            position: relative;
        }
        .hs-progress-fill::after {
            content: "";
            position: absolute;
            inset: 0;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.35), transparent);
            animation: progress-shine 2.8s infinite;
        }
        @keyframes progress-shine {
            0% { transform: translateX(-100%); }
            60%, 100% { transform: translateX(100%); }
        }
        .hs-progress-label {
            display: flex;
            align-items: center;
            justify-content: space-between;
            font-size: 12px;
            margin-bottom: 3px;
            gap: 8px;
            flex-wrap: wrap;
        }
        .hs-progress-label .label-text { color: var(--text-sub); font-weight: 500; }
        .hs-progress-label .label-value { color: var(--text-main); font-weight: 700; }

        .hs-ring {
            width: clamp(50px, 5cqw, 80px);
            height: clamp(50px, 5cqw, 80px);
            border-radius: 50%;
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }
        .hs-ring::before {
            content: "";
            position: absolute;
            inset: 0;
            border-radius: 50%;
            background: conic-gradient(
                #e87d5e calc(var(--ring-value, 50) * 1%),
                rgba(230, 200, 170, 0.4) calc(var(--ring-value, 50) * 1%)
            );
            -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 6px), #fff calc(100% - 5px));
            mask: radial-gradient(farthest-side, transparent calc(100% - 6px), #fff calc(100% - 5px));
            transition: background 0.8s ease;
        }
        .hs-ring-inner {
            position: relative;
            z-index: 1;
            font-size: 12px;
            font-weight: 700;
            color: var(--text-main);
            text-align: center;
        }

        .hs-tag {
            display: inline-flex;
            align-items: center;
            gap: 4px;
            padding: 3px 10px;
            border-radius: var(--radius-pill);
            border: 1px solid rgba(240, 160, 110, 0.45);
            background: rgba(240, 170, 120, 0.22);
            font-size: 12px;
            color: var(--text-main);
            font-weight: 500;
            max-width: 100%;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .hs-tag .tag-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--coral); flex-shrink: 0; }
        .hs-tag--gold .tag-dot { background: var(--warning); }
        .hs-tag--blue .tag-dot { background: var(--info); }
        .hs-tag--pink .tag-dot { background: var(--danger); }
        .hs-tag--green .tag-dot { background: var(--success); }

        .hs-timeline {
            position: relative;
            padding-left: 22px;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }
        .hs-timeline::before {
            content: "";
            position: absolute;
            left: 7px;
            top: 4px;
            bottom: 4px;
            width: 2px;
            background: repeating-linear-gradient(to bottom, var(--peach) 0, var(--peach) 4px, transparent 4px, transparent 8px);
        }
        .hs-timeline-item {
            position: relative;
            padding: 6px 10px;
            border-radius: 8px;
            background: rgba(255, 250, 244, 0.5);
            border: 1px solid rgba(240, 190, 150, 0.3);
            font-size: 12px;
            color: var(--text-main);
        }
        .hs-timeline-item::before {
            content: "";
            position: absolute;
            left: -19px;
            top: 12px;
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--coral);
            box-shadow: 0 0 6px rgba(240, 130, 80, 0.6);
        }
        .hs-timeline-item.current::before {
            animation: header-breathe 2s ease-in-out infinite;
            background: var(--warning);
