        }
        .hs-paragraph-card {
            padding: 10px;
            border-radius: var(--radius-md);
            background: rgba(255, 250, 244, 0.6);
            border: 1.5px solid var(--border);
            backdrop-filter: var(--blur);
            -webkit-backdrop-filter: var(--blur);
            font-size: 13px;
            line-height: 1.75;
            color: var(--text-main);
            min-height: 60px;
        }
        .hs-svg-container {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            width: 100%;
            overflow: hidden;
            padding: 6px;
            box-sizing: border-box;
        }
        .hs-svg-container svg { display: block; max-width: 100%; height: auto; border-radius: 10px; }
        .hs-collapsible-chart .hs-chart-body { display: none; }
        .hs-collapsible-chart.expanded .hs-chart-body { display: flex; }
        .hs-chart-toggle { cursor: pointer; user-select: none; }
        .hs-chart-toggle:hover { color: var(--coral); }
        .hs-chart-chevron { margin-left: auto; transition: transform var(--transition-base); }
        .hs-collapsible-chart.expanded .hs-chart-chevron { transform: rotate(180deg); }

        /* ========== Hồ sơ trạng thái / Tâm lý thai kỳ tinh chỉnh ========== */
        .hs-subhead {
            display: flex;
            align-items: center;
            gap: 8px;
            margin: 14px 0 8px;
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.16em;
            color: var(--text-soft);
        }
        .hs-subhead::after {
            content: "";
            flex: 1;
            height: 1px;
            background: linear-gradient(90deg, rgba(240, 170, 120, 0.45), rgba(240, 170, 120, 0));
        }
        .hs-state-hero {
            position: relative;
            padding: 12px;
            border-radius: 14px;
            border: 1px solid rgba(240, 180, 140, 0.45);
            background:
                radial-gradient(120% 150% at 0% 0%, rgba(255, 214, 180, 0.55), rgba(255, 214, 180, 0) 62%),
                linear-gradient(135deg, rgba(255, 247, 238, 0.95), rgba(255, 233, 216, 0.85));
            overflow: hidden;
        }
        .hs-state-hero::after {
            content: "";
            position: absolute;
            right: -46px;
            bottom: -70px;
            width: 170px;
            height: 170px;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(245, 170, 120, 0.22), rgba(245, 170, 120, 0) 68%);
            pointer-events: none;
        }
        .hs-state-hero-head {
            display: flex;
            align-items: center;
            gap: 7px;
            margin-bottom: 10px;
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.14em;
            color: var(--coral);
        }
        .hs-live-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: var(--coral);
            animation: hs-live-pulse 2.2s ease-in-out infinite;
        }
        @keyframes hs-live-pulse {
            0%, 100% { box-shadow: 0 0 0 3px rgba(240, 151, 110, 0.18); }
            50% { box-shadow: 0 0 0 6px rgba(240, 151, 110, 0.04); }
        }
        .hs-state-chips {
            position: relative;
            z-index: 1;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 150px), 1fr));
            gap: 8px;
        }
        .hs-state-chip {
            position: relative;
            padding: 9px 10px 9px 13px;
            border-radius: 10px;
            background: rgba(255, 252, 248, 0.8);
            border: 1px solid rgba(240, 195, 155, 0.5);
            box-shadow: 0 1px 3px rgba(200, 140, 90, 0.08);
        }
        .hs-state-chip::before {
            content: "";
            position: absolute;
            left: 0;
            top: 10px;
            bottom: 10px;
            width: 3px;
            border-radius: 0 3px 3px 0;
            background: linear-gradient(180deg, #f8b28a, #e88d68);
        }
        .hs-state-chip .chip-label {
            font-size: 10px;
            font-weight: 700;
            letter-spacing: 0.12em;
            color: var(--text-soft);
        }
        .hs-state-chip .chip-value {
            margin-top: 3px;
            font-size: 13px;
            font-weight: 700;
            line-height: 1.5;
            color: var(--text-main);
            word-break: break-word;
        }
        .hs-meter-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 190px), 1fr));
            gap: 8px;
        }
        .hs-meter {
            padding: 9px 10px 10px;
            border-radius: 10px;
            background: rgba(255, 250, 244, 0.6);
            border: 1px solid rgba(240, 195, 155, 0.4);
        }
        .hs-meter-head {
            display: flex;
            align-items: baseline;
            justify-content: space-between;
            gap: 8px;
        }
        .hs-meter-label {
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.03em;
            color: var(--text-sub);
        }
        .hs-meter-value {
            font-size: 12px;
            font-weight: 800;
            color: var(--text-main);
        }
        .hs-meter-track {
            margin-top: 7px;
            height: 6px;
            border-radius: 999px;
            background: rgba(230, 200, 170, 0.42);
            overflow: hidden;
        }
        .hs-meter-fill {
            height: 100%;
            border-radius: 999px;
            transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
            background-image: linear-gradient(90deg, #f5a87a, #e87d5e);
        }
        .hs-meter-fill.tone-blue { background-image: linear-gradient(90deg, #a9cbe4, #6a9ec4); }
        .hs-meter-fill.tone-pink { background-image: linear-gradient(90deg, #f3bfd3, #d88bb0); }
        .hs-meter-fill.tone-gold { background-image: linear-gradient(90deg, #f0d9a0, #d9a44a); }
        .hs-meter-fill.tone-green { background-image: linear-gradient(90deg, #bcd7a8, #7ca86a); }
        .hs-meter-fill.tone-mauve { background-image: linear-gradient(90deg, #d9bfe0, #a985b8); }
        .hs-meter.is-text .hs-meter-value {
            margin-top: 4px;
            font-weight: 600;
            font-size: 12.5px;
            line-height: 1.55;
            word-break: break-word;
        }
        .hs-metric-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 165px), 1fr));
            gap: 8px;
        }
        .hs-metric {
            display: flex;
            flex-direction: column;
            gap: 4px;
            padding: 9px 10px;
            border-radius: 10px;
            background: rgba(255, 250, 244, 0.58);
            border: 1px solid rgba(240, 195, 155, 0.38);
            transition: border-color var(--transition-base), box-shadow var(--transition-base);
        }
        .hs-metric:hover {
            border-color: var(--peach);
            box-shadow: var(--shadow-soft);
        }
        .hs-metric.is-static {
            border-style: dashed;
            background: rgba(255, 250, 244, 0.32);
        }
        .hs-metric .metric-top {
            display: flex;
            align-items: center;
            gap: 6px;
        }
        .hs-metric .metric-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 20px;
            height: 20px;
            flex-shrink: 0;
            border-radius: 6px;
            background: rgba(240, 170, 120, 0.18);
            color: var(--coral);
            font-size: 10px;
        }
        .hs-metric .metric-label {
            font-size: 11px;
            font-weight: 700;
            line-height: 1.35;
            color: var(--text-sub);
        }
        .hs-metric .metric-value {
            font-size: 12.5px;
            font-weight: 700;
            line-height: 1.55;
            color: var(--text-main);
            word-break: break-word;
        }
        .hs-psy-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 215px), 1fr));
            gap: 8px;
        }
        .hs-psy-item {
            padding: 10px 11px 11px;
            border-radius: 12px;
            border: 1px solid rgba(240, 195, 155, 0.42);
            background: linear-gradient(145deg, rgba(255, 252, 248, 0.95), rgba(255, 240, 230, 0.62));
        }
        .hs-psy-item.is-accent {
            border-color: rgba(232, 141, 104, 0.55);
            box-shadow: inset 0 0 0 1px rgba(232, 141, 104, 0.12), 0 2px 10px rgba(232, 141, 104, 0.12);
        }
        .hs-psy-item .psy-head {
            display: flex;
            align-items: baseline;
            justify-content: space-between;
            gap: 8px;
        }
        .hs-psy-item .psy-label {
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.03em;
            color: var(--text-sub);
        }
        .hs-psy-item .psy-value {
            font-size: 13px;
            font-weight: 800;
            color: var(--text-main);
        }
        .hs-psy-item.is-text .psy-value {
            font-size: 12px;
            font-weight: 600;
            line-height: 1.5;
            text-align: right;
            word-break: break-word;
        }
        .hs-psy-track {
            margin-top: 8px;
            height: 7px;
            border-radius: 999px;
            background: rgba(230, 200, 170, 0.4);
            overflow: hidden;
        }
        .hs-psy-fill {
            height: 100%;
            border-radius: 999px;
            transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
            background-image: linear-gradient(90deg, #d9bfe0, #a985b8);
        }
        .hs-psy-fill.tone-coral { background-image: linear-gradient(90deg, #f5a87a, #e87d5e); }
        .hs-psy-fill.tone-blue { background-image: linear-gradient(90deg, #a9cbe4, #6a9ec4); }
        .hs-psy-fill.tone-pink { background-image: linear-gradient(90deg, #f3bfd3, #d88bb0); }
        .hs-psy-fill.tone-gold { background-image: linear-gradient(90deg, #f0d9a0, #d9a44a); }
        .hs-psy-fill.tone-green { background-image: linear-gradient(90deg, #bcd7a8, #7ca86a); }
        .hs-psy-foot {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            margin-top: 12px;
            padding-top: 10px;
            border-top: 1px dashed rgba(240, 195, 155, 0.5);
        }
        .hs-psy-foot:empty { display: none; }
        .hs-tag.hs-psy-tag {
            white-space: normal;
            overflow: visible;
            text-overflow: clip;
            line-height: 1.5;
            padding: 4px 10px;
            border-radius: 9px;
            max-width: 100%;
        }

        /* ========== Hồ sơ nhân vật / Dấu hiệu cơ thể / Thang đo tâm lý ========== */
        .hs-profile-grid {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 8px;
            margin-top: 10px;
        }
        .hs-vital-grid {
            display: grid;
            grid-template-columns: repeat(4, minmax(0, 1fr));
            gap: 8px;
        }
        .hs-female-grid {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 8px;
        }
        .hs-scale-grid {
            display: grid;
            grid-template-columns: repeat(4, minmax(0, 1fr));
            gap: 8px;
        }
        .hs-scale-card {
            padding: 10px 11px 11px;
            border-radius: 12px;
            border: 1px solid rgba(240, 195, 155, 0.42);
            background: linear-gradient(145deg, rgba(255, 252, 248, 0.95), rgba(255, 240, 230, 0.62));
        }
        .hs-scale-card .scale-label {
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.03em;
            color: var(--text-sub);
        }
        .hs-scale-card .scale-value {
            margin-top: 4px;
            font-size: 13px;
            font-weight: 800;
            color: var(--text-main);
            word-break: break-word;
        }
        .hs-scale-notes {
            display: flex;
            flex-direction: column;
            gap: 8px;
            margin-top: 10px;
        }
        .hs-note-row {
            display: flex;
            gap: 10px;
            padding: 10px 12px;
            border-radius: 10px;
            background: rgba(255, 250, 244, 0.55);
            border: 1px solid rgba(240, 195, 155, 0.35);
        }
        .hs-note-row .note-label {
            flex: 0 0 auto;
            min-width: 84px;
            font-size: 11px;
            font-weight: 800;
            letter-spacing: 0.08em;
            color: var(--coral);
        }
        .hs-note-row .note-value {
            flex: 1;
            min-width: 0;
            font-size: 12.5px;
            line-height: 1.6;
            color: var(--text-main);
            word-break: break-word;
        }
        @container (max-width: 640px) {
            .hs-profile-grid, .hs-female-grid, .hs-vital-grid, .hs-scale-grid {
                grid-template-columns: repeat(2, minmax(0, 1fr));
            }
        }
        @container (max-width: 400px) {
            .hs-profile-grid, .hs-female-grid, .hs-vital-grid, .hs-scale-grid {
                grid-template-columns: 1fr;
            }
            .hs-note-row {
                flex-direction: column;
                gap: 4px;
            }
        }

        /* ========== Hồ sơ sinh lý nữ ========== */
        .women-head {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 10px;
            flex-wrap: wrap;
            margin-bottom: 12px;
        }
        .women-clock {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
        }
        .women-clock-item {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 7px 12px;
            border-radius: 12px;
            background: rgba(255, 250, 244, 0.72);
            border: 1px solid rgba(240, 195, 155, 0.45);
        }
        .women-clock-item > span {
            font-size: 13px;
            font-weight: 800;
            letter-spacing: 0.14em;
            color: var(--text-soft);
        }
        .women-clock-item > b {
            font-size: 14px;
            font-weight: 800;
            color: var(--text-main);
            white-space: nowrap;
        }
        .women-clock-item > span { white-space: nowrap; }
        .women-clock-item { min-width: 0; }
        .wf-clock-input {
            width: 112px;
            padding: 2px 6px;
            border-radius: 6px;
            border: 1px solid var(--peach);
            background: #fffaf4;
            color: var(--text-main);
            font-size: 13px;
            font-family: var(--font);
        }
        .women-add { flex-shrink: 0; }
        .woman-card { padding: 12px; }
        .woman-summary { gap: 10px; }
        .woman-badge {
            width: 38px;
            height: 38px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #fff;
            font-size: 16px;
            font-weight: 800;
            background: linear-gradient(135deg, #f8b28a, #e88d68);
            box-shadow: 0 2px 8px rgba(230, 130, 80, 0.35);
            flex-shrink: 0;
        }
        .woman-headline { flex: 1; min-width: 0; }
        .woman-name { font-size: 14px; font-weight: 800; color: var(--text-main); }
        .woman-meta {
            margin-top: 2px;
            font-size: 11px;
            color: var(--text-sub);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .woman-status {
            flex-shrink: 0;
            font-size: 11px;
            font-weight: 700;
            padding: 2px 8px;
            border-radius: 999px;
            border: 1px solid transparent;
        }
        .woman-status.ok { color: #2e8b57; background: rgba(124, 168, 106, 0.16); border-color: rgba(124, 168, 106, 0.35); }
        .woman-status.failed { color: #c0392b; background: rgba(212, 93, 77, 0.14); border-color: rgba(212, 93, 77, 0.35); }
        .woman-status.pending { color: var(--text-soft); background: rgba(240, 170, 120, 0.14); border-color: rgba(240, 170, 120, 0.3); }
        .woman-icon-btn {
            flex-shrink: 0;
            width: 28px;
            height: 26px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 0;
            border: 1px solid rgba(240, 170, 120, 0.45);
            background: rgba(255, 245, 235, 0.85);
            color: var(--text-sub);
            font-size: 13px;
            line-height: 1;
            border-radius: 999px;
            cursor: pointer;
            transition: all var(--transition-base);
        }
        .woman-icon-btn:hover {
            border-color: var(--coral);
            color: var(--coral);
            transform: translateY(-1px);
        }
        .woman-icon-btn.woman-del:hover { border-color: var(--danger); color: var(--danger); }
        .ui-ico { width: 14px; height: 14px; display: block; }
        .field-emoji {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-width: 20px;
            height: 20px;
            padding: 0 4px;
            border-radius: 6px;
            background: rgba(240, 170, 120, 0.2);
            border: 1px solid rgba(240, 170, 120, 0.3);
            font-size: 13px;
            flex-shrink: 0;
        }
        #women-view .women-field .wf-value,
        #women-view .child-cell .child-text { color: #8a1f2b; }
        #men-view .women-field .wf-value,
        #men-view .child-cell .child-text { color: #1f3f7a; }
        #bd-vital-signs .metric-value { color: #1f5f6b; }
        #bd-female-signs .metric-value { color: #6b2f4a; }
        #md-scale-grid .scale-value { color: #3b3a6b; }
        #md-pregpsy-progress .psy-value { color: #7a2f47; }
        #bd-state-traits .hs-meter-value { color: #8a4a2f; }
        #bd-state-current .chip-value {
            background: linear-gradient(90deg, #8a4a2f, #c4573a, #8a4a2f);
            background-size: 200% 100%;
            -webkit-background-clip: text;
            background-clip: text;
            -webkit-text-fill-color: transparent;
            animation: hs-value-flow 6s ease-in-out infinite;
        }
        @keyframes hs-value-flow {
            0%, 100% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
        }
        #md-pregpsy-progress .hs-psy-item.is-accent .psy-value {
            animation: hs-pulse-soft 3s ease-in-out infinite;
        }
        @keyframes hs-pulse-soft {
            0%, 100% { opacity: 0.82; }
            50% { opacity: 1; }
        }
        .wf-edit .ui-ico { width: 12px; height: 12px; }
        .women-group { margin-top: 12px; }
        .women-group-title {
            display: flex;
            align-items: center;
            gap: 8px;
            margin-bottom: 7px;
            font-size: 11px;
            font-weight: 800;
            letter-spacing: 0.12em;
            color: var(--coral);
        }
        .women-group-title::after {
            content: "";
            flex: 1;
            height: 1px;
            background: linear-gradient(90deg, rgba(240, 170, 120, 0.4), rgba(240, 170, 120, 0));
        }
        .women-fields {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 7px;
        }
        .women-field {
            display: flex;
            align-items: flex-start;
            gap: 8px;
            padding: 8px 10px;
            border-radius: 10px;
            background: rgba(255, 250, 244, 0.58);
            border: 1px solid rgba(240, 195, 155, 0.35);
        }
        .women-field .wf-label {
            flex: 0 0 auto;
            width: 140px;
            font-size: 14.3px;
            font-weight: 800;
            line-height: 1.5;
            color: var(--text-sub);
        }
        .women-field .wf-value {
            flex: 1;
            min-width: 0;
            font-size: 13.75px;
            line-height: 1.6;
            color: var(--text-main);
            word-break: break-word;
        }
        .women-field .wf-edit {
            flex-shrink: 0;
            border: none;
            background: transparent;
            cursor: pointer;
            font-size: 12px;
            line-height: 1.4;
            opacity: 0.6;
            padding: 0 2px;
        }
        .women-field .wf-edit:hover { opacity: 1; }
        .women-field .wf-input {
            width: 100%;
            min-height: 54px;
            resize: vertical;
            padding: 5px 7px;
            border-radius: 8px;
            border: 1px solid var(--peach);
            background: #fffaf4;
            color: var(--text-main);
            font-size: 12.5px;
            line-height: 1.55;
            font-family: var(--font);
            outline: none;
        }
        @container (max-width: 560px) {
            .women-fields { grid-template-columns: 1fr; }
            .women-field .wf-label { width: 118px; }
        }

        .woman-presence {
            flex-shrink: 0;
            font-size: 11px;
            font-weight: 700;
            padding: 2px 8px;
            border-radius: 999px;
            border: 1px solid transparent;
        }
        .woman-presence.present { color: #2e6b8b; background: rgba(106, 158, 196, 0.16); border-color: rgba(106, 158, 196, 0.35); }
        .woman-presence.left { color: var(--text-soft); background: rgba(180, 160, 140, 0.18); border-color: rgba(180, 160, 140, 0.35); }

        /* ========== Bảng con cái ========== */
        .children-table {
            border: 1px solid rgba(240, 195, 155, 0.4);
            border-radius: 10px;
            overflow: hidden;
            background: rgba(255, 250, 244, 0.35);
        }
        .child-table-head, .child-row {
            display: grid;
            grid-template-columns: 1.3fr 0.5fr 0.8fr 0.5fr 1fr;
        }
        .child-table-head {
            background: rgba(240, 170, 120, 0.14);
            font-size: 13px;
            font-weight: 800;
            color: var(--text-sub);
        }
        .child-table-head span { padding: 7px 9px; }
        .child-row + .child-row { border-top: 1px solid rgba(240, 195, 155, 0.28); }
        .child-cell {
            display: flex;
            align-items: flex-start;
            gap: 6px;
            padding: 7px 9px;
            min-width: 0;
        }
        .child-cell .child-text {
            flex: 1;
            min-width: 0;
            font-size: 13.75px;
            line-height: 1.6;
            color: var(--text-main);
            word-break: break-word;
        }
        .child-cell .wf-edit {
            border: none;
            background: transparent;
            cursor: pointer;
            font-size: 12px;
            opacity: 0.6;
            padding: 0 2px;
            flex-shrink: 0;
        }
        .child-cell .wf-edit:hover { opacity: 1; }
        .child-cell .wf-input {
            width: 100%;
            min-height: 46px;
            resize: vertical;
            padding: 4px 6px;
            border-radius: 8px;
            border: 1px solid var(--peach);
            background: #fffaf4;
            color: var(--text-main);
            font-size: 12.5px;
            line-height: 1.5;
