    function sanitizeCoT(text) {
        if (!text) return '';
        return text.replace(/^[\s\S]*?<\/(?:think|thinking)>/i, '').trim();
    }
    function extractBlocks(text) {
        const blocks = [];
        let current = '';
        let depth = 0;
        for (let i = 0; i < text.length; i++) {
            const ch = text[i];
            if (ch === '[') {
                if (depth > 0) current += ch;
                depth++;
            } else if (ch === ']') {
                depth--;
                if (depth === 0) {
                    if (current.trim()) blocks.push(current.trim());
                    current = '';
                } else if (depth > 0) {
                    current += ch;
                } else { depth = 0; }
            } else {
                if (depth > 0) current += ch;
            }
        }
        if (depth > 0 && current.trim()) blocks.push(current.trim());
        return blocks;
    }
    function splitParts(blockStr) { return blockStr.split('|').map(s => s.trim()); }
    // Thanh tiến độ / biểu đồ vòng / khối thang đo dùng chung một cách xét:
    // chỉ các giá trị số thuần như “62%”, “khoảng 62%”, “62” mới tính là phần trăm;
    // “12 điểm (nhẹ)”, “8.5cm”, “180ml”, “thai 4 tuần ngày 2” đều xem là văn bản,
    // nếu không sẽ đọc nhầm điểm số, chiều dài, dung tích thành phần trăm rồi vẽ thành thanh tiến độ.
    function parsePercent(str) {
        if (str === null || str === undefined) return null;
        const s = String(str).replace(/\s+/g, '').replace(/^(?:ướctính|ướcchừng|xấpxỉ|khoảng|tầm|chừng|ước|[约≈~～])/i, '').replace(/[%％]$/, '');
        if (!s || s === 'Không') return null;
        if (!/^\d+(?:\.\d+)?$/.test(s)) return null;
        const v = parseFloat(s);
        return Number.isFinite(v) ? Math.max(0, Math.min(100, v)) : null;
    }
    function tagHtml(text, extraClass = '') {
        if (!text || text === 'Không') text = 'Không';
        return `<span class="hs-tag ${extraClass}"><span class="tag-dot"></span>${escapeHtml(text)}</span>`;
    }
    function makeRingHtml(value, label, sublabel = '') {
        const n = parsePercent(value);
        const displayVal = n !== null ? `${Math.round(n)}%` : (value || 'Không');
        return `<div class="hs-flex-wrap" style="gap:10px;align-items:center;">
            <div class="hs-ring" style="--ring-value:${n !== null ? Math.round(n) : 0};">
                <div class="hs-ring-inner">${escapeHtml(displayVal)}</div>
            </div>
            <div>
                <div class="hs-font-sm" style="font-weight:700;">${labelEmoji(label)} ${label}</div>
