    function labelEmoji(label) {
        if (HERO_FIELD_EMOJI[label]) return HERO_FIELD_EMOJI[label];
        const key = String(label || '');
        const keyLower = key.toLowerCase();
        for (const pair of HERO_EMOJI_KEYWORDS) { if (keyLower.includes(pair[0].toLowerCase())) return pair[1]; }
        let sum = 0;
        const s = String(label || '');
        for (let i = 0; i < s.length; i++) sum = (sum + s.charCodeAt(i) * (i + 1)) % 997;
        return HERO_EMOJI_FALLBACK[sum % HERO_EMOJI_FALLBACK.length];
    }

