    function resetHSD() {
        HSD.status = { spaceTime: [], profile: [], charm: [] };
        HSD.privacy = { private: [], state: [], vitals: [], breast: [], excretion: [] };
        HSD.mind = { preference: [], mindScale: [], genetics: [], pregPsy: [], diary: [] };
        HSD.pregnancy = { pregStage: [], gestSac: [], fetus: [], cordPlacenta: [], weight: [], length: [] };
        HSD.delivery = { deliveryState: [], deliveryProgress: [] };
        HSD.femaleOrgans = { bodyImage: [] };
        HSD.clothing = { clothes: [] };
        HSD.children = [];
        HSD.medical = { ultrasound: [], doctorComment: [] };
    }

    function parseHeroineStatus(rawText) {
        resetHSD();
        const cleaned = sanitizeCoT(rawText);
        const blocks = extractBlocks(cleaned);
        let currentModule = null;
        blocks.forEach(block => {
            const parts = splitParts(block);
            const header = parts[0];
            const isModuleTag = parts.length === 1 && MODULE_TAGS.includes(header);
            if (isModuleTag) { currentModule = header; return; }
            if (header === 'Child' && parts.length >= 2) {
                HSD.children.push(parts.slice(1));
                return;
            }
            if (MODULE_MAP[header]) {
                const [section, field] = MODULE_MAP[header];
                HSD[section][field] = parts.slice(1);
            }
        });
        fixHeroineCycleDates();
    }
    // SpaceTime: 0 Ngày, 5 Ngày kinh cuối, 6 Dự đoán rụng trứng, 7 Khoảng nguy hiểm; Profile: 16 Số ngày chu kỳ chuẩn
    function fixHeroineCycleDates() {
        const st = HSD.status && HSD.status.spaceTime;
        if (!Array.isArray(st) || !st.length) return;
        const prof = (HSD.status && HSD.status.profile) || [];
        fixCycleDates(st, { cycle: -1, lmp: 5, ovu: 6, danger: 7 }, st[0], prof[16]);
    }

    // ==================== Hàm render (đã chuyển) ====================
    // Bản lưu cũ (phiên bản ít trường hơn) sau khi đọc được bù đủ số trường hiện tại, đảm bảo trường mới hiển thị “Không” mà không bị xô lệch
    function padRows() {
        HSD.privacy.vitals = HSD.privacy.vitals || [];
        HSD.mind.mindScale = HSD.mind.mindScale || [];
        if (HSD.status.spaceTime.length > 0 && HSD.status.spaceTime.length < 10) HSD.status.spaceTime = padRowAt(HSD.status.spaceTime, [6, 7]);
        if (HSD.status.profile.length === 8) {
            const p = HSD.status.profile;
            HSD.status.profile = [p[0], p[1], p[2], p[3], p[4], 'Không', 'Không', p[5], p[6], 'Không', 'Không', 'Không', 'Không', 'Không', 'Không', 'Không', p[7]];
        }
        if (HSD.status.profile.length > 0 && HSD.status.profile.length < 20) HSD.status.profile = HSD.status.profile.concat(Array(20 - HSD.status.profile.length).fill('Không'));
        const legacyState = HSD.privacy.state;
        if (legacyState.length === 14) {
            HSD.privacy.state = [legacyState[0], legacyState[1], legacyState[2], 'Không', legacyState[3], 'Không', 'Không'];
            if (HSD.privacy.vitals.length === 0) {
                HSD.privacy.vitals = [
                    'Không', 'Không', 'Không', 'Không', 'Không', 'Không', 'Không', 'Không',
                    'Không', 'Không', 'Không',
                    legacyState[6], legacyState[7], 'Không',
                    legacyState[8], legacyState[9], legacyState[10],
                    'Không', 'Không', 'Không',
                    legacyState[11], legacyState[12], legacyState[13]
                ];
            }
        }
        if (HSD.privacy.state.length > 0 && HSD.privacy.state.length < 7) HSD.privacy.state = HSD.privacy.state.concat(Array(7 - HSD.privacy.state.length).fill('Không'));
        if (HSD.privacy.vitals.length > 0 && HSD.privacy.vitals.length < 23) HSD.privacy.vitals = HSD.privacy.vitals.concat(Array(23 - HSD.privacy.vitals.length).fill('Không'));
        if (HSD.mind.mindScale.length > 0 && HSD.mind.mindScale.length < 11) HSD.mind.mindScale = HSD.mind.mindScale.concat(Array(11 - HSD.mind.mindScale.length).fill('Không'));
        if (HSD.mind.preference.length > 0 && HSD.mind.preference.length < 9) HSD.mind.preference = padRowAt(HSD.mind.preference, [2, 3, 4]);
        if (HSD.mind.genetics.length > 0 && HSD.mind.genetics.length < 4) HSD.mind.genetics = HSD.mind.genetics.concat(['Không', 'Không']);
        if (HSD.mind.pregPsy.length > 0 && HSD.mind.pregPsy.length < 9) HSD.mind.pregPsy = padRowAt(HSD.mind.pregPsy, [5]);
        if (HSD.medical.doctorComment.length > 0 && HSD.medical.doctorComment.length < 9) HSD.medical.doctorComment = padRowAt(HSD.medical.doctorComment, [8]);
        if (HSD.children && HSD.children.length) HSD.children = HSD.children.map(c => c.length < 16 ? padRowAt(c, [15]) : c);
    }
    function padRowAt(arr, indexes) {
        const out = arr.slice();
        indexes.forEach((idx, i) => out.splice(idx, 0, 'Không'));
        return out;
    }

