                ${makeStatNumberCardHtml('Thời gian kéo dài', ds[4])}
                ${makeStatNumberCardHtml('Khoảng cách cơn co', ds[5] || 'Không')}
                ${makeStatNumberCardHtml('Nguồn sức rặn', ds[6] || 'Không')}`;
        }
        const dvTags = qs('#dv-state-tags');
        if (dvTags && ds.length >= 7) {
            dvTags.innerHTML = `
                ${tagHtml('Cơn co: ' + (ds[5] || 'Không'), 'hs-tag--gold')}
                ${tagHtml('Nguồn sức rặn: ' + (ds[6] || 'Không'))}`;
        }
        const dpTimeline = qs('#dv-progress-timeline');
        if (dpTimeline && dp.length >= 3) {
            dpTimeline.innerHTML = `<div class="hs-timeline">
                ${makeTimelineItemHtml('<strong>Đã sinh:</strong> ' + (dp[0] || 'Không'), true)}
                ${makeTimelineItemHtml('<strong>Đang sinh:</strong> ' + (dp[1] || 'Không'))}
                ${makeTimelineItemHtml('<strong>Đã lọt khung chờ sinh:</strong> ' + (dp[2] || 'Không'))}
            </div>`;
