    function renderFemaleOrgans() {
        const bi = HSD.femaleOrgans.bodyImage;
        const grid = qs('#fo-bodyimage-timeline');
        const actualOrder = [
            ['👄 Khoang miệng', 14, 15], ['🧴 Dạ dày', 16, 17], ['🍼 Tuyến vú', 26, 27], ['🍒 Núm vú', 24, 25],
            ['🦴 Vùng chậu', 0, 1], ['🕯️ Buồng tử cung', 8, 9], ['🌊 Vòi trứng', 10, 11], ['🥚 buồng trứng', 12, 13],
            ['🚰 Bàng quang', 22, 23], ['🦋 Âm hộ', 2, 3], ['🌸 Âm vật', 4, 5], ['🌙 Vòm âm đạo', 6, 7],
            ['🍩 Hậu môn', 18, 19], ['🦶 Bàn chân', 20, 21]
        ];
        if (grid && bi.length >= 28) {
            grid.innerHTML = `<div class="hs-grid-3">` + actualOrder.map(([name, imgIdx, feelIdx]) => {
                return makeBodyPartCardHtml(name, bi[imgIdx] || 'Không', bi[feelIdx] || 'Không', 'hs-title-lg');
            }).join('') + `</div>`;
        } else if (grid && bi.length > 0) {
            const available = [];
            for (let i = 0; i + 1 < bi.length; i += 2) {
                available.push(makeBodyPartCardHtml(`Vị trí ${Math.floor(i/2)+1}`, bi[i] || 'Không', bi[i+1] || 'Không', 'hs-title-lg'));
            }
            grid.innerHTML = `<div class="hs-grid-3">` + available.join('') + `</div>`;
        }
    }

    function renderClothing() {
