    function renderChildren() {
        const list = qs('#ch-children-list');
        if (list) {
            if (!HSD.children || HSD.children.length === 0) {
                list.innerHTML = `<div class="hs-empty">Chưa có hồ sơ con cái</div>`;
                return;
            }
            list.innerHTML = HSD.children.map((child) => {
                const [name, gender, age, race, father, bloodType, fertDate, implantDate, birthDate, lookGene, talentGene, charGene, rebel, momLove, childView, momView] = child;
                return `<div class="hs-child-card">
                    <div class="hs-child-summary">
                        <div class="hs-avatar-placeholder">${escapeHtml(name ? name.substring(0,1) : 'C')}</div>
                        <div style="flex:1;min-width:min(100%,160px);">
                            <div class="hs-glow-number" style="font-size:16px;">${escapeHtml(name || 'Không')}</div>
                            <div class="hs-font-sm hs-text-sub">${escapeHtml(gender || 'Không')} · ${escapeHtml(age || 'Không')} tuổi · ${escapeHtml(race || 'Không')}</div>
                        </div>
                        ${tagHtml('Cha ruột: ' + (father || 'Không'), 'hs-tag--gold')}
                        ${tagHtml('Nhóm máu: ' + (bloodType || 'Không'))}
                        <i class="fas fa-chevron-down hs-child-chevron"></i>
                    </div>
                    <div class="hs-child-details">
                        <div class="hs-timeline" style="margin-top:10px;">
                            ${makeTimelineItemHtml('Ngày thụ tinh: ' + (fertDate || 'Không'), true)}
                            ${makeTimelineItemHtml('Ngày làm tổ: ' + (implantDate || 'Không'))}
                            ${makeTimelineItemHtml('Ngày sinh: ' + (birthDate || 'Không'))}
                        </div>
                        <div class="hs-flex-wrap" style="margin-top:10px;">
                            ${tagHtml('Ngoại hình: ' + (lookGene || 'Không'), 'hs-tag--pink')}
                            ${tagHtml('Năng khiếu: ' + (talentGene || 'Không'), 'hs-tag--gold')}
                            ${tagHtml('Tính cách: ' + (charGene || 'Không'), 'hs-tag--blue')}
                        </div>
                        <div class="hs-grid-2" style="margin-top:10px;">
                            ${makeFlatStatHtml('', 'Tâm lý nổi loạn', rebel)}
                            ${makeFlatStatHtml('', 'Tâm lý luyến mẹ', momLove)}
                        </div>
                        <div style="margin-top:10px;">
                            <div class="hs-inline-label">Cách con nhìn nhận mẹ</div>
                            <div class="hs-paragraph">${escapeHtml(childView || 'Không')}</div>
                            <div class="hs-inline-label" style="margin-top:10px;">Cách mẹ nhìn nhận đứa con này</div>
                            <div class="hs-paragraph">${escapeHtml(momView || 'Không')}</div>
                        </div>
                    </div>
                </div>`;
            }).join('');
            list.querySelectorAll('.hs-child-summary').forEach(summary => {
                summary.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const card = summary.closest('.hs-child-card');
                    if (card) card.classList.toggle('expanded');
                });
            });
        }
    }

