    // ==================== Khởi tạo tab ====================
    function initTabs() {
        const seen = new Set();
        const buttons = Array.from(qsa('.hs-tab-btn')).filter(btn => {
            const key = btn.getAttribute('data-tab');
            if (seen.has(key)) { btn.remove(); return false; }
            seen.add(key);
            return true;
        });
        const panels = qsa('.hs-tab-panel');
        buttons.forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                buttons.forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                const target = btn.getAttribute('data-tab');
                panels.forEach(p => p.classList.remove('active'));
                const panel = qs('#panel-' + target);
                if (panel) panel.classList.add('active');
            });
        });
    }

    function initChartToggles() {
        const toggles = qsa('.hs-chart-toggle');
        toggles.forEach(toggle => {
            toggle.addEventListener('click', (e) => {
                e.stopPropagation();
                const card = toggle.closest('.hs-collapsible-chart');
                if (card) card.classList.toggle('expanded');
            });
        });
    }

