    let configMigrationWarned = false;
    function getConfig() {
        try {
            const raw = localStorage.getItem(CONFIG_KEY);
            if (raw) {
                const stored = JSON.parse(raw);
                // Phiên bản cũ lưu URL Chat Completions đầy đủ, chuyển thành URL gốc URL
                if (stored && !stored.baseUrl && stored.chatUrl) {
                    stored.baseUrl = normalizeBaseUrl(stored.chatUrl);
                    const oldUrl = String(stored.chatUrl).trim();
                    if (!configMigrationWarned && (oldUrl.includes('?') || !/\/chat\/completions\/?$/i.test(oldUrl))) {
                        configMigrationWarned = true;
                        console.warn('[Thanh trạng thái nữ chính] Địa chỉ API bản cũ “' + oldUrl + '” đã chuyển thành URL gốc “' + stored.baseUrl + '”, hãy kiểm tra lại trong cài đặt.');
                    }
                }
                return { ...DEFAULT_API_FIELDS, ...stored };
            }
        } catch (e) {}
        return {
            ...DEFAULT_API_FIELDS,
            apiKey: '',
            model: 'deepseek-chat',
            maxTokens: 8000
        };
    }
