    function makeSnapshot(raw, time) {
        return { raw, time: time || new Date().toLocaleString('vi-VN', { hour: '2-digit', minute: '2-digit' }) };
    }

    // Xét một bản lưu có “nội dung” hay không: hồ sơ nam/nữ xem có trường thực tế không, thanh trạng thái xem có giá trị khác -/Không không
    function isMeaningfulRaw(raw) {
        const s = String(raw == null ? '' : raw).trim();
        if (!s) return false;
        if (s.charAt(0) === '{') {
            try {
                const data = JSON.parse(s);
                const list = Array.isArray(data.women) ? data.women : (Array.isArray(data.men) ? data.men : null);
                if (!list) return false;
                return list.some(person => {
                    if (!person) return false;
                    if (person.status === 'ok') return true;
                    const fields = Array.isArray(person.fields) ? person.fields : [];
                    return fields.some((v, i) => {
                        if (i === 0) return false;   // chỉ có họ tên, còn lại toàn “Không”= = chưa từng đồng bộ, không tính là có nội dung
                        const t = String(v == null ? '' : v).trim();
                        return t && t !== '-' && t !== 'Không' && t !== 'Chưa đồng bộ';
                    });
                });
            } catch (e) { return false; }
        }
        const lines = s.split(/\r?\n/);
        for (const line of lines) {
            const m = line.match(/^\s*\[([A-Za-z]+)\|(.*)\]\s*$/);
            if (!m) continue;
            const cells = m[2].split('|').map(x => x.trim());
            if (cells.some(c => c && c !== '-' && c !== 'Không' && c !== 'Chưa đồng bộ')) return true;
        }
        return false;
    }

    // Chỉ đưa dữ liệu cũ có nội dung vào dòng thời gian; bản lưu trống và snapshot giống bản cuối đều bỏ qua
    function pushSnapshot(raw) {
        if (!isMeaningfulRaw(raw)) return false;
        try {
            const history = getHistory();
            const last = history[history.length - 1];
            if (last && last.raw === raw) return false;
            history.push(makeSnapshot(raw));
            while (history.length > 9) history.shift();
            saveHistory(history);
            return true;
        } catch (e) { return false; }
    }

    // Chuẩn hóa endpoint tùy chỉnh: bỏ khoảng trắng, query string, dấu gạch chéo cuối; nếu điền nhầm đường dẫn đầy đủ thì bỏ /chat/completions, /completions,/models
    function normalizeBaseUrl(input) {
        let url = String(input || '').trim().replace(/[?#].*$/, '').replace(/\/+$/, '');
        url = url.replace(/\/(chat\/completions|completions|models)$/i, '').replace(/\/+$/, '');
        return url;
    }
    // Giống “Tùy chỉnh (tương thích OpenAI)” của Tavern: URL gốc + hậu tố cố định
    function getChatUrl(cfg) {
        const base = normalizeBaseUrl(cfg && cfg.baseUrl);
        return base ? base + '/chat/completions' : '';
    }
    function getModelsUrl(cfg) {
        const base = normalizeBaseUrl(cfg && cfg.baseUrl);
        return base ? base + '/models' : '';
    }

    function loadConfigToUI() {
        const cfg = getConfig();
        qs('#cfg-api-mode').value = API_MODES.includes(cfg.apiMode) ? cfg.apiMode : 'preset';
        qs('#cfg-preset-api').value = cfg.presetApi === 'custom' ? 'custom' : 'main';
        qs('#cfg-preset-context').value = cfg.presetContext === 'preset' ? 'preset' : 'script';
        qs('#cfg-preset-format').value = cfg.presetFormat === 'off' ? 'off' : 'builtin';
        qs('#cfg-preset-run').value = cfg.presetRun === 'helper' ? 'helper' : 'native';
        renderPresetOptions(cfg.presetName || '');
        renderProfileOptions(cfg.profileId || '');
        updateApiModeUI();
        qs('#cfg-base-url').value = normalizeBaseUrl(cfg.baseUrl) || DEFAULT_BASE_URL;
        qs('#cfg-api-key').value = cfg.apiKey || '';
        qs('#cfg-model-name').value = cfg.model || 'deepseek-chat';
        qs('#cfg-max-tokens').value = cfg.maxTokens || readBuiltinPresetSetting('max_completion_tokens') || 12000;
        qs('#cfg-jailbreak-prompt').value = cfg.jailbreakPrompt || '';
        qs('#cfg-disable-reasoning').checked = cfg.disableReasoning !== false;
        qs('#cfg-auto-sync').checked = cfg.autoSync === true;
        qs('#cfg-auto-feedback').checked = cfg.autoFeedback === true;
        qs('#cfg-auto-feedback-content').value = AUTO_FEEDBACK_CONTENTS.includes(cfg.autoFeedbackContent) ? cfg.autoFeedbackContent : 'both';
        qs('#cfg-auto-feedback-mode').value = cfg.autoFeedbackMode === 'append' ? 'append' : 'inject';
        updateAutomationUI();
        updateFooterInfo();
    }

    // Thẻ tự động hóa: chỉ hiện hai ô chọn khi đã tích “Tự động kèm phản hồi khi gửi”
    function updateAutomationUI() {
        const opts = qs('#cfg-auto-feedback-options');
        if (opts) opts.style.display = qs('#cfg-auto-feedback').checked ? '' : 'none';
    }

    function collectConfigFromUI() {
        return {
            apiMode: API_MODES.includes(qs('#cfg-api-mode').value) ? qs('#cfg-api-mode').value : 'preset',
            presetName: qs('#cfg-preset-select').value || '',
            presetApi: qs('#cfg-preset-api').value === 'custom' ? 'custom' : 'main',
            presetContext: qs('#cfg-preset-context').value === 'preset' ? 'preset' : 'script',
            presetFormat: qs('#cfg-preset-format').value === 'off' ? 'off' : 'builtin',
            presetRun: qs('#cfg-preset-run').value === 'helper' ? 'helper' : 'native',
            profileId: qs('#cfg-profile-select').value || '',
            baseUrl: normalizeBaseUrl(qs('#cfg-base-url').value) || DEFAULT_BASE_URL,
            apiKey: qs('#cfg-api-key').value.trim(),
            model: qs('#cfg-model-name').value.trim() || 'deepseek-chat',
            maxTokens: parseInt(qs('#cfg-max-tokens').value, 10) || 8000,
            jailbreakPrompt: qs('#cfg-jailbreak-prompt').value,
            disableReasoning: qs('#cfg-disable-reasoning').checked,
            autoSync: qs('#cfg-auto-sync').checked,
            autoFeedback: qs('#cfg-auto-feedback').checked,
            autoFeedbackContent: AUTO_FEEDBACK_CONTENTS.includes(qs('#cfg-auto-feedback-content').value) ? qs('#cfg-auto-feedback-content').value : 'both',
            autoFeedbackMode: qs('#cfg-auto-feedback-mode').value === 'append' ? 'append' : 'inject'
        };
    }

    // Hàm đồng bộ lấy cấu hình: khi tự động đồng bộ dùng syncCfgOverride (cấu hình đã lưu), ngược lại đọc giao diện
    function getSyncConfig() {
        return syncCfgOverride ? { ...syncCfgOverride } : collectConfigFromUI();
    }

    // selector mặc định là thanh trạng thái trong thẻ API tùy chỉnh; kiểm tra preset/cấu hình kết nối dùng #mode-connection-status
    function setConnectionStatus(type, message, selector = '#connection-status') {
        const el = qs(selector);
        if (!el) return;
        el.style.display = 'flex';
        el.className = 'connection-status ' + type;
        const icons = { success: 'fa-check-circle', error: 'fa-times-circle', info: 'fa-info-circle' };
        el.innerHTML = `<i class="fas ${icons[type] || 'fa-info-circle'}"></i> ${message}`;
        replaceIcons();
    }
    function hideConnectionStatus(selector = '#connection-status') {
        const el = qs(selector);
        if (el) el.style.display = 'none';
    }

    // ==================== API - Gọi ====================
    async function apiRequest(url, options) {
        const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
        const timer = controller ? setTimeout(() => controller.abort(), 180000) : null;
        let response;
        try {
            response = await fetch(url, { ...options, signal: controller ? controller.signal : options?.signal });
        } catch (e) {
            if (e && e.name === 'AbortError') throw new Error('Hết thời gian yêu cầu (180 giây): địa chỉ API không phản hồi hoặc mạng bị gián đoạn');
            throw e;
        } finally {
            if (timer) clearTimeout(timer);
        }
        const text = await response.text();
        let data = null;
        try {
            data = text ? JSON.parse(text) : null;
        } catch (e) {
            const preview = String(text || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 120);
            throw new Error(`HTTP ${response.status} trả về không phải JSON${preview ? '（' + preview + ')' : ''}`);
        }
        if (!response.ok) {
            const errDetail = data?.error?.message || data?.message || String(text || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 180);
            throw new Error(`HTTP ${response.status} ${errDetail || 'Yêu cầu thất bại'}`);
        }
        return data;
    }

    // ==================== Cấu hình kết nối Tavern ====================
    const escapeHtml = (str) => String(str ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

    function getSTContext() {
        try {
            if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) return SillyTavern.getContext();
        } catch (e) {}
        try {
            const pw = window.parent;
            if (pw && pw.SillyTavern && pw.SillyTavern.getContext) return pw.SillyTavern.getContext();
        } catch (e) {}
        return null;
    }

    function getConnectionService() {
        const ctx = getSTContext();
        if (!ctx) throw new Error('Không truy cập được ngữ cảnh Tavern');
        if (ctx.extensionSettings?.disabledExtensions?.includes('connection-manager')) {
            throw new Error('Tiện ích “Connection Manager” của Tavern đã bị tắt');
        }
        const svc = ctx.ConnectionManagerRequestService;
        if (!svc || typeof svc.sendRequest !== 'function') {
            throw new Error('Phiên bản Tavern hiện tại không hỗ trợ gọi cấu hình kết nối, hãy cập nhật Tavern hoặc chuyển sang tùy chỉnh API');
        }
        return { ctx, svc };
    }

    function getSupportedProfilesSafe() {
        try {
            const { ctx, svc } = getConnectionService();
            if (typeof svc.getSupportedProfiles === 'function') return svc.getSupportedProfiles() || [];
            return ctx.extensionSettings?.connectionManager?.profiles || [];
        } catch (e) {
            return [];
        }
    }

    // profileId trống thì theo cấu hình kết nối Tavern đang chọn
    function resolveProfile(profileId) {
        const { ctx, svc } = getConnectionService();
        const id = profileId || ctx.extensionSettings?.connectionManager?.selectedProfile;
        if (!id) throw new Error('Tavern hiện chưa chọn cấu hình kết nối nào, hãy chỉ định một cái trong cài đặt');
        const profile = (ctx.extensionSettings?.connectionManager?.profiles || []).find(p => p.id === id);
        if (!profile) throw new Error('Cấu hình kết nối đã chọn không tồn tại, có thể đã bị xóa, hãy chọn lại');
        if (typeof svc.isProfileSupported === 'function' && !svc.isProfileSupported(profile)) {
            throw new Error(`Cấu hình kết nối “${profile.name}” có loại API không được hỗ trợ (chỉ hỗ trợ Chat Completion / Text Completion)`);
        }
        return { svc, profile };
    }

    // Yêu cầu thực tế gần nhất đã gửi, dùng cho nhật ký nhà phát triển; không chứa API key
    let lastRequestPayload = null;

    async function requestViaProfile(profileId, messages, maxTokens, { includePreset = true, includeInstruct = true } = {}) {
        const { svc, profile } = resolveProfile(profileId);
        // Cấu hình Text Completion cần ghép thành chuỗi theo mẫu instruct trong cấu hình, Chat Completion thì trả nguyên mảng tin nhắn
        const prompt = typeof svc.constructPrompt === 'function' ? svc.constructPrompt(messages, profile.id) : messages;
        lastRequestPayload = { via: 'Cấu hình kết nối Tavern', profile: profile.name, api: profile.api, model: profile.model, maxTokens, prompt };
        try {
            const res = await svc.sendRequest(profile.id, prompt, maxTokens, {
                stream: false,
                extractData: true,
                includePreset,
                includeInstruct
            });
            return typeof res === 'string' ? res : (res?.content || '');
        } catch (err) {
            throw new Error(err?.cause?.message || err?.message || String(err));
        }
    }

    function describeProfile(profile) {
        const parts = [profile.api, profile.model].filter(Boolean).map(escapeHtml);
        return `“${escapeHtml(profile.name)}”${parts.length ? ' · ' + parts.join(' / ') : ''}`;
    }

    function renderProfileOptions(selectedId) {
        const select = qs('#cfg-profile-select');
        if (!select) return;
        const profiles = getSupportedProfilesSafe();
        const currentId = getSTContext()?.extensionSettings?.connectionManager?.selectedProfile;
        const current = profiles.find(p => p.id === currentId);
        const opts = [`<option value="">Theo cấu hình hiện tại của Tavern ${current ? '（' + escapeHtml(current.name) + ')' : ''}</option>`];
        profiles.forEach(p => {
            opts.push(`<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)}${p.model ? ' · ' + escapeHtml(p.model) : ''}</option>`);
        });
        if (selectedId && !profiles.some(p => p.id === selectedId)) {
            opts.push(`<option value="${escapeHtml(selectedId)}">(cấu hình đã mất hiệu lực)</option>`);
        }
        select.innerHTML = opts.join('');
        select.value = selectedId || '';
        updateProfileHint();
    }

    function updateProfileHint() {
        const hint = qs('#cfg-profile-hint');
        if (!hint) return;
        try {
            const { profile } = resolveProfile(qs('#cfg-profile-select').value || '');
            hint.className = 'form-hint';
            hint.innerHTML = `Sẽ dùng ${describeProfile(profile)}, key, địa chỉ và preset đều theo cài đặt trong Tavern.`;
        } catch (err) {
            hint.className = 'form-hint error';
            hint.textContent = err.message;
        }
    }

    // ==================== Preset Chat Completion của Tavern (Tavern Helper generate) ====================
    // Trong script Tavern Helper các hàm này là toàn cục; dự phòng lấy từ TavernHelper của cửa sổ cha
    function getHelperFn(name) {
        try {
            if (typeof window[name] === 'function') return window[name];
        } catch (e) {}
        try {
            const fn = window.parent?.TavernHelper?.[name];
            if (typeof fn === 'function') return fn;
        } catch (e) {}
        return null;
    }

    function getPresetNamesSafe() {
        try {
            const fn = getHelperFn('getPresetNames');
            return fn ? (fn() || []).filter(n => n !== 'in_use') : [];
        } catch (e) {
            return [];
        }
    }

    function getLoadedPresetNameSafe() {
        try {
            const fn = getHelperFn('getLoadedPresetName');
            return fn ? (fn() || '') : '';
        } catch (e) {
            return '';
        }
    }

    // presetName trống thì dùng preset Tavern đang sử dụng ('in_use'）
    function resolvePreset(presetName) {
        const generateFn = getHelperFn('generate');
        if (!generateFn) throw new Error('Không phát hiện giao diện generate của Tavern Helper, hãy chắc chắn đã cài và bật Tavern Helper');
        if (presetName && presetName !== BUILTIN_PRESET_NAME && !getPresetNamesSafe().includes(presetName)) {
            throw new Error(`Preset “${presetName}” không tồn tại, có thể đã bị đổi tên hoặc xóa, hãy chọn lại`);
        }
        return { generateFn, label: presetName || `Preset hiện tại (${getLoadedPresetNameSafe() || 'chưa lưu'}）` };
    }

    // Cài preset tích hợp; replace là true thì ghi đè preset cùng tên. Trả về có ghi hay không
    async function installBuiltinPreset(replace = false) {
        const fnName = replace ? 'createOrReplacePreset' : 'createPreset';
        const fn = getHelperFn(fnName);
        if (!fn) throw new Error(`Không phát hiện giao diện ${fnName} của Tavern Helper, hãy cập nhật Tavern Helper`);
        if (!replace && getPresetNamesSafe().includes(BUILTIN_PRESET_NAME)) return false;
        await fn(BUILTIN_PRESET_NAME, JSON.parse(JSON.stringify(BUILTIN_PRESET)));
        return true;
    }

    function readBuiltinPreset() {
        try {
            const fn = getHelperFn('getPreset');
            return fn ? fn(BUILTIN_PRESET_NAME) : null;
        } catch (e) {
            return null;
        }
    }

    function readBuiltinPresetSetting(key) {
        const preset = readBuiltinPreset();
        return preset && preset.settings ? preset.settings[key] : undefined;
    }

    // Preset riêng của script theo “Token tối đa / Tắt suy nghĩ của mô hình” trong cài đặt; preset của người dùng tuyệt đối không động vào
    async function syncBuiltinPresetSettings(cfg) {
        if (!cfg || cfg.apiMode !== 'preset' || cfg.presetName !== BUILTIN_PRESET_NAME) return null;
        const writeFn = getHelperFn('createOrReplacePreset');
        const preset = readBuiltinPreset();
        if (!writeFn || !preset || !preset.settings) return null;
        const settings = { ...preset.settings };
        const before = {
            reasoning_effort: settings.reasoning_effort,
            max_completion_tokens: settings.max_completion_tokens
        };
        let changed = false;
        if (cfg.disableReasoning !== false && settings.reasoning_effort !== 'none') {
            settings.reasoning_effort = 'none';
            changed = true;
        }
        if (Number.isFinite(cfg.maxTokens) && cfg.maxTokens > 0 && settings.max_completion_tokens !== cfg.maxTokens) {
            settings.max_completion_tokens = cfg.maxTokens;
            changed = true;
        }
        if (!changed) return { changed: false, ...before };
        try {
            await writeFn(BUILTIN_PRESET_NAME, { ...preset, settings });
            if (getLoadedPresetNameSafe() === BUILTIN_PRESET_NAME) {
                try {
                    await switchLoadedPreset(BUILTIN_PRESET_NAME);
                } catch (e) {
                    console.warn('[Thanh trạng thái nữ chính] Tải lại preset tích hợp thất bại', e);
                }
            }
        } catch (e) {
            console.warn('[Thanh trạng thái nữ chính] Ghi thiết lập preset tích hợp thất bại', e);
            return null;
        }
        return {
            changed: true,
            before,
            after: {
                reasoning_effort: settings.reasoning_effort,
                max_completion_tokens: settings.max_completion_tokens
            }
        };
    }

    async function ensureBuiltinPresetSafe() {
        try {
            return await installBuiltinPreset(false);
        } catch (e) {
            console.warn('[Thanh trạng thái nữ chính] Cài preset tích hợp thất bại', e);
            return false;
        }
    }

    // Các mục trong preset tích hợp chỉ lo định dạng đầu ra; ưu tiên đọc preset đã cài, giữ các sửa đổi của người dùng trong Tavern
    const BUILTIN_FORMAT_PROMPT_IDS = ['hs_format_rules', 'jailbreak'];
    function getBuiltinFormatText() {
        let prompts = BUILTIN_PRESET.prompts;
        try {
            const fn = getHelperFn('getPreset');
            if (fn && getPresetNamesSafe().includes(BUILTIN_PRESET_NAME)) prompts = fn(BUILTIN_PRESET_NAME).prompts || prompts;
        } catch (e) {}
        return BUILTIN_FORMAT_PROMPT_IDS
            .map(id => prompts.find(p => p.id === id) || BUILTIN_PRESET.prompts.find(p => p.id === id))
            .map(p => String(p?.content || '').trim())
            .filter(Boolean)
            .join('\n\n');
    }

    // Khi chọn preset khác có nối thêm quy tắc định dạng tích hợp không
    const usesBuiltinFormat = (cfg) => cfg.presetName !== BUILTIN_PRESET_NAME && cfg.presetFormat !== 'off';

    // Chuyển preset hiện tại của Tavern và đợi Tavern áp dụng xong nội dung preset
    function switchLoadedPreset(name) {
        const loadFn = getHelperFn('loadPreset');
        if (!loadFn) throw new Error('Không phát hiện giao diện loadPreset của Tavern Helper, hãy cập nhật Tavern Helper hoặc chuyển sang “Gọi trực tiếp”');
        const ctx = getSTContext();
        const evt = ctx?.eventTypes?.OAI_PRESET_CHANGED_AFTER;
        return new Promise((resolve, reject) => {
            let done = false;
            const finish = () => { if (!done) { done = true; resolve(); } };
            if (ctx?.eventSource && evt) ctx.eventSource.once(evt, finish);
            if (!loadFn(name)) { done = true; reject(new Error(`Chuyển sang preset “${name}” thất bại`)); return; }
            // Thăm dò xác nhận preset đã chuyển, chờ tối đa 1.2 giây; không còn đợi cứng 5 giây
            const started = Date.now();
            const tick = () => {
                if (done) return;
                if (getLoadedPresetNameSafe() === name) return finish();
                if (Date.now() - started >= 1200) return finish();
                setTimeout(tick, 40);
            };
            setTimeout(tick, 0);
        });
    }

    // Preset hiện tại có sửa đổi chưa lưu không: chuyển preset sẽ bỏ các sửa đổi này, vì vậy phát hiện thì không chuyển
    // chỉ dùng làm phán đoán dự phòng cho Tavern Helper bản cũ (thiếu getPreset / replacePreset, không khôi phục snapshot được)
    function hasUnsavedPresetChanges(loadedName) {
        const getFn = getHelperFn('getPreset');
        // Không xét được thì không chặn: trước đây không lấy được in_use thì coi là “có sửa đổi chưa lưu”,
        // kết quả là chạy gốc không bao giờ chuyển được, chỉ có thể lùi về gọi trực tiếp.
        if (!getFn || !loadedName) return false;
        // Preset tích hợp do script tự quản (mỗi lần đồng bộ đều ghi settings), không tham gia phán đoán này
        if (loadedName === BUILTIN_PRESET_NAME) return false;
        try {
            const live = getFn('in_use');
            const stored = getFn(loadedName);
            if (!live || !stored) return false;
            const pick = (p) => JSON.stringify({ settings: p.settings, prompts: p.prompts });
            return pick(live) !== pick(stored);
        } catch (e) {
            return false;
        }
    }

    // Liệt kê khác biệt giữa preset in_use và preset đã lưu (settings và prompts) để chẩn đoán; giống hệt thì trả về mảng rỗng
    const PRESET_DIFF_MAX = 20;
    function diffPresets(live, stored) {
        const out = [];
        const short = (v) => {
            let s;
            try { s = v === undefined ? 'undefined' : JSON.stringify(v); } catch (e) { s = String(v); }
            if (s === undefined) s = String(v);
            return s.length > 60 ? s.slice(0, 60) + '…' : s;
        };
        const same = (a, b) => {
            try { return JSON.stringify(a) === JSON.stringify(b); } catch (e) { return a === b; }
        };
        const ls = (live && live.settings) || {};
        const ss = (stored && stored.settings) || {};
        new Set([...Object.keys(ls), ...Object.keys(ss)]).forEach(k => {
            if (!same(ls[k], ss[k])) out.push(`settings.${k}: ${short(ss[k])} → ${short(ls[k])}`);
        });
        const lp = Array.isArray(live && live.prompts) ? live.prompts : [];
        const sp = Array.isArray(stored && stored.prompts) ? stored.prompts : [];
        const nameOf = (p) => (p && (p.name || p.id)) || '?';
        const lMap = new Map(lp.map(p => [p && p.id, p]));
        const sMap = new Map(sp.map(p => [p && p.id, p]));
        sp.forEach(p => { if (!lMap.has(p && p.id)) out.push(`Thiếu mục “${nameOf(p)}”`); });
        lp.forEach(p => { if (!sMap.has(p && p.id)) out.push(`Thừa mục “${nameOf(p)}”`); });
        const lOrder = lp.map(p => p && p.id).filter(id => sMap.has(id));
        const sOrder = sp.map(p => p && p.id).filter(id => lMap.has(id));
        if (!same(lOrder, sOrder)) out.push('Thứ tự mục khác nhau');
        sp.forEach(s => {
            const l = lMap.get(s && s.id);
            if (!l) return;
            new Set([...Object.keys(s), ...Object.keys(l)]).forEach(k => {
                if (same(l[k], s[k])) return;
                if (k === 'content') {
                    out.push(`Mục “${nameOf(s)}” content khác (độ dài ${String(s[k] ?? '').length} → ${String(l[k] ?? '').length}）`);
                } else {
                    out.push(`Mục “${nameOf(s)}”${k}: ${short(s[k])} → ${short(l[k])}`);
                }
            });
        });
        if (out.length > PRESET_DIFF_MAX) {
            const rest = out.length - PRESET_DIFF_MAX;
            return [...out.slice(0, PRESET_DIFF_MAX), `…còn ${rest} chỗ khác`];
        }
        return out;
    }

    // Chạy gốc: tạm chuyển Tavern sang preset đã chọn, tạo theo đúng quy trình chat của Tavern, xong thì chuyển lại
    // Nếu preset hiện tại có sửa đổi chưa lưu (kể cả thay đổi lúc chạy của Tavern/script khác), trước khi chuyển chụp snapshot in_use, chuyển lại xong ghi lại nguyên trạng
    async function runWithLoadedPreset(presetName, task) {
        const original = getLoadedPresetNameSafe();
        if (!presetName || presetName === original) return { result: await task(), switched: false };
        const getFn = getHelperFn('getPreset');
        const replaceFn = getHelperFn('replacePreset');
        const canRestore = !!(getFn && replaceFn);
        let snapshot = null;
        let diff = [];
        // Preset tích hợp do script tự quản (khi đồng bộ sẽ ghi settings và tải lại), không chụp/khôi phục snapshot để tránh đè mất dữ liệu script ghi
        if (original && original !== BUILTIN_PRESET_NAME) {
            if (!canRestore) {
                // Tavern Helper bản cũ không có khả năng khôi phục snapshot: giữ logic cũ, có sửa đổi chưa lưu thì không chuyển
                if (hasUnsavedPresetChanges(original)) {
                    showToast(`Preset hiện tại “${original}” có sửa đổi chưa lưu, lần này chuyển sang gọi trực tiếp, không chuyển preset`, 'warning');
                    return null;
                }
            } else {
                try {
                    const live = getFn('in_use');
                    if (live) {
                        snapshot = JSON.parse(JSON.stringify(live));
                        diff = diffPresets(snapshot, getFn(original));
                    }
                } catch (e) {
                    console.warn('[Thanh trạng thái nữ chính] Đọc snapshot preset hiện tại thất bại', e);
                    snapshot = null;
                    diff = [];
                }
                // Không lấy được snapshot thì không khôi phục được: lùi về logic cũ, có sửa đổi chưa lưu thì không chuyển
                if (!snapshot && hasUnsavedPresetChanges(original)) {
                    showToast(`Preset hiện tại “${original}” có sửa đổi chưa lưu, lần này chuyển sang gọi trực tiếp, không chuyển preset`, 'warning');
                    return null;
                }
                if (diff.length) {
                    try {
                        console.groupCollapsed(`[Thanh trạng thái nữ chính] Preset hiện tại “${original}” có ${diff.length} chỗ khác với bản đã lưu, sẽ khôi phục sau khi chuyển lại`);
                        diff.forEach(d => console.warn(d));
                        console.groupEnd();
                    } catch (e) {}
                }
            }
        }
        try {
            await switchLoadedPreset(presetName);
        } catch (e) {
            showToast('Chuyển sang preset “' + presetName + '” thất bại, lần này chuyển sang gọi trực tiếp:' + (e && e.message ? e.message : e), 'warning');
            return null;
        }
        const snapInfo = snapshot ? { preset: original, diff, restored: false } : null;
        try {
            return { result: await task(), switched: true };
        } finally {
            // original trống nghĩa là lúc vào Tavern không báo tên preset, không có gì để chuyển lại, đừng cố chuyển sang tên rỗng
            if (original) {
                let switchedBack = false;
                try {
                    await switchLoadedPreset(original);
                    switchedBack = true;
                } catch (e) {
                    showToast(`Chuyển lại preset “${original}” thất bại, hãy chuyển lại thủ công`, 'error');
                    if (snapInfo) snapInfo.error = 'Chuyển lại thất bại, chưa khôi phục:' + (e && e.message ? e.message : e);
                }
                if (snapInfo && switchedBack && diff.length) {
                    try {
                        await replaceFn('in_use', snapshot);
                        snapInfo.restored = true;
                    } catch (e) {
                        const msg = e && e.message ? e.message : String(e);
                        snapInfo.error = 'Khôi phục thất bại:' + msg;
                        console.warn('[Thanh trạng thái nữ chính] Khôi phục sửa đổi chưa lưu của preset thất bại', e);
                        showToast(`Preset “${original}” khôi phục sửa đổi chưa lưu thất bại: ${msg}, hãy kiểm tra thiết lập preset`, 'error');
                    }
                }
            }
            // logPayload chạy bên trong task, ở đây bổ sung vào cùng một bản nhật ký yêu cầu
            if (snapInfo && lastRequestPayload) lastRequestPayload.presetSnapshot = snapInfo;
        }
    }

    async function requestViaPreset(cfg, userInput, overrides = {}, { applyFormat = true, applyJailbreak = true } = {}) {
        if (cfg.presetName === BUILTIN_PRESET_NAME) await installBuiltinPreset(false);
        const presetSync = await syncBuiltinPresetSettings(cfg);
        const { generateFn } = resolvePreset(cfg.presetName);
        const config = {
            user_input: userInput,
            should_stream: false,
            should_silence: true,
            ...overrides
        };
        if (cfg.presetName) config.preset_name = cfg.presetName;
        if (applyJailbreak && cfg.jailbreakPrompt) {
            config.injects = [...(config.injects || []), {
                role: 'system',
                content: cfg.jailbreakPrompt + '\n\n【Lưu ý】Phần trên chỉ là thiết lập giọng điệu nhân vật và mức độ nội dung; vẫn phải hoàn thành nghiêm túc nhiệm vụ thanh trạng thái và xuất theo mẫu.',
                position: 'in_chat',
                depth: 0,
                should_scan: false
            }];
        }
        if (applyFormat && usesBuiltinFormat(cfg)) {
            const formatText = getBuiltinFormatText();
            // Chèn ở độ sâu 0, đứng sau prompt của preset đã chọn và đầu vào lần này, yêu cầu định dạng có ưu tiên cao nhất
            if (formatText) {
                config.injects = [...(config.injects || []), {
                    role: 'system',
                    content: `【Thanh trạng thái nữ chính·Định dạng đầu ra (ưu tiên hơn mọi yêu cầu về định dạng, văn phong, chuỗi suy nghĩ hay thẻ ở trên)】\n${formatText}`,
                    position: 'in_chat',
                    depth: 0,
                    should_scan: false
                }];
            }
        }
        // Khi nội dung chính đã được script trích vào user_input thì không cho preset kèm cả đoạn lịch sử chat nữa, tránh trùng lặp
        if (config.max_chat_history === undefined) config.max_chat_history = cfg.presetContext === 'preset' ? RECENT_FLOOR_COUNT : 0;
        if (cfg.presetApi === 'custom') {
            config.custom_api = {
                apiurl: normalizeBaseUrl(cfg.baseUrl),
                key: cfg.apiKey,
                model: cfg.model,
                source: 'openai'
            };
        }
        const logPayload = (via, cfgObj) => {
            lastRequestPayload = {
                via,
                config: cfgObj.custom_api ? { ...cfgObj, custom_api: { ...cfgObj.custom_api, key: cfgObj.custom_api.key ? '***' : '' } } : cfgObj
            };
            if (presetSync) lastRequestPayload.presetSettings = presetSync;
        };
        const toText = (res) => {
            if (typeof res === 'string') return res;
            const content = res && typeof res === 'object' ? (res.content || '') : '';
            if (res && typeof res === 'object' && lastRequestPayload) {
                lastRequestPayload.responseMeta = {
                    finish_reason: res.finish_reason,
                    usage: res.usage,
                    contentLength: content.length,
                    reasoningLength: String(res.reasoning_content || res.reasoning || '').length
                };
            }
            return content;
        };
        if (cfg.presetRun !== 'helper' && cfg.presetName) {
            // Không truyền preset_name, Tavern Helper sẽ dùng preset hiện tại (đã chuyển) của Tavern và đi theo quy trình gốc của Tavern
            const nativeConfig = { ...config };
            delete nativeConfig.preset_name;
            const native = await runWithLoadedPreset(cfg.presetName, () => {
                logPayload(`Tavern Helper generate · Chạy gốc (tạm chuyển sang “${cfg.presetName}”）`, nativeConfig);
                return generateFn(nativeConfig);
            });
            if (native) return toText(native.result);
        }
        logPayload(cfg.presetName ? 'Tavern Helper generate · Gọi trực tiếp' : 'Tavern Helper generate · Preset hiện tại của Tavern', config);
        return toText(await generateFn(config));
    }

    function renderPresetOptions(selectedName) {
        const select = qs('#cfg-preset-select');
        if (!select) return;
        const names = getPresetNamesSafe();
        const loaded = getLoadedPresetNameSafe();
        const builtinLabel = names.includes(BUILTIN_PRESET_NAME) ? '(tích hợp)' : '(tích hợp, tự cài khi dùng lần đầu)';
        const opts = [
            `<option value="${escapeHtml(BUILTIN_PRESET_NAME)}">${escapeHtml(BUILTIN_PRESET_NAME)}${builtinLabel}</option>`,
            `<option value="">Theo preset hiện tại của Tavern ${loaded ? '（' + escapeHtml(loaded) + ')' : ''}</option>`
        ];
        names.filter(n => n !== BUILTIN_PRESET_NAME).forEach(n => opts.push(`<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>`));
        if (selectedName && selectedName !== BUILTIN_PRESET_NAME && !names.includes(selectedName)) {
            opts.push(`<option value="${escapeHtml(selectedName)}">${escapeHtml(selectedName)} (đã mất hiệu lực)</option>`);
        }
        select.innerHTML = opts.join('');
        select.value = selectedName || '';
        updatePresetHint();
    }

    function updatePresetHint() {
        const hint = qs('#cfg-preset-hint');
        if (!hint) return;
        try {
            const { label } = resolvePreset(qs('#cfg-preset-select').value || '');
            const apiText = qs('#cfg-preset-api').value === 'custom' ? 'API tùy chỉnh bên dưới' : 'API hiện tại của Tavern';
            const cfg = collectConfigFromUI();
            const formatText = cfg.presetName === BUILTIN_PRESET_NAME
                ? ''
                : (usesBuiltinFormat(cfg) ? 'Định dạng đầu ra áp dụng thêm “Quy tắc định dạng bắt buộc” và “Tự kiểm tra cuối cùng” của preset tích hợp.' : 'Định dạng đầu ra hoàn toàn do preset đã chọn quyết định, có thể không phân tích được.');
            hint.className = 'form-hint';
            const runText = !cfg.presetName
                ? 'Tạo theo đúng quy trình chat của Tavern (mọi tham số, độ dài ngữ cảnh và vị trí prompt đều có hiệu lực).'
                : (cfg.presetRun === 'helper'
                    ? 'Gọi trực tiếp: chỉ áp dụng prompt cùng Token trả lời tối đa, nhiệt độ, phạt lặp, Top P/K; độ dài ngữ cảnh theo preset hiện tại của Tavern, regex và script gắn với preset không chạy.'
                    : 'Chạy gốc: khi đồng bộ Tavern sẽ chuyển nhanh sang preset này, xong tự chuyển lại, trong lúc đó đừng gửi tin nhắn; sửa đổi chưa lưu của preset hiện tại sẽ được khôi phục nguyên trạng sau khi chuyển lại.');
            hint.innerHTML = `Sẽ dùng preset ${escapeHtml(label)}, tạo qua ${apiText}. ${runText}${formatText}`;
        } catch (err) {
            hint.className = 'form-hint error';
            hint.textContent = err.message;
        }
    }

    // Cấu hình hiện tại có cần điền API tùy chỉnh bên dưới không API
    const usesCustomApi = (cfg) => cfg.apiMode === 'custom' || (cfg.apiMode === 'preset' && cfg.presetApi === 'custom');

    function updateApiModeUI() {
        const cfg = collectConfigFromUI();
        const needCustom = usesCustomApi(cfg);
        qs('#cfg-preset-section').style.display = cfg.apiMode === 'preset' ? '' : 'none';
        qs('#cfg-preset-format-group').style.display = cfg.presetName === BUILTIN_PRESET_NAME ? 'none' : '';
        qs('#cfg-preset-run').closest('.form-group').style.display = cfg.presetName ? '' : 'none';
        qs('#cfg-profile-section').style.display = cfg.apiMode === 'profile' ? '' : 'none';
        const builtinPreset = cfg.apiMode === 'preset' && cfg.presetName === BUILTIN_PRESET_NAME;
        const showOutputControls = cfg.apiMode !== 'preset' || builtinPreset;
        qs('#cfg-max-tokens-group').style.display = showOutputControls ? '' : 'none';
        const reasoningGroup = qs('#cfg-reasoning-group');
        if (reasoningGroup) reasoningGroup.style.display = (needCustom || builtinPreset) ? '' : 'none';
        const maxHint = qs('#cfg-max-tokens-hint');
        if (maxHint) maxHint.textContent = builtinPreset
            ? 'Sẽ ghi vào max_completion_tokens của preset tích hợp; thanh trạng thái có nhiều trường, khuyên đặt 12000～16000.'
            : '';
        // Hiển thị giá trị hiện tại của preset tích hợp vào ô nhập, tránh khi đồng bộ bị chỉnh nhỏ đi
        const maxInput = qs('#cfg-max-tokens');
        if (maxInput && builtinPreset && targetDocument.activeElement !== maxInput) {
            const presetMax = readBuiltinPresetSetting('max_completion_tokens');
            if (presetMax) maxInput.value = presetMax;
        }
        qs('#cfg-custom-section').style.display = needCustom ? '' : 'none';
        // Khi dùng preset Tavern (API chính) hoặc cấu hình kết nối Tavern, có nút kiểm tra trong thẻ này; khi dùng API tùy chỉnh thì do nút “Kết nối” bên dưới đảm nhận
        const modeTestGroup = qs('#cfg-mode-test-group');
        if (modeTestGroup) modeTestGroup.style.display = (cfg.apiMode === 'profile' || (cfg.apiMode === 'preset' && cfg.presetApi !== 'custom')) ? '' : 'none';
        hideConnectionStatus();
        hideConnectionStatus('#mode-connection-status');
        if (cfg.apiMode === 'preset') updatePresetHint();
        if (cfg.apiMode === 'profile') updateProfileHint();
    }

    // Trả về chữ báo lỗi; cấu hình dùng được thì trả về chuỗi rỗng
    function validateConfig(cfg) {
        if (cfg.apiMode === 'profile') {
            try { resolveProfile(cfg.profileId); return ''; } catch (err) { return err.message; }
        }
        if (cfg.apiMode === 'preset') {
            try { resolvePreset(cfg.presetName); } catch (err) { return err.message; }
            if (!usesCustomApi(cfg)) return '';
        }
        if (!normalizeBaseUrl(cfg.baseUrl)) return 'Hãy điền endpoint tùy chỉnh (URL gốc) trong cài đặt trước';
        if (!/^https?:\/\/[^\/\s]+/i.test(normalizeBaseUrl(cfg.baseUrl))) return 'Endpoint tùy chỉnh (URL gốc) sai định dạng';
        if (!cfg.apiKey) return 'Hãy điền API key trong cài đặt trước';
        if (!cfg.model) return 'Hãy điền tên mô hình trong cài đặt trước';
        return '';
    }

    async function requestOnce(cfg, messages, maxTokens) {
        if (cfg.apiMode === 'preset') {
            // Ràng buộc vai trò và định dạng giao cho preset, script chỉ gửi chỉ dẫn nhiệm vụ làm đầu vào người dùng
            const userMsg = [...messages].reverse().find(m => m.role === 'user');
            return requestViaPreset(cfg, userMsg ? userMsg.content : '');
        }
        if (cfg.apiMode === 'profile') return requestViaProfile(cfg.profileId, messages, maxTokens);
        const requestBody = {
            model: cfg.model,
            messages: messages,
            temperature: 0.7,
            max_tokens: maxTokens,
            stream: false
        };
        // Mô hình suy luận dùng hết hạn mức đầu ra cho suy nghĩ khiến content trống; mặc định tắt suy nghĩ
        if (cfg.disableReasoning !== false) requestBody.reasoning_effort = 'none';
        const endpoint = getChatUrl(cfg);
        lastRequestPayload = { via: 'Tùy chỉnh API', url: endpoint, body: requestBody };
        const data = await apiRequest(endpoint, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': 'Bearer ' + cfg.apiKey
            },
            body: JSON.stringify(requestBody)
        });
        const message = data?.choices?.[0]?.message || {};
        const content = message.content || '';
        if (lastRequestPayload) {
            lastRequestPayload.responseMeta = {
                finish_reason: data?.choices?.[0]?.finish_reason,
                usage: data?.usage,
                contentLength: (content || '').length,
                reasoningLength: (message.reasoning_content || '').length
            };
        }
        return content;
    }

    // Khi trả lời trống thống nhất thử lại một lần: bắt buộc tắt suy nghĩ; chẩn đoán của lần đầu và lần thử lại đều lưu ở lastRequestPayload.attempts
    async function requestCompletion(cfg, messages, maxTokens = cfg.maxTokens) {
        const attempts = [];
        const remember = (label, usedCfg, tokens, text) => {
            attempts.push({
                label,
                mode: usedCfg.apiMode,
                maxTokens: tokens,
                contentLength: (text || '').length,
                meta: lastRequestPayload?.responseMeta || null
            });
        };
        let content = await requestOnce(cfg, messages, maxTokens);
        remember('Lần đầu', cfg, maxTokens, content);
        if (content) {
            if (lastRequestPayload) lastRequestPayload.attempts = attempts;
            return content;
        }

        // Luồng preset trả về trống: chuyển sang kết nối hiện tại của Tavern, tự dựng prompt tối giản, bỏ qua việc chuyển preset và thiết lập suy nghĩ trong preset
        if (cfg.apiMode === 'preset') {
            try {
                const formatText = getBuiltinFormatText();
                const fallbackMessages = messages.slice();
                if (formatText) {
                    fallbackMessages.splice(Math.max(0, fallbackMessages.length - 1), 0, {
                        role: 'system',
                        content: '【Thanh trạng thái nữ chính·Định dạng đầu ra (bắt buộc tuân thủ)】\n' + formatText
                    });
                }
                const text = await requestViaProfile('', fallbackMessages, maxTokens, { includePreset: false, includeInstruct: false });
                if (lastRequestPayload) lastRequestPayload.via = 'Kết nối Tavern · Yêu cầu dự phòng sau khi preset trả về trống';
                remember('Preset trống·Chuyển sang kết nối Tavern', cfg, maxTokens, text);
                if (text) {
                    if (lastRequestPayload) {
                        lastRequestPayload.fellBack = true;
                        lastRequestPayload.attempts = attempts;
                    }
                    return text;
                }
            } catch (fallbackErr) {
                attempts.push({ label: 'Preset trống·Chuyển sang kết nối Tavern', error: fallbackErr?.message || String(fallbackErr) });
            }
        }

        if (cfg.disableReasoning === false) {
            try {
                content = await requestOnce({ ...cfg, disableReasoning: true }, messages, maxTokens);
                remember('Thử lại khi trả lời trống', { ...cfg, disableReasoning: true }, maxTokens, content);
            } catch (retryErr) {
                attempts.push({ label: 'Thử lại khi trả lời trống', error: retryErr?.message || String(retryErr) });
            }
        }
        if (lastRequestPayload) lastRequestPayload.attempts = attempts;
        return content;
    }

    // Nút “Kiểm tra kết nối” (thẻ Cách kết nối API): gửi một yêu cầu thử qua preset hoặc cấu hình kết nối Tavern
    async function testModeConnection() {
        const cfg = collectConfigFromUI();
        const statusSel = '#mode-connection-status';
        if (cfg.apiMode !== 'preset' && cfg.apiMode !== 'profile') return false;
        if (cfg.apiMode === 'preset') {
            const cfgError = validateConfig(cfg);
            if (cfgError) { setConnectionStatus('error', escapeHtml(cfgError), statusSel); return false; }
        }
        hideConnectionStatus(statusSel);
        const btn = qs('#btn-test-mode-connection');
        if (btn) btn.disabled = true;
        try {
            if (cfg.apiMode === 'preset') {
                const { label } = resolvePreset(cfg.presetName);
                setConnectionStatus('info', `Đang gửi yêu cầu thử qua preset ${escapeHtml(label)} để gửi yêu cầu thử...`, statusSel);
                const reply = await requestViaPreset(cfg, 'Đây là kiểm tra kết nối, chỉ trả lời: OK', { max_chat_history: 0 }, { applyFormat: false, applyJailbreak: false });
                setConnectionStatus('success', `Kết nối thành công: ${escapeHtml(label)}, trả lời “${escapeHtml(String(reply || '').trim().slice(0, 40))}”`, statusSel);
                return true;
            }
            const { profile } = resolveProfile(cfg.profileId);
            setConnectionStatus('info', `Đang ${describeProfile(profile)} để gửi yêu cầu thử...`, statusSel);
            await requestViaProfile(cfg.profileId, [{ role: 'user', content: 'Chỉ trả lời: OK' }], 64);
            setConnectionStatus('success', `Kết nối thành công: ${describeProfile(profile)}`, statusSel);
            return true;
        } catch (err) {
            setConnectionStatus('error', 'Kết nối thất bại: ' + escapeHtml(err?.message || String(err)), statusSel);
            return false;
        } finally {
            if (btn) btn.disabled = false;
        }
    }

    // Nút “Kết nối”: trước tiên GET /models để lấy danh sách mô hình; endpoint không cung cấp danh sách thì gửi một yêu cầu chat tối giản để kiểm tra kết nối
    async function connectApi() {
        const cfg = collectConfigFromUI();
        const baseInput = qs('#cfg-base-url');
        if (baseInput) baseInput.value = normalizeBaseUrl(baseInput.value);
        if (!normalizeBaseUrl(baseInput ? baseInput.value : '')) { setConnectionStatus('error', 'Hãy điền endpoint tùy chỉnh (URL gốc) trước'); return false; }
        if (!/^https?:\/\//i.test(cfg.baseUrl)) { setConnectionStatus('error', 'Endpoint tùy chỉnh phải bắt đầu bằng http:// hoặc https://'); return false; }
        if (!cfg.apiKey) { setConnectionStatus('error', 'Hãy điền API key trước'); return false; }
        const btn = qs('#btn-connect-api');
        if (btn) btn.disabled = true;
        setConnectionStatus('info', 'Đang kết nối…');
        const authHeaders = { 'Authorization': 'Bearer ' + cfg.apiKey };
        try {
            let models = null;
            let modelsError = null;
            try {
                const data = await apiRequest(getModelsUrl(cfg), { method: 'GET', headers: authHeaders });
                models = (data?.data?.map(m => m && m.id) || data?.models?.map(m => m && (m.id || m.name)) || []).filter(Boolean);
            } catch (err) {
                modelsError = err;
            }
            if (models && models.length) {
                const select = qs('#cfg-model-select');
                select.innerHTML = models.map(m => `<option value="${escapeHtml(m)}">${escapeHtml(m)}</option>`).join('');
                const currentModel = cfg.model;
                if (currentModel && models.includes(currentModel)) {
                    select.value = currentModel;
                } else {
                    qs('#cfg-model-name').value = models[0];
                }
                setConnectionStatus('success', `Kết nối thành công, đã lấy được ${models.length} mô hình`);
                return true;
            }
            if (models) {
                setConnectionStatus('success', 'Kết nối thành công nhưng danh sách mô hình trống, hãy điền tay tên mô hình');
                return true;
            }
            // Một số nhà cung cấp không có /models, chuyển sang kiểm tra bằng yêu cầu chat tối giản
            try {
                await apiRequest(getChatUrl(cfg), {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', ...authHeaders },
                    body: JSON.stringify({
                        model: cfg.model,
                        messages: [{ role: 'user', content: 'Chỉ trả lời: OK' }],
                        max_tokens: 16,
                        stream: false
                    })
                });
                setConnectionStatus('success', 'Kết nối thành công (endpoint này không cung cấp danh sách mô hình, hãy điền tay tên mô hình)');
                return true;
            } catch (chatErr) {
                const detail = chatErr?.message || String(chatErr);
                const modelsDetail = modelsError ? (modelsError.message || String(modelsError)) : '';
                setConnectionStatus('error', 'Kết nối thất bại: ' + escapeHtml(detail) + (modelsDetail && modelsDetail !== detail ? '(lấy danh sách mô hình: ' + escapeHtml(modelsDetail) + ')' : ''));
                return false;
            }
        } finally {
            if (btn) btn.disabled = false;
        }
    }

    // ==================== Lấy ngữ cảnh chat ====================
    // Số tầng nội dung đọc mỗi lần đồng bộ (cùng với dữ liệu thanh trạng thái cũ làm căn cứ cập nhật)
    const RECENT_FLOOR_COUNT = 3;

    function getRecentChatText(maxMessages = RECENT_FLOOR_COUNT) {
        let text = '';
        try {
            if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
                const lastId = getLastMessageId();
                const msgs = getChatMessages(Math.max(0, lastId - maxMessages + 1) + '-' + lastId);
                if (msgs && Array.isArray(msgs)) {
                    const recent = msgs.slice(-maxMessages);
                    text = recent.map(m => {
                        const raw = (m.message || '').toString();
                        const body = raw.replace(/<heroine_status>[\s\S]*?<\/heroine_status>/gi, '').trim();
                        return body ? `【Tầng ${m.message_id} · ${m.name || (m.role === 'user' ? 'Người dùng' : 'Nhân vật')}】\n${body}` : '';
                    }).filter(Boolean).join('\n\n');
                }
            }
        } catch (e) {
            console.warn('Lấy lịch sử chat thất bại', e);
        }
        return text;
    }

    // ==================== Nhật ký nhà phát triển ====================
    function getDevLog() {
        try { return JSON.parse(localStorage.getItem(DEV_LOG_KEY) || '[]'); } catch (e) { return []; }
    }
    function saveDevLog(list) {
        // Khi vượt giới hạn lưu trữ của trình duyệt thì bỏ dần bản ghi cũ nhất
        while (list.length) {
            try { localStorage.setItem(DEV_LOG_KEY, JSON.stringify(list)); return; } catch (e) { list.shift(); }
        }
        try { localStorage.removeItem(DEV_LOG_KEY); } catch (e) {}
    }

    // Đối chiếu nội dung trả về với mẫu từng dòng: dòng bị thiếu, dòng sai số giá trị
    function checkStatusAgainstTemplate(template, content) {
        const fieldCount = {};
        template.split('\n').forEach(line => {
            const m = line.trim().match(/^\[([A-Za-z]+)\|(.*)\]$/);
            if (m) fieldCount[m[1]] = m[2].split('|').length;
        });
        const match = content.match(/<heroine_status>([\s\S]*?)(?:<\/heroine_status>|$)/i);
        if (!match) return { tagFound: false, missing: [], mismatched: [] };
        const seen = {};
        const mismatched = [];
        match[1].split('\n').forEach(line => {
            const m = line.trim().match(/^\[([A-Za-z]+)\|(.*)\]$/);
            if (!m || !(m[1] in fieldCount)) return;
            seen[m[1]] = true;
            const got = m[2].split('|').length;
            if (got !== fieldCount[m[1]]) mismatched.push(`${m[1]} (cần ${fieldCount[m[1]]}, thực tế ${got})`);
        });
        const missing = Object.keys(fieldCount).filter(t => !seen[t] && t !== 'Child');
        return { tagFound: true, closed: /<\/heroine_status>/i.test(content), missing, mismatched };
    }

    function recordDevLog(entry) {
        if (!DEV_MODE) return;
        const list = getDevLog();
        list.push(entry);
        while (list.length > DEV_LOG_MAX) list.shift();
        saveDevLog(list);
        try {
            console.groupCollapsed(`[Thanh trạng thái nữ chính·Nhà phát triển] ${entry.time} ${entry.error ? 'Thất bại' : 'Hoàn tất'} · ${entry.durationMs}ms`);
            console.log('Yêu cầu', entry.request);
            console.log('Câu trả lời gốc\n' + (entry.response || ''));
            if (entry.check) console.log('Kiểm tra định dạng', entry.check);
            if (entry.error) console.warn('Lỗi', entry.error);
            console.groupEnd();
        } catch (e) {}
        renderDevLog(list.length - 1);
    }

    function describeDevEntry(e) {
        const parts = [
            `Thời gian: ${escapeHtml(e.time)}　Thời lượng: ${e.durationMs}ms　Tab: ${escapeHtml(e.tab || '')}`,
            `Cách gọi: ${escapeHtml(e.mode)}${e.label ? '　' + escapeHtml(e.label) : ''}　Độ dài trả lời: ${(e.response || '').length} ký tự`
        ];
        if (e.error) parts.push(`<span class="bad">Lỗi: ${escapeHtml(e.error)}</span>`);
        const snap = e.request && e.request.presetSnapshot;
        if (snap) {
            const n = Array.isArray(snap.diff) ? snap.diff.length : 0;
            const state = !n ? 'Không có khác biệt, không cần khôi phục' : (snap.restored ? 'Đã khôi phục' : 'Chưa khôi phục');
            const text = `Snapshot preset: “${escapeHtml(snap.preset || '')}” khác biệt ${n} chỗ, ${state}${snap.error ? '（' + escapeHtml(snap.error) + ')' : ''}`;
            parts.push(snap.error || (n && !snap.restored) ? `<span class="bad">${text}</span>` : text);
        }
        if (e.check) {
            if (!e.check.tagFound) parts.push('<span class="bad">Không tìm thấy thẻ &lt;heroine_status&gt;</span>');
            else {
                parts.push(e.check.closed ? '<span class="ok">Thẻ đầy đủ</span>' : '<span class="bad">Thiếu thẻ đóng (có thể bị cắt, hãy kiểm tra Token trả lời tối đa)</span>');
                parts.push(e.check.missing.length ? `<span class="bad">Dòng bị thiếu: ${escapeHtml(e.check.missing.join('、'))}</span>` : '<span class="ok">Đủ các dòng</span>');
                parts.push(e.check.mismatched.length ? `<span class="bad">Sai số giá trị: ${escapeHtml(e.check.mismatched.join('、'))}</span>` : '<span class="ok">Số giá trị đều khớp</span>');
            }
        }
        return parts.join('<br>');
    }

    function renderDevLog(selectIndex) {
        const select = qs('#dev-log-select');
        if (!select) return;
        const list = getDevLog();
        if (!list.length) {
            select.innerHTML = '<option value="">Chưa có bản ghi</option>';
            qs('#dev-log-meta').innerHTML = '';
            qs('#dev-log-response').value = '';
            qs('#dev-log-request').value = '';
            return;
        }
        const idx = Number.isInteger(selectIndex) && list[selectIndex] ? selectIndex : list.length - 1;
        select.innerHTML = list.map((e, i) => `<option value="${i}">#${i + 1} ${escapeHtml(e.time)} · ${e.error ? 'Thất bại' : (e.check && e.check.mismatched.length + e.check.missing.length ? 'Sai định dạng' : 'Thành công')}${e.tab ? ' · ' + escapeHtml(e.tab) : ''}</option>`).reverse().join('');
        select.value = String(idx);
        const e = list[idx];
        qs('#dev-log-meta').innerHTML = describeDevEntry(e);
        qs('#dev-log-response').value = e.response || '';
        qs('#dev-log-request').value = JSON.stringify(e.request, null, 2);
    }

    async function copyText(text) {
        try {
            await navigator.clipboard.writeText(text);
        } catch (e) {
            const ta = targetDocument.createElement('textarea');
            ta.value = text;
            targetDocument.body.appendChild(ta);
            ta.select();
            targetDocument.execCommand('copy');
            ta.remove();
        }
        showToast('Đã sao chép vào clipboard', 'success');
    }

