    const DAY_MS = 86400000;
    function parseStoryYmd(s) {
        const m = String(s || '').match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
        if (!m) return null;
        const t = Date.UTC(+m[1], +m[2] - 1, +m[3]);
        return Number.isFinite(t) ? t : null;
    }
    function fmtYmd(t) {
        const d = new Date(t);
        return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0');
    }
    // Ngày cách ngày trong truyện quá xa (thường do mô hình viết nhầm năm, vd 2027 thay cho 2077) thì đổi sang năm gần nhất
    function alignDatesToStory(text, ref) {
        return String(text == null ? '' : text).replace(/(\d{4})-(\d{1,2})-(\d{1,2})/g, (all, y, mo, da) => {
            const t = Date.UTC(+y, +mo - 1, +da);
            if (!Number.isFinite(t) || Math.abs(t - ref) <= 200 * DAY_MS) return all;
            const Y = new Date(ref).getUTCFullYear();
            let best = null;
            [Y - 1, Y, Y + 1].forEach(yy => {
                const c = Date.UTC(yy, +mo - 1, +da);
                if (best === null || Math.abs(c - ref) < Math.abs(best - ref)) best = c;
            });
            return fmtYmd(best);
        });
    }
    function replaceDatesInOrder(text, dates) {
        let i = 0;
        return String(text).replace(/\d{4}-\d{1,2}-\d{1,2}/g, all => (i < dates.length ? fmtYmd(dates[i++]) : all));
    }
    // vals: mảng giá trị; idx: { cycle, lmp, ovu, danger } (vị trí trong mảng, -1 nếu không có); cycleVal: dùng khi số ngày chu kỳ nằm ở mảng khác
    function fixCycleDates(vals, idx, refDate, cycleVal) {
        try {
            const ref = parseStoryYmd(refDate);
            if (!ref || !Array.isArray(vals)) return false;
            let changed = false;
            const set = (i, v) => { if (i >= 0 && vals[i] != null && String(vals[i]) !== v) { vals[i] = v; changed = true; } };
            [idx.lmp, idx.ovu, idx.danger].forEach(i => { if (i >= 0 && vals[i] != null) set(i, alignDatesToStory(vals[i], ref)); });
            const lmp = idx.lmp >= 0 ? parseStoryYmd(vals[idx.lmp]) : null;
            const cm = String(cycleVal != null ? cycleVal : (idx.cycle >= 0 ? vals[idx.cycle] : '')).match(/\d{2}/);
            const cyc = cm ? parseInt(cm[0], 10) : NaN;
            if (lmp && cyc >= 20 && cyc <= 45) {
                const ovu = lmp + (cyc - 14) * DAY_MS;
                if (idx.ovu >= 0 && /\d{4}-\d{1,2}-\d{1,2}/.test(vals[idx.ovu] || '')) set(idx.ovu, replaceDatesInOrder(vals[idx.ovu], [ovu]));
                if (idx.danger >= 0 && /\d{4}-\d{1,2}-\d{1,2}/.test(vals[idx.danger] || '')) set(idx.danger, replaceDatesInOrder(vals[idx.danger], [ovu - 5 * DAY_MS, ovu + 4 * DAY_MS]));
            }
            return changed;
        } catch (e) { return false; }
    }
    function womanCycleIdx(fieldsList) {
        return {
            cycle: fieldsList.indexOf('Số ngày chu kỳ chuẩn'),
            lmp: fieldsList.indexOf('Ngày đầu kỳ kinh cuối'),
            ovu: fieldsList.indexOf('Dự đoán ngày rụng trứng kỳ này'),
            danger: fieldsList.indexOf('Khoảng thời gian nguy hiểm kỳ này')
        };
    }

    function normalizeWoman(w) {
        const src = w && Array.isArray(w.fields) ? w.fields : [];
        return {
            id: (w && w.id) || makeWomanId(),
            fields: Array.from({ length: WOMEN_FIELDS.length }, (_, i) => (src[i] != null && src[i] !== '' ? String(src[i]) : 'Không')),
            status: (w && w.status) || 'pending',
            error: (w && w.error) || '',
            updatedAt: (w && w.updatedAt) || '',
            presence: (w && w.presence) === 'left' ? 'left' : 'present'
        };
    }

    function parseWomenRaw(raw) {
        if (!raw) return emptyWomenState();
        try {
            const data = JSON.parse(raw);
            if (data && Array.isArray(data.women)) {
                const st = {
                    version: 1,
                    date: typeof data.date === 'string' ? data.date : '',
                    time: typeof data.time === 'string' ? data.time : '',
                    women: data.women.map(normalizeWoman)
                };
                const ci = womanCycleIdx(WOMEN_FIELDS);
                st.women.forEach(w => fixCycleDates(w.fields, ci, st.date));
                return st;
            }
        } catch (e) {}
        return emptyWomenState();
    }

    function readWomenState(tabId) {
        return parseWomenRaw(getSavedStatusRaw(tabId));
    }

    function writeWomenState(state) {
        saveStatusRaw(JSON.stringify(state));
    }

    function findWoman(state, wid) {
        return state.women.find(w => w.id === wid);
    }

    function renderWomanCard(w) {
        const f = w.fields;
        const expanded = !!womenExpanded[w.id];
        const name = f[0] || 'Chưa đặt tên';
        const meta = [f[1], f[2], f[5], f[14]].filter(v => v && v !== 'Không').join(' · ') || 'Chưa có thông tin';
        const statusClass = w.status === 'failed' ? 'failed' : (w.status === 'ok' ? 'ok' : 'pending');
        const presence = w.presence === 'left' ? 'left' : 'present';
        const retryBtn = (w.status === 'failed' && presence !== 'left')
            ? `<button type="button" class="woman-icon-btn woman-retry" data-wid="${w.id}" title="Đồng bộ lại (thử lại khi thất bại)" aria-label="Đồng bộ lại">${svgIcon('repeat')}</button>`
            : '';
        const groups = WOMEN_GROUPS.map(g => `
            <div class="women-group">
                <div class="women-group-title">${g.title}</div>
                <div class="women-fields">
                    ${g.fields.map(label => {
                        const idx = WOMEN_FIELDS.indexOf(label);
                        if (label === 'Danh sách con cái') return renderChildrenTableHtml('women', w, idx, '👨 Cha ruột');
                        return `<div class="women-field" data-wid="${w.id}" data-idx="${idx}">
                            <div class="wf-label">${WOMEN_FIELD_EMOJI[label] || '📌'} ${label}</div>
                            <div class="wf-value">${escapeHtml(f[idx] || 'Không')}</div>
                            <button type="button" class="wf-edit" data-wid="${w.id}" data-idx="${idx}" title="Sửa">${svgIcon('pen')}</button>
                        </div>`;
                    }).join('')}
                </div>
            </div>`).join('');
        return `<div class="hs-child-card woman-card${expanded ? ' expanded' : ''}" data-wid="${w.id}">
            <div class="hs-child-summary woman-summary" data-wid="${w.id}">
                <div class="woman-badge">${escapeHtml(String(name).slice(0, 1))}</div>
                <div class="woman-headline">
                    <div class="woman-name">${escapeHtml(name)}</div>
                    <div class="woman-meta">${escapeHtml(meta)}</div>
                </div>
                <span class="woman-status ${statusClass}" title="${escapeHtml(w.error || '')}">${WOMEN_STATUS_TEXT[w.status] || 'Chờ đồng bộ'}</span>
                <span class="woman-presence ${presence}">${presence === 'left' ? 'Rời cảnh' : 'Có mặt'}</span>
                ${retryBtn}
                <button type="button" class="woman-icon-btn woman-presence-btn" data-wid="${w.id}" title="${presence === 'left' ? 'Tử vong, rời cảnh hoặc quay lại (bấm để khôi phục có mặt)' : 'Tử vong, rời cảnh hoặc quay lại (bấm để đánh dấu rời cảnh)'}" aria-label="Tử vong, rời cảnh hoặc quay lại">${svgIcon('door')}</button>
                <button type="button" class="woman-icon-btn woman-manual" data-wid="${w.id}" title="Đồng bộ thủ công nhân vật này" aria-label="Đồng bộ thủ công">${svgIcon('refresh')}</button>
                <button type="button" class="woman-icon-btn woman-del" data-wid="${w.id}" title="Xóa hồ sơ" aria-label="Xóa hồ sơ">${svgIcon('trash')}</button>
                <span class="hs-child-chevron">⌄</span>
            </div>
            <div class="hs-child-details">${groups}</div>
        </div>`;
    }

    // Làm mới từng thẻ: khi đồng bộ hàng loạt không cần vẽ lại cả danh sách (32 người × 45 trường sẽ giật rõ rệt)
    function updateWomanCardDom(state, w) {
        const dateEl = qs('#women-date');
        const timeEl = qs('#women-time');
        if (dateEl) dateEl.textContent = state.date || 'Chưa đồng bộ';
        if (timeEl) timeEl.textContent = state.time || 'Chưa đồng bộ';
        const list = qs('#women-list');
        if (!list || typeof list.querySelector !== 'function') return;
        const card = list.querySelector('.woman-card[data-wid="' + w.id + '"]');
        if (!card || !card.parentNode) { renderWomenView(state); return; }
        const doc = (shadow && shadow.ownerDocument) || (typeof document !== 'undefined' ? document : null);
        if (!doc) return;
        const holder = doc.createElement('div');
        holder.innerHTML = renderWomanCard(w);
        const next = holder.firstElementChild;
        if (next) card.parentNode.replaceChild(next, card);
    }

    function renderWomenView(stateOverride) {
        const view = qs('#women-view');
        if (!view) return;
        const state = stateOverride || womenPreviewState || readWomenState();
        const dateEl = qs('#women-date');
        const timeEl = qs('#women-time');
        if (dateEl) dateEl.textContent = state.date || 'Chưa đồng bộ';
        if (timeEl) timeEl.textContent = state.time || 'Chưa đồng bộ';
        const list = qs('#women-list');
        if (!list) return;
        if (!state.women.length) {
            list.innerHTML = '<div class="hs-empty">Chưa có nhân vật nữ nào. Bấm “Thêm nhân vật nữ”, nhập tên rồi bắt đầu đồng bộ.</div>';
            return;
        }
        list.innerHTML = state.women.map(renderWomanCard).join('');
    }

    function toggleWomanCard(wid) {
        womenExpanded[wid] = !womenExpanded[wid];
        const card = qs('.woman-card[data-wid="' + wid + '"]');
        if (card) card.classList.toggle('expanded', !!womenExpanded[wid]);
    }

    function promptAddWoman() {
        const countNow = readWomenState().women.length;
        if (countNow >= 32) {
            showToast('Hồ sơ nhân vật nữ đã đạt giới hạn 32 người, hãy xóa bớt hồ sơ không cần trước.', 'warning');
            return;
        }
        let name = '';
        try {
            if (window.parent && typeof window.parent.prompt === 'function') {
                name = window.parent.prompt('Nhập tên nhân vật nữ:', '');
            }
        } catch (e) { name = ''; }
        name = String(name || '').trim().slice(0, 30);
        if (!name) { showToast('Đã hủy thêm.', 'info'); return; }
        womenPreviewState = null;
        const state = readWomenState();
        if (state.women.some(w => w.fields[0] === name)) {
            showToast('Đã có hồ sơ trùng tên.', 'warning');
            return;
        }
        const fields = Array(WOMEN_FIELDS.length).fill('Không');
        fields[0] = name;
        const woman = normalizeWoman({ id: makeWomanId(), fields, status: 'pending' });
        state.women.push(woman);
        writeWomenState(state);
        womenExpanded[woman.id] = true;
        renderWomenView();
        renderTimeline();
        updateFooterInfo();
        showToast('Đã thêm【' + name + '】, bấm đồng bộ để bắt đầu lấy hồ sơ.', 'success');
    }

    function deleteWoman(wid) {
        const state = readWomenState();
        const w = findWoman(state, wid);
        if (!w) return;
        try {
            if (window.parent && typeof window.parent.confirm === 'function') {
                if (!window.parent.confirm('Xác nhận xóa hồ sơ của【' + w.fields[0] + '】? Xóa xong không thể khôi phục.')) return;
            }
        } catch (e) {}
        state.women = state.women.filter(x => x.id !== wid);
        womenPreviewState = null;
        writeWomenState(state);
        delete womenExpanded[wid];
        renderWomenView();
        renderTimeline();
        updateFooterInfo();
        showToast('Đã xóa hồ sơ.', 'success');
    }

    function toggleWomanPresence(wid) {
        const state = readWomenState();
        const w = findWoman(state, wid);
        if (!w) return;
        w.presence = w.presence === 'left' ? 'present' : 'left';
        womenPreviewState = null;
        writeWomenState(state);
        renderWomenView();
        renderTimeline();
        updateFooterInfo();
        showToast('【' + w.fields[0] + '】đã được đánh dấu là ' + (w.presence === 'left' ? 'rời cảnh, tự động đồng bộ sẽ bỏ qua' : 'Có mặt'), 'info');
    }

    function updateWomanField(wid, idx, value) {
        const state = readWomenState();
        const w = findWoman(state, wid);
        if (!w || idx < 0 || idx >= WOMEN_FIELDS.length) return;
        w.fields[idx] = value || 'Không';
        writeWomenState(state);
    }

    function handleFieldEdit(btn) {
        const row = btn.closest('.women-field');
        if (!row) return;
        const wid = btn.getAttribute('data-wid');
        const idx = parseInt(btn.getAttribute('data-idx'), 10);
        const valueEl = row.querySelector('.wf-value');
        if (row.dataset.editing === '1') {
            const input = row.querySelector('.wf-input');
            const val = input ? input.value.trim() : valueEl.textContent;
            updateWomanField(wid, idx, val);
            womenPreviewState = null;
            renderWomenView();
            renderTimeline();
            showToast('Đã lưu.', 'success');
            return;
        }
        const state = womenPreviewState || readWomenState();
        const w = findWoman(state, wid);
        const current = w ? (w.fields[idx] || '') : (valueEl.textContent || '');
        row.dataset.editing = '1';
        valueEl.innerHTML = '<textarea class="wf-input"></textarea>';
        const ta = valueEl.querySelector('textarea');
        ta.value = current;
        ta.focus();
        ta.addEventListener('click', (ev) => ev.stopPropagation());
    }

    function handleClockEdit(btn) {
        const kind = btn.getAttribute('data-kind');
        if (kind !== 'date' && kind !== 'time') return;
        const el = qs(kind === 'date' ? '#women-date' : '#women-time');
        if (!el) return;
        const state = womenPreviewState || readWomenState();
        if (btn.dataset.editing === '1') {
            const input = el.querySelector('input');
            state[kind] = (input ? input.value : el.textContent).trim();
            womenPreviewState = null;
            writeWomenState(state);
            renderWomenView();
            showToast('Đã lưu.', 'success');
            return;
        }
        btn.dataset.editing = '1';
        el.innerHTML = '<input class="wf-clock-input" type="text">';
        const input = el.querySelector('input');
        input.value = state[kind] || '';
        input.focus();
        input.addEventListener('click', (ev) => ev.stopPropagation());
    }

    function handleWomenViewClick(e) {
        const editBtn = e.target.closest('.wf-edit');
        if (editBtn && editBtn.hasAttribute('data-kind')) {
            e.stopPropagation();
            handleClockEdit(editBtn);
            return;
        }
        if (editBtn) {
            e.stopPropagation();
            if (editBtn.hasAttribute('data-row')) handleChildCellEdit('women', editBtn);
            else handleFieldEdit(editBtn);
            return;
        }
        const retry = e.target.closest('.woman-retry');
        if (retry) {
            e.stopPropagation();
            retryWoman(retry.getAttribute('data-wid'));
            return;
        }
        const presenceBtn = e.target.closest('.woman-presence-btn');
        if (presenceBtn) {
            e.stopPropagation();
            toggleWomanPresence(presenceBtn.getAttribute('data-wid'));
            return;
        }
        const manualBtn = e.target.closest('.woman-manual');
        if (manualBtn) {
            e.stopPropagation();
            retryWoman(manualBtn.getAttribute('data-wid'), true);
            return;
        }
        const addChild = e.target.closest('.child-add');
        if (addChild) {
            e.stopPropagation();
            handleChildRowAdd('women', addChild);
            return;
        }
        const del = e.target.closest('.woman-del');
        if (del) {
            e.stopPropagation();
            deleteWoman(del.getAttribute('data-wid'));
            return;
        }
        const summary = e.target.closest('.woman-summary');
        if (summary) toggleWomanCard(summary.getAttribute('data-wid'));
    }

    // Trích world info chỉ cố gắng hết mức: máy chủ không có helper tương ứng thì bỏ qua; mỗi lần đồng bộ chỉ đọc một lần
    let womenWbCache = null;
    function collectWorldbookEntries() {
        if (womenWbCache) return womenWbCache;
        const out = [];
        try {
            const entriesFn = getHelperFn('getLorebookEntries');
            if (!entriesFn) {
                womenWbCache = out;
                return out;
            }
            let books = [];
            const namesFn = getHelperFn('getCharWorldbookNames');
            if (namesFn) {
                const res = namesFn('current');
                if (Array.isArray(res)) books = res;
                else if (res && Array.isArray(res.primary)) books = res.primary;
            }
            for (const book of books.slice(0, 2)) {
                let entries = [];
                try { entries = entriesFn(book) || []; } catch (e) { continue; }
                for (const en of entries) {
                    const text = String(en && (en.content || en.comment) || '');
                    if (!text) continue;
                    const keys = (Array.isArray(en.key) ? en.key : String(en.key || '').split(','))
                        .map(k => String(k || '').trim())
                        .filter(Boolean);
                    out.push({ keys, text });
                }
            }
        } catch (e) {}
        womenWbCache = out;
        return out;
    }

    function getWorldbookContext(name) {
        try {
            const picked = [];
            for (const en of collectWorldbookEntries()) {
                const hit = en.keys.some(k => k.includes(name) || name.includes(k)) || en.text.includes(name);
                if (hit) {
                    picked.push(en.text.slice(0, 600));
                    if (picked.length >= 3) break;
                }
            }
            return picked.join('\n---\n');
        } catch (e) {
            return '';
        }
    }

    function buildWomanPrompt(w, ctx) {
        const old = WOMEN_FIELDS.map((label, i) => label + ': ' + (w.fields[i] || 'Không')).join('\n');
        return `Bạn là AI duy trì “Hồ sơ sinh lý nữ” với góc nhìn toàn tri. Lượt này chỉ phụ trách một nhân vật nữ, xuất hồ sơ ngắn gọn, có thể lưu trực tiếp.

【Nhân vật lần này】 ${w.fields[0]}
【Thời gian trong truyện】 ${ctx.dateHint || '(chưa cung cấp)'}

【Nhập gỡ lỗi / sửa lỗi】(ưu tiên cao nhất)
${ctx.debugInput || '(không có)'}

【Hồ sơ cũ】(nội dung không thay đổi có thể giữ nguyên)
${old}

【Nội dung gần nhất】(nếu trong đó có khối <heroine_status> thanh trạng thái cũ thì bỏ qua, đừng chép lại)
${ctx.chatText || '(chưa có nội dung, hãy suy diễn hợp lý theo góc nhìn toàn tri)'}

【Trích world info】
${getWorldbookContext(w.fields[0]) || '(không đọc được mục liên quan)'}

【Yêu cầu đầu ra】
1. Chỉ xuất hai dòng, không giải thích, tiêu đề hay code block:
[StoryClock|Ngày trong truyện lượt này YYYY-MM-DD|Giờ trong truyện lượt này HH:mm]
[Woman|${WOMEN_FIELDS.join('|')}]
2. [Woman|…] phải có đúng ${WOMEN_FIELDS.length} giá trị, thứ tự giống hệt bên trên, không thêm bớt, không gộp.
3. Trong giá trị cấm có dấu gạch đứng |, ngoặc vuông, ngoặc nhọn và xuống dòng; khi cần phân tách dùng dấu “、” hoặc dấu phẩy.
4. Nội dung chưa được viết trong truyện thì suy diễn hợp lý theo góc nhìn toàn tri; thật sự không áp dụng thì ghi “Không”.
5. Thèm ăn, Ham muốn tình dục, Nhu cầu bài tiết, Buồn ngủ, Sức hấp dẫn tình dục, Chỉ số sức hút nữ tính, Mức người ngoài nghi ngờ mang thai, Nỗi sợ thụ thai, Mức tự nhận ra mang thai, Mức chấp nhận thai nhi xuất dưới dạng phần trăm, ví dụ 62%.
6. Mọi trường số liệu phải có đơn vị: chiều dài cm, dung tích/thể tích ml, trọng lượng kg, thời lượng phút/giây, số lượng quả/sợi, thân nhiệt ℃, huyết áp mmHg, nhịp tim lần/phút; cấm chỉ ghi số.
7. Ngày và giờ lấy theo thời gian trong truyện lượt này; không xác định được thì giữ hồ sơ cũ hoặc suy diễn hợp lý.
8. Định dạng danh sách con cái: “Tên/biệt danh，giới tính，loài，tuổi，cha ruột”; nhiều con phân tách bằng dấu chấm phẩy kiểu Trung “；”; không có con thì điền “Không”.
9. Họ tên cố định là “${w.fields[0]}”, không được đổi tên.`;
    }

    function parseWomanOutput(text) {
        if (!text) return null;
        const raw = String(text).replace(/｜/g, '|');
        const clock = raw.match(/\[StoryClock\|([^|\]\n]*)\|([^|\]\n]*)\]/);
        const m = raw.match(/\[Woman\|([^\]\n]*)\]/);
        if (!m) return null;
        const parts = m[1].split('|').map(s => s.trim());
        const fields = Array.from({ length: WOMEN_FIELDS.length }, (_, i) => (parts[i] ? parts[i] : 'Không'));
        return { date: clock ? clock[1].trim() : '', time: clock ? clock[2].trim() : '', fields };
    }

    async function requestWomenCompletion(cfg, prompt) {
        const messages = [{ role: 'user', content: prompt }];
        const errors = [];
        if (cfg.apiMode === 'custom') {
            try {
                const text = await requestOnce(cfg, messages, cfg.maxTokens);
                if (text) return text;
                errors.push('API tùy chỉnh: trả về trống');
            } catch (e) { errors.push('API tùy chỉnh: ' + (e && e.message ? e.message : e)); }
        }
        try {
            const text = await requestViaProfile('', messages, cfg.maxTokens, { includePreset: false, includeInstruct: false });
            if (text) return text;
            errors.push('Kết nối Tavern: trả về trống');
        } catch (e) { errors.push('Kết nối Tavern: ' + (e && e.message ? e.message : e)); }
        const rawFn = getHelperFn('generateRaw');
        if (rawFn) {
            try {
                const res = await rawFn({ user_input: prompt, should_stream: false, should_silence: true, max_chat_history: 0 });
                const text = typeof res === 'string' ? res : (res && res.content ? res.content : '');
                if (text) return text;
                errors.push('generateRaw: trả về trống');
            } catch (e) { errors.push('generateRaw: ' + (e && e.message ? e.message : e)); }
        }
        try {
            const text = await requestOnce(Object.assign({}, cfg, { apiMode: 'preset' }), messages, cfg.maxTokens);
            if (text) return text;
            errors.push('Preset: trả về trống');
        } catch (e) { errors.push('Preset: ' + (e && e.message ? e.message : e)); }
        throw new Error(errors.join('; '));
    }

    async function syncOneWoman(w, ctx) {
        try {
            const text = await requestWomenCompletion(ctx.cfg, buildWomanPrompt(w, ctx));
            const parsed = parseWomanOutput(text);
            if (!parsed) throw new Error(text ? 'Nội dung trả về không có dòng [Woman|…] có thể phân tích' : 'API trả về nội dung trống');
            parsed.fields[0] = w.fields[0];
            w.fields = parsed.fields;
            w.status = 'ok';
            w.error = '';
            w.updatedAt = new Date().toLocaleString('vi-VN');
            if (parsed.date) ctx.state.date = parsed.date;
            if (parsed.time) ctx.state.time = parsed.time;
            fixCycleDates(w.fields, womanCycleIdx(WOMEN_FIELDS), ctx.state.date);
            return true;
        } catch (e) {
            w.status = 'failed';
            w.error = e && e.message ? e.message : String(e);
            return false;
        }
    }

    function setWomenSyncing(on) {
        const btn = qs('#btn-sync-status');
        if (!btn) return;
        btn.disabled = on;
        btn.classList.toggle('syncing', on);
    }

    async function syncWomenArchive(repair = false) {
        if (isSyncing) return 'busy';
        const state = readWomenState();
        if (!state.women.length) {
            if (!syncCfgOverride) showToast('Hãy thêm nhân vật nữ trước rồi bấm đồng bộ.', 'warning');
            return 'empty';
        }
        if (!state.women.some(w => w.presence !== 'left')) {
            if (!syncCfgOverride) showToast('Tất cả nhân vật hiện đều được đánh dấu “Rời cảnh”, đã bỏ qua toàn bộ.', 'warning');
            return 'empty';
        }
        const cfg = getSyncConfig();
        const cfgError = validateConfig(cfg);
        if (cfgError) { showToast(cfgError, 'error'); if (!syncCfgOverride) switchToSettings(); return 'error'; }
        if (!syncCfgOverride) saveConfig(cfg);
        isSyncing = true;
        setWomenSyncing(true);
        womenPreviewState = null;
        womenWbCache = null;
        const previousRaw = getSavedStatusRaw();
        if (!repair) pushSnapshot(previousRaw);
        const targets = state.women.filter(w => w.presence !== 'left');
        const skipped = state.women.length - targets.length;
        let ok = 0;
        let failed = 0;
        try {
            const ctx = { cfg, state, chatText: getRecentChatText(RECENT_FLOOR_COUNT), dateHint: (state.date || '') + ' ' + (state.time || ''), debugInput: (syncCfgOverride ? '' : (qs('#debug-input')?.value.trim() || '')) };
            for (let i = 0; i < targets.length; i++) {
                const w = targets[i];
                const info = qs('#footer-info');
                if (info) info.textContent = withAutoSyncPrefix('Đồng bộ hồ sơ nữ ' + (i + 1) + '/' + targets.length + ' · ' + w.fields[0]);
                (await syncOneWoman(w, ctx)) ? ok++ : failed++;
                writeWomenState(state);
                updateWomanCardDom(state, w);
            }
            if (!syncTargetTabId || syncTargetTabId === currentTabId) {
                renderTimeline();
                updateFooterInfo();
            }
            const tail = skipped ? (', bỏ qua ' + skipped + ' người (rời cảnh)') : '';
            syncToast('Đồng bộ xong: thành công ' + ok + ' người, thất bại ' + failed + ' người' + tail,
                (failed || skipped) ? 'warning' : 'success');
            return failed ? 'partial' : 'success';
        } finally {
            isSyncing = false;
            setWomenSyncing(false);
        }
    }

    async function retryWoman(wid, manual = false) {
        if (isSyncing) { showToast('Đang đồng bộ, vui lòng chờ.', 'info'); return; }
        const state = readWomenState();
        const w = findWoman(state, wid);
        if (!w) return;
        if (!manual && w.presence === 'left') {
            showToast('【' + w.fields[0] + '】đã được đánh dấu rời cảnh, tự động đồng bộ sẽ bỏ qua.', 'info');
            return;
        }
        const cfg = collectConfigFromUI();
        const cfgError = validateConfig(cfg);
        if (cfgError) { showToast(cfgError, 'error'); return; }
        isSyncing = true;
        setWomenSyncing(true);
        womenWbCache = null;
        const info = qs('#footer-info');
        if (info) info.textContent = 'Đồng bộ lại · ' + w.fields[0];
        try {
            const ctx = { cfg, state, chatText: getRecentChatText(RECENT_FLOOR_COUNT), dateHint: (state.date || '') + ' ' + (state.time || ''), debugInput: (qs('#debug-input')?.value.trim() || '') };
            const ok = await syncOneWoman(w, ctx);
            writeWomenState(state);
            renderWomenView();
            renderTimeline();
            updateFooterInfo();
            if (ok) showToast('【' + w.fields[0] + '】đã được cập nhật.', 'success');
            else showToast('【' + w.fields[0] + '】vẫn thất bại: ' + w.error, 'error');
        } finally {
            isSyncing = false;
            setWomenSyncing(false);
        }
    }

