    }

    function parseManOutput(text) {
        if (!text) return null;
        const raw = String(text).replace(/｜/g, '|');
        const clock = raw.match(/\[StoryClock\|([^|\]\n]*)\|([^|\]\n]*)\]/);
        const m = raw.match(/\[Man\|([^\]\n]*)\]/);
        if (!m) return null;
        const parts = m[1].split('|').map(s => s.trim());
        const fields = Array.from({ length: MEN_FIELDS.length }, (_, i) => (parts[i] ? parts[i] : 'Không'));
        return { date: clock ? clock[1].trim() : '', time: clock ? clock[2].trim() : '', fields };
    }

    async function requestMenCompletion(cfg, prompt) {
        const messages = [{ role: 'user', content: prompt }];
        const errors = [];
        if (cfg.apiMode === 'custom') {
            try {
                const text = await requestOnce(cfg, messages, cfg.maxTokens);
                if (text) return text;
                errors.push('API tùy chỉnh: trả về trống');
            } catch (e) { errors.push('API tùy chỉnh: ' + (e && e.message ? e.message : e)); }
        }
        try {
            const text = await requestViaProfile('', messages, cfg.maxTokens, { includePreset: false, includeInstruct: false });
            if (text) return text;
            errors.push('Kết nối Tavern: trả về trống');
        } catch (e) { errors.push('Kết nối Tavern: ' + (e && e.message ? e.message : e)); }
        const rawFn = getHelperFn('generateRaw');
        if (rawFn) {
            try {
                const res = await rawFn({ user_input: prompt, should_stream: false, should_silence: true, max_chat_history: 0 });
                const text = typeof res === 'string' ? res : (res && res.content ? res.content : '');
                if (text) return text;
                errors.push('generateRaw: trả về trống');
            } catch (e) { errors.push('generateRaw: ' + (e && e.message ? e.message : e)); }
        }
        try {
            const text = await requestOnce(Object.assign({}, cfg, { apiMode: 'preset' }), messages, cfg.maxTokens);
            if (text) return text;
            errors.push('Preset: trả về trống');
        } catch (e) { errors.push('Preset: ' + (e && e.message ? e.message : e)); }
        throw new Error(errors.join('; '));
    }

    async function syncOneMan(w, ctx) {
        try {
            const text = await requestMenCompletion(ctx.cfg, buildManPrompt(w, ctx));
            const parsed = parseManOutput(text);
            if (!parsed) throw new Error(text ? 'Nội dung trả về không có dòng [Man|…] có thể phân tích' : 'API trả về nội dung trống');
            parsed.fields[0] = w.fields[0];
            w.fields = parsed.fields;
            w.status = 'ok';
            w.error = '';
            w.updatedAt = new Date().toLocaleString('vi-VN');
            if (parsed.date) ctx.state.date = parsed.date;
            if (parsed.time) ctx.state.time = parsed.time;
            return true;
        } catch (e) {
            w.status = 'failed';
            w.error = e && e.message ? e.message : String(e);
            return false;
        }
    }

    function setMenSyncing(on) {
        const btn = qs('#btn-sync-status');
        if (!btn) return;
        btn.disabled = on;
        btn.classList.toggle('syncing', on);
    }

    async function syncMenArchive(repair = false) {
        if (isSyncing) return 'busy';
        const state = readMenState();
        if (!state.men.length) {
            if (!syncCfgOverride) showToast('Hãy thêm nhân vật nam trước rồi bấm đồng bộ.', 'warning');
            return 'empty';
        }
        if (!state.men.some(w => w.presence !== 'left')) {
            if (!syncCfgOverride) showToast('Tất cả nhân vật hiện đều được đánh dấu “Rời cảnh”, đã bỏ qua toàn bộ.', 'warning');
            return 'empty';
        }
        const cfg = getSyncConfig();
        const cfgError = validateConfig(cfg);
        if (cfgError) { showToast(cfgError, 'error'); if (!syncCfgOverride) switchToSettings(); return 'error'; }
        if (!syncCfgOverride) saveConfig(cfg);
        isSyncing = true;
        setMenSyncing(true);
        menPreviewState = null;
        womenWbCache = null;
        const previousRaw = getSavedStatusRaw();
        if (!repair) pushSnapshot(previousRaw);
        const targets = state.men.filter(w => w.presence !== 'left');
        const skipped = state.men.length - targets.length;
        let ok = 0;
        let failed = 0;
        try {
            const ctx = { cfg, state, chatText: getRecentChatText(RECENT_FLOOR_COUNT), dateHint: (state.date || '') + ' ' + (state.time || ''), debugInput: (syncCfgOverride ? '' : (qs('#debug-input')?.value.trim() || '')) };
            for (let i = 0; i < targets.length; i++) {
                const w = targets[i];
                const info = qs('#footer-info');
                if (info) info.textContent = withAutoSyncPrefix('Đồng bộ hồ sơ nam ' + (i + 1) + '/' + targets.length + ' · ' + w.fields[0]);
                (await syncOneMan(w, ctx)) ? ok++ : failed++;
                writeMenState(state);
                updateManCardDom(state, w);
            }
            if (!syncTargetTabId || syncTargetTabId === currentTabId) {
                renderTimeline();
                updateFooterInfo();
            }
            const tail = skipped ? (', bỏ qua ' + skipped + ' người (rời cảnh)') : '';
            syncToast('Đồng bộ xong: thành công ' + ok + ' người, thất bại ' + failed + ' người' + tail,
                (failed || skipped) ? 'warning' : 'success');
            return failed ? 'partial' : 'success';
        } finally {
            isSyncing = false;
            setMenSyncing(false);
        }
    }

    async function retryMan(wid, manual = false) {
        if (isSyncing) { showToast('Đang đồng bộ, vui lòng chờ.', 'info'); return; }
        const state = readMenState();
        const w = findMan(state, wid);
        if (!w) return;
        if (!manual && w.presence === 'left') {
            showToast('【' + w.fields[0] + '】đã được đánh dấu rời cảnh, tự động đồng bộ sẽ bỏ qua.', 'info');
            return;
        }
        const cfg = collectConfigFromUI();
        const cfgError = validateConfig(cfg);
        if (cfgError) { showToast(cfgError, 'error'); return; }
        isSyncing = true;
        setMenSyncing(true);
        womenWbCache = null;
        const info = qs('#footer-info');
        if (info) info.textContent = 'Đồng bộ lại · ' + w.fields[0];
        try {
            const ctx = { cfg, state, chatText: getRecentChatText(RECENT_FLOOR_COUNT), dateHint: (state.date || '') + ' ' + (state.time || ''), debugInput: (qs('#debug-input')?.value.trim() || '') };
            const ok = await syncOneMan(w, ctx);
            writeMenState(state);
            renderMenView();
            renderTimeline();
            updateFooterInfo();
            if (ok) showToast('【' + w.fields[0] + '】đã được cập nhật.', 'success');
            else showToast('【' + w.fields[0] + '】vẫn thất bại: ' + w.error, 'error');
        } finally {
            isSyncing = false;
            setMenSyncing(false);
        }
    }


    // ==================== Bảng con cái (hồ sơ nữ / nam dùng chung) ====================
    function parseChildRows(value) {
        const s = String(value || '').trim();
        if (!s || s === 'Không') return [];
        return s.split(/[；;]/).map(part => part.trim()).filter(Boolean).map(part => {
            const cells = part.split(/[，,]/).map(x => x.trim());
            if (cells.length === 4) cells.splice(2, 0, 'Không');
            return [cells[0] || 'Không', cells[1] || 'Không', cells[2] || 'Không', cells[3] || 'Không', cells[4] || 'Không'];
        });
    }

    function renderChildrenTableHtml(kind, w, idx, parentLabel) {
        const rows = parseChildRows(w.fields[idx]);
        const head = `<div class="child-table-head"><span>🆔 Tên/biệt danh</span><span>⚧ Giới tính</span><span>🧬 Loài</span><span>🎂 Tuổi</span><span>${parentLabel}</span></div>`;
        const body = rows.map((cells, ri) => `<div class="child-row">${cells.map((cell, ci) => `<div class="child-cell" data-wid="${w.id}" data-idx="${idx}" data-row="${ri}" data-cell="${ci}">
                <span class="child-text">${escapeHtml(cell)}</span>
                <button type="button" class="wf-edit" data-wid="${w.id}" data-idx="${idx}" data-row="${ri}" data-cell="${ci}" title="Sửa">${svgIcon('pen')}</button>
            </div>`).join('')}</div>`).join('');
        const empty = rows.length ? '' : '<div class="child-empty">Chưa có con (tự điền sau khi đồng bộ)</div>';
        const addBtn = `<button type="button" class="child-add" data-wid="${w.id}" data-idx="${idx}">＋ Thêm con</button>`;
        return `<div class="children-table" style="grid-column: 1 / -1;">${head}${body}${empty}${addBtn}</div>`;
    }

    function handleChildRowAdd(kind, btn) {
        const wid = btn.getAttribute('data-wid');
        const idx = parseInt(btn.getAttribute('data-idx'), 10);
        const isWomen = kind === 'women';
        const readState = isWomen ? readWomenState : readMenState;
        const writeState = isWomen ? writeWomenState : writeMenState;
        const findPerson = isWomen ? findWoman : findMan;
        const state = readState();
        const person = findPerson(state, wid);
        if (!person || !(idx >= 0)) return;
        const rows = parseChildRows(person.fields[idx]);
        rows.push(['(con mới)', 'Không', 'Không', 'Không', 'Không']);
        person.fields[idx] = rows.map(r => r.join('，')).join('；');
        writeState(state);
        if (isWomen) { womenPreviewState = null; renderWomenView(); }
        else { menPreviewState = null; renderMenView(); }
        showToast('Đã thêm một dòng con cái, bấm bút ở từng ô để điền nội dung.', 'success');
    }

    function handleChildCellEdit(kind, btn) {
        const cellEl = btn.closest('.child-cell');
        if (!cellEl) return;
        const wid = btn.getAttribute('data-wid');
        const idx = parseInt(btn.getAttribute('data-idx'), 10);
        const row = parseInt(btn.getAttribute('data-row'), 10);
        const cell = parseInt(btn.getAttribute('data-cell'), 10);
        const isWomen = kind === 'women';
        const readState = isWomen ? readWomenState : readMenState;
        const findPerson = isWomen ? findWoman : findMan;
        const writeState = isWomen ? writeWomenState : writeMenState;
        const state = (isWomen ? womenPreviewState : menPreviewState) || readState();
        const person = findPerson(state, wid);
        if (!person) return;
        if (cellEl.dataset.editing === '1') {
            const input = cellEl.querySelector('.wf-input');
            const val = input ? input.value.trim() : '';
            const rows = parseChildRows(person.fields[idx]);
            if (!rows[row]) return;
            rows[row][cell] = val || 'Không';
            const serialized = rows.length ? rows.map(r => r.join('，')).join('；') : 'Không';
            const fresh = readState();
            const target = findPerson(fresh, wid);
            if (target) {
                target.fields[idx] = serialized;
                writeState(fresh);
            }
            if (isWomen) womenPreviewState = null;
            else menPreviewState = null;
            if (isWomen) renderWomenView();
            else renderMenView();
            showToast('Đã lưu.', 'success');
            return;
        }
        const rows = parseChildRows(person.fields[idx]);
        const current = rows[row] ? rows[row][cell] : '';
        cellEl.dataset.editing = '1';
        const textEl = cellEl.querySelector('.child-text');
        textEl.innerHTML = '<textarea class="wf-input"></textarea>';
        const ta = textEl.querySelector('textarea');
        ta.value = current;
        ta.focus();
        ta.addEventListener('click', (ev) => ev.stopPropagation());
    }

    // ==================== Luồng đồng bộ chính ====================
