    // Tìm cùng nhân vật theo họ tên trong “Hồ sơ sinh lý nữ” (hồ sơ nằm trong ô riêng của tab hồ sơ nữ)
    function findArchiveWoman(name) {
        const key = String(name || '').trim();
        if (!key) return null;
        try {
            const womenTab = tabs.find(t => t && t.isWomen);
            const state = readWomenState(womenTab ? womenTab.id : undefined);
            return state.women.find(w => String((w.fields && w.fields[0]) || '').trim() === key) || null;
        } catch (e) { return null; }
    }

    // Nén hồ sơ thành một đoạn “trường: giá trị” đưa vào prompt đồng bộ
    function buildWomanArchiveBlock(name) {
        const w = findArchiveWoman(name);
        if (!w) return '';
        const lines = [];
        WOMEN_FIELDS.forEach((label, idx) => {
            const v = String((w.fields && w.fields[idx]) || '').trim();
            if (!v || v === 'Không' || v === 'Chưa đồng bộ' || v === '-') return;
            lines.push(label + ': ' + v);
        });
        return lines.join('\n');
    }

