    function applyWomanArchiveToHSD(name) {
        const w = findArchiveWoman(name);
        if (!w) return 0;
        const isEmpty = (v) => {
            const t = String(v == null ? '' : v).trim();
            return !t || t === '-' || t === 'Không' || t === 'Chưa đồng bộ';
        };
        let filled = 0;
        const apply = (path, idx, force) => {
            const src = String((w.fields && w.fields[idx]) || '').trim();
            if (isEmpty(src)) return;
            const arr = HSD[path[0]] && HSD[path[0]][path[1]];
            if (!Array.isArray(arr)) return;
            if (!force && !isEmpty(arr[path[2]])) return;
            if (String(arr[path[2]] || '') !== src) { arr[path[2]] = src; filled++; }
