                messages.push({ role: 'system', content: 'Phần trên là thiết lập giọng điệu nhân vật và mức độ nội dung; bạn vẫn phải hoàn thành nghiêm túc nhiệm vụ duy trì dữ liệu thanh trạng thái, xuất theo mẫu trong tin nhắn người dùng, không được chỉ nhập vai.' });
            }
            messages.push({ role: 'system', content: 'Bạn là AI chuyên duy trì dữ liệu thanh trạng thái, giỏi trích xuất, tổng hợp và suy đoán hợp lý trạng thái sinh lý, tâm lý, thai kỳ, trang phục, y tế… của nhân vật nữ từ nội dung câu chuyện.' });
            messages.push({ role: 'user', content: prompt });
            const devStart = Date.now();
            let content = '';
            lastRequestPayload = null;
            try {
                content = await requestCompletion(cfg, messages);
            } catch (reqErr) {
                recordDevLog({
                    time: new Date().toLocaleString('vi-VN'), durationMs: Date.now() - devStart, tab: activeTab.name,
                    mode: cfg.apiMode, label: cfg.apiMode === 'preset' ? (cfg.presetName || 'Preset hiện tại') : '',
                    request: lastRequestPayload, response: '', error: reqErr?.message || String(reqErr)
                });
                throw reqErr;
            }
            recordDevLog({
                time: new Date().toLocaleString('vi-VN'), durationMs: Date.now() - devStart, tab: activeTab.name,
                mode: cfg.apiMode, label: cfg.apiMode === 'preset' ? (cfg.presetName || 'Preset hiện tại') : '',
                request: lastRequestPayload, response: content || '',
                error: content ? '' : 'API Nội dung trả về trống (có thể thử tắt suy nghĩ của mô hình)',
                check: content ? checkStatusAgainstTemplate(template, content) : null
            });
            if (!content) {
                const meta = lastRequestPayload?.responseMeta || {};
                const detail = [];
                if (meta.finish_reason) detail.push('finish_reason=' + meta.finish_reason);
                if (meta.reasoningLength) detail.push('Nội dung suy nghĩ ' + meta.reasoningLength + ' ký tự');
                if (meta.usage && meta.usage.completion_tokens) detail.push('completion_tokens=' + meta.usage.completion_tokens);
                const head = detail.length ? ' (' + detail.join(', ') + ')' : '';
                const hint = cfg.apiMode === 'preset'
                    ? 'Đã thử “Tạo bằng preset → dự phòng bằng kết nối hiện tại của Tavern”. Nếu cả hai đều trống, thường là do mô hình dùng hết hạn mức cho suy nghĩ hoặc API có lọc nội dung; hãy chỉnh “Token tối đa” lên 12000～16000, hoặc chuyển sang API tùy chỉnh.'
                    : 'Hãy kiểm tra xem mô hình có dùng hết hạn mức cho suy nghĩ không, hoặc tăng “Token tối đa”.';
                const firstErr = (lastRequestPayload?.attempts || []).find(a => a.error);
                const errTail = firstErr ? '(lỗi dự phòng: ' + String(firstErr.error).slice(0, 80) + ')' : '';
                throw new Error('API trả về nội dung trống' + head + ': ' + hint + errTail);
            }
            const match = content.match(/<heroine_status>([\s\S]*?)(?:<\/heroine_status>|$)/i);
            if (!match) throw new Error('Không tìm thấy thẻ trong nội dung trả về: <heroine_status>');
            const extracted = '<heroine_status>' + match[1].trim() + '</heroine_status>';
            const previousRaw = getSavedStatusRaw();
            if (!repair) pushSnapshot(previousRaw);
            saveStatusRaw(extracted);
            parseHeroineStatus(extracted);
            if (!isAdaptiveTab) { applyWomanArchiveToHSD(customRoleName); fixHeroineCycleDates(); }
            const isVisibleTab = !syncTargetTabId || syncTargetTabId === currentTabId;
            if (isVisibleTab) {
                renderAll();
                selectedTimelineIndex = -1;
                renderTimeline();
                const now = new Date();
                const timeStr = now.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
                qs('#footer-info').textContent = withAutoSyncPrefix(`Đồng bộ gần nhất: ${timeStr}`);
            }
            const syncedTab = activeTab;
            if (!syncedTab.isAdaptive) {
                const profileName = Array.isArray(HSD.status.profile) ? HSD.status.profile[0] : '';
                if (profileName === '-' || profileName === 'Không' || !profileName) {
                    result = 'not-found';
                    syncToast(`【${syncedTab.name}】không tìm thấy trong ngữ cảnh, các trường của tab vẫn giữ là "-".`, 'warning');
                } else {
                    result = 'success';
                    syncToast(`【${syncedTab.name}】đồng bộ thanh trạng thái thành công!`, 'success');
                }
            } else {
                result = 'success';
                syncToast('Đồng bộ thanh trạng thái thành công!', 'success');
            }
        } catch (err) {
            result = 'error';
            qs('#footer-info').textContent = withAutoSyncPrefix('Đồng bộ thất bại');
            showToast('Đồng bộ thất bại: ' + err.message, 'error');
        } finally {
            isSyncing = false;
            syncBtn.disabled = false;
            syncBtn.classList.remove('syncing');
        }
        return result;
    }

    // ==================== Quản lý tab nhân vật ====================
    function loadTabs() {
        let list = getTabsList();
        if (!Array.isArray(list)) list = [];
        list = list.map(t => {
            if (t && t.isAdaptive && !t.isWomen && !t.isMen) {
                return Object.assign({}, t, { name: 'Hồ sơ sinh lý nữ', isWomen: true });
            }
            return t;
        });
        list = list.map(t => Object.assign({}, t, { checked: t.checked !== false }));
        const womenTab = list.find(t => t && t.isWomen) || { id: ADAPTIVE_TAB_ID, name: 'Hồ sơ sinh lý nữ', isAdaptive: true, isWomen: true };
        const menTab = list.find(t => t && t.isMen) || { id: MEN_TAB_ID, name: 'Hồ sơ sinh lý nam', isAdaptive: true, isMen: true };
        const customs = list.filter(t => t && !t.isWomen && !t.isMen);
        const next = [womenTab, menTab].concat(customs);
        if (JSON.stringify(next) !== JSON.stringify(list)) saveTabsList(next);
        return next;
    }

    function renderTabBar() {
        const tabsEl = qs('#char-tabs');
        if (!tabsEl) return;
        const prevScroll = tabsEl.scrollLeft;
        tabsEl.innerHTML = '';
        tabs.forEach(tab => {
            const el = targetDocument.createElement('div');
            el.className = 'char-tab' + (tab.id === currentTabId ? ' active' : '');
            if (!tab.isAdaptive) el.classList.add('closable');
            el.setAttribute('data-tab-id', tab.id);
            const checked = tab.checked !== false;
            el.innerHTML = `<span class="char-tab-check${checked ? ' checked' : ''}" data-tab-check="${tab.id}" role="checkbox" tabindex="0" aria-checked="${checked ? 'true' : 'false'}" aria-label="${escapeHtml((tab.name || '') + (checked ? ': đã chọn, tham gia đồng bộ' : ': chưa chọn, không tham gia đồng bộ'))}" title="Tích chọn để tham gia đồng bộ">✓</span><span class="char-tab-name"></span>${tab.isAdaptive ? '' : '<span class="char-tab-close">×</span>'}`;
            el.querySelector('.char-tab-name').textContent = tab.name || '';
            const checkEl = el.querySelector('.char-tab-check');
            if (checkEl) {
                checkEl.addEventListener('keydown', (ev) => {
                    if (ev.key === ' ' || ev.key === 'Enter') {
                        ev.preventDefault();
                        ev.stopPropagation();
                        toggleTabChecked(tab.id);
                    }
                });
            }
            el.addEventListener('click', (e) => {
                if (e.target.closest('.char-tab-check')) {
                    e.stopPropagation();
                    toggleTabChecked(tab.id);
                    return;
                }
                if (e.target === el.querySelector('.char-tab-close')) {
                    e.stopPropagation();
                    confirmRemoveTab(tab.id);
                    return;
                }
                switchTab(tab.id);
            });
            tabsEl.appendChild(el);
        });
        const addBtn = qs('#btn-add-tab');
        if (addBtn) addBtn.style.display = tabs.filter(t => !t.isAdaptive).length >= 12 ? 'none' : 'flex';
        tabsEl.scrollLeft = prevScroll;
        if (isMobileLayout()) {
            const activeEl = tabsEl.querySelector('.char-tab.active');
            if (activeEl && tabsEl.clientWidth) {
                const box = tabsEl.getBoundingClientRect();
                const ab = activeEl.getBoundingClientRect();
                if (ab.left < box.left) tabsEl.scrollLeft -= (box.left - ab.left) + 8;
                else if (ab.right > box.right) tabsEl.scrollLeft += (ab.right - box.right) + 8;
            }
        }
    }
    function promptAndAddTab() {
        if (tabs.filter(t => !t.isAdaptive).length >= 12) { showToast('Chỉ có thể tạo tối đa 12 tab nhân vật.', 'warning'); return; }
        let name = '';
        try {
            if (window.parent && typeof window.parent.prompt === 'function') {
                name = window.parent.prompt('Nhập tên nhân vật cho tab mới:', '');
            }
        } catch (e) { name = ''; }
        if (!name || !String(name).trim()) {
            showToast('Đã hủy thêm tab.', 'info');
            return;
        }
        addTabByName(String(name).trim());
    }
    function addTabByName(name) {
        const trimmed = name.trim().slice(0, 30);
        if (!trimmed) { showToast('Tên nhân vật không được để trống.', 'warning'); return; }
        if (tabs.some(t => t.name === trimmed)) { showToast(`Đã có tab【${trimmed}】.`, 'warning'); return; }
        if (tabs.filter(t => !t.isAdaptive).length >= 12) { showToast('Chỉ có thể tạo tối đa 12 tab nhân vật.', 'warning'); return; }
        const newTab = { id: makeTabId(), name: trimmed, isAdaptive: false };
        tabs.push(newTab);
        saveTabsList(tabs);
        renderTabBar();
        switchTab(newTab.id);
        showToast(`Đã thêm tab【${trimmed}】.`, 'success');
    }
    function confirmRemoveTab(tabId) {
        if (isSyncing || isBulkSyncing) { showToast('Đang đồng bộ, vui lòng thử lại sau.', 'warning'); return; }
        const tab = tabs.find(t => t.id === tabId);
        if (!tab || tab.isAdaptive) return;
        try {
            if (window.parent && typeof window.parent.confirm === 'function') {
                if (!window.parent.confirm(`Xác nhận đóng tab【${tab.name}】? Dữ liệu của tab này sẽ bị xóa.`)) return;
            }
        } catch (e) {}
        try {
            localStorage.removeItem(getDataKey(tabId));
            localStorage.removeItem(getHistoryKey(tabId));
        } catch (e) {}
        tabs = tabs.filter(t => t.id !== tabId);
        if (currentTabId === tabId) currentTabId = tabs[0] ? tabs[0].id : ADAPTIVE_TAB_ID;
        saveTabsList(tabs);
        renderTabBar();
        renderActiveTab();
        showToast(`Đã đóng tab【${tab.name}】.`, 'success');
    }
    function switchTab(tabId) {
        const tab = tabs.find(t => t.id === tabId);
        if (!tab) return;
        // Bấm tab nhân vật khi đang ở trang cài đặt / nhật ký: quay lại bảng trước
        if (currentPanelView !== 'dashboard') switchToDashboard();
        currentTabId = tabId;
        selectedTimelineIndex = -1;
        timelineNodes = [];
        renderTabBar();
        renderActiveTab();
        updateFooterInfo();
    }
    function renderActiveTab() {
        const tab = getActiveTab();
        const isWomen = !!tab.isWomen;
        const isMen = !!tab.isMen;
        const isArchive = isWomen || isMen;
        const nav = qs('#hs-nav');
        const content = qs('#hs-content');
        const womenView = qs('#women-view');
        const menView = qs('#men-view');
        if (nav) nav.style.display = isArchive ? 'none' : '';
        if (content) content.style.display = isArchive ? 'none' : '';
        if (womenView) womenView.style.display = isWomen ? '' : 'none';
        if (menView) menView.style.display = isMen ? '' : 'none';
        const titleEl = qs('#header-title');
        const subtitleEl = qs('#header-subtitle');
        if (isArchive) {
            if (isWomen) womenPreviewState = null;
            else menPreviewState = null;
            selectedTimelineIndex = -1;
            timelineNodes = [];
            if (isWomen) {
                if (titleEl) titleEl.textContent = 'Hồ sơ sinh lý nữ';
                if (subtitleEl) subtitleEl.textContent = 'Women Physiology Archive';
                renderWomenView();
            } else {
                if (titleEl) titleEl.textContent = 'Hồ sơ sinh lý nam';
                if (subtitleEl) subtitleEl.textContent = 'Men Physiology Archive';
                renderMenView();
            }
            renderTimeline();
            updateFooterInfo();
            return;
        }
        const savedRaw = getSavedStatusRaw(tab.id);
        resetHSD();
        if (savedRaw) {
            const match = savedRaw.match(/<heroine_status>([\s\S]*?)(?:<\/heroine_status>|$)/i);
            if (match) {
                parseHeroineStatus('<heroine_status>' + match[1].trim() + '</heroine_status>');
            } else if (!tab.isAdaptive) {
                fillHSDWithDashPlaceholders();
            }
        } else if (!tab.isAdaptive) {
            fillHSDWithDashPlaceholders();
        }
        if (!tab.isAdaptive) applyWomanArchiveToHSD(tab.name);
        if (titleEl) titleEl.textContent = tab.isAdaptive ? 'Bảng trạng thái nữ chính' : `${tab.name} - Bảng trạng thái`;
        if (subtitleEl) subtitleEl.textContent = tab.isAdaptive ? 'Heroine Status Dashboard' : 'Custom Heroine Status Dashboard';
        renderTimeline();
        renderAll();
    }

    async function syncAllNonAdaptiveTabs() {
        const customTabs = tabs.filter(t => !t.isAdaptive);
        if (customTabs.length === 0) {
            showToast('Ngoài【Hồ sơ sinh lý nữ】ra, không có tab nhân vật nào khác để đồng bộ.', 'warning');
            return;
        }
        const successNames = [];
        const missedNames = [];
        const previousTabId = currentTabId;
        for (const tab of customTabs) {
            currentTabId = tab.id;
            const res = await syncStatusFromAPI(true);
            if (res === 'not-found') missedNames.push(tab.name);
            else if (res === 'success') successNames.push(tab.name);
        }
        currentTabId = previousTabId;
        renderTabBar();
        renderActiveTab();
        let msg = '';
        if (successNames.length) msg += `Đã đồng bộ thành công: ${successNames.join(', ')}.`;
        if (missedNames.length) msg += `Không tìm thấy nhân vật, chưa đồng bộ: ${missedNames.join(', ')}.`;
        if (!msg) msg = 'Đồng bộ hàng loạt không có kết quả dùng được.';
        showToast(msg, missedNames.length && !successNames.length ? 'warning' : (missedNames.length ? 'info' : 'success'));
    }

    // ==================== Dòng thời gian ====================
    function renderTimeline() {
        const history = getHistory();
        const currentRaw = getSavedStatusRaw();
        timelineNodes = [];
        if (history.length > 0) {
            history.forEach((h, idx) => timelineNodes.push({ index: idx, raw: h.raw, time: h.time || `đồng bộ ${idx + 1}`, isCurrent: false }));
        }
        if (currentRaw && isMeaningfulRaw(currentRaw)) {
            timelineNodes.push({ index: timelineNodes.length, raw: currentRaw, time: 'Hiện tại', isCurrent: true });
        }
        const track = qs('#history-track');
        if (!track) return;
        if (timelineNodes.length === 0) {
            track.innerHTML = '<div class="history-empty">Chưa có lịch sử đồng bộ</div>';
            return;
        }
        track.innerHTML = timelineNodes.map((node, arrIndex) => {
            const isSelected = selectedTimelineIndex === -1 ? node.isCurrent : (arrIndex === selectedTimelineIndex);
            const classes = ['history-node'];
            if (node.isCurrent) classes.push('current');
            if (isSelected) classes.push('selected');
            const label = node.isCurrent ? 'N' : String(arrIndex + 1);
            return `<div class="${classes.join(' ')}" data-timeline-index="${arrIndex}" title="${escapeHtml(node.time)}">${label}</div>`;
        }).join('');
        track.querySelectorAll('.history-node').forEach(el => {
            el.addEventListener('click', (e) => {
                e.stopPropagation();
                const idx = parseInt(el.getAttribute('data-timeline-index'), 10);
                selectTimelineNode(idx);
            });
        });
    }

    function selectTimelineNode(idx) {
        if (!timelineNodes[idx]) return;
        selectedTimelineIndex = idx;
        renderTimeline();
        const target = timelineNodes[idx];
        if (getActiveTab().isWomen) {
            womenPreviewState = parseWomenRaw(target.raw);
            renderWomenView(womenPreviewState);
            qs('#footer-info').textContent = target.isCurrent ? 'Đang hiển thị: lần đồng bộ mới nhất' : ('Đang hiển thị: mốc lịch sử ' + target.time);
            return;
        }
        if (getActiveTab().isMen) {
            menPreviewState = parseMenRaw(target.raw);
            renderMenView(menPreviewState);
            qs('#footer-info').textContent = target.isCurrent ? 'Đang hiển thị: lần đồng bộ mới nhất' : ('Đang hiển thị: mốc lịch sử ' + target.time);
            return;
        }
        parseHeroineStatus(target.raw);
        renderAll();
        if (target.isCurrent) {
            qs('#footer-info').textContent = 'Đang hiển thị: lần đồng bộ mới nhất';
        } else {
            qs('#footer-info').textContent = `Đang hiển thị: mốc lịch sử ${target.time}`;
        }
    }

    function revertToSelectedTimeline() {
        if (isSyncing || isBulkSyncing) { showToast('Đang đồng bộ, vui lòng thử lại sau.', 'warning'); return; }
        const idx = selectedTimelineIndex === -1 ? timelineNodes.length - 1 : selectedTimelineIndex;
        if (idx < 0 || !timelineNodes[idx]) return;
        const target = timelineNodes[idx];
        if (target.isCurrent) {
            showToast('Đã là mốc mới nhất, không cần hoàn tác', 'info');
            return;
        }
        try {
            if (window.parent && typeof window.parent.confirm === 'function') {
                if (!window.parent.confirm('Xác nhận hoàn tác về mốc này? Lịch sử sau mốc này sẽ bị xóa.')) return;
            }
        } catch (e) {}
        if (getActiveTab().isWomen) {
            womenPreviewState = null;
            saveStatusRaw(target.raw);
            const wh = getHistory();
            if (idx < wh.length) { wh.splice(idx); saveHistory(wh); }
            selectedTimelineIndex = -1;
            renderWomenView();
            renderTimeline();
            updateFooterInfo();
            showToast('Đã hoàn tác về mốc đã chọn, lịch sử phía sau đã bị xóa.', 'success');
            return;
        }
        if (getActiveTab().isMen) {
            menPreviewState = null;
            saveStatusRaw(target.raw);
            const mh = getHistory();
            if (idx < mh.length) { mh.splice(idx); saveHistory(mh); }
            selectedTimelineIndex = -1;
            renderMenView();
            renderTimeline();
            updateFooterInfo();
            showToast('Đã hoàn tác về mốc đã chọn, lịch sử phía sau đã bị xóa.', 'success');
            return;
        }
        const history = getHistory();
        if (idx < history.length) {
            // Mốc đích sẽ thành trạng thái hiện tại, lịch sử không giữ thêm bản giống hệt nữa, tránh dòng thời gian có mốc trùng
            history.splice(idx);
            saveHistory(history);
        }
        saveStatusRaw(target.raw);
        parseHeroineStatus(target.raw);
        renderAll();
        selectedTimelineIndex = -1;
        renderTimeline();
        updateFooterInfo();
        showToast('Đã hoàn tác về mốc đã chọn, lịch sử phía sau đã bị xóa.', 'success');
    }

    function clearAllStatusAndHistory() {
        if (isSyncing || isBulkSyncing) { showToast('Đang đồng bộ, vui lòng thử lại sau.', 'warning'); return; }
        try {
            if (window.parent && typeof window.parent.confirm === 'function') {
                if (!window.parent.confirm('Xác nhận xóa toàn bộ dữ liệu thanh trạng thái và lịch sử đồng bộ? Thao tác này không thể khôi phục.')) return;
            }
        } catch (e) {}
        const womenTabNow = getActiveTab();
        if (womenTabNow && womenTabNow.isWomen) {
            try {
                localStorage.removeItem(getDataKey());
                localStorage.removeItem(getHistoryKey());
            } catch (e) { console.warn('Xóa hồ sơ nữ thất bại', e); }
            womenPreviewState = null;
            selectedTimelineIndex = -1;
            timelineNodes = [];
            renderWomenView();
            renderTimeline();
            updateFooterInfo();
            showToast('Đã xóa hồ sơ sinh lý nữ và lịch sử.', 'success');
            return;
        }
        const menTabNow = getActiveTab();
        if (menTabNow && menTabNow.isMen) {
            try {
                localStorage.removeItem(getDataKey());
                localStorage.removeItem(getHistoryKey());
            } catch (e) { console.warn('Xóa hồ sơ nam thất bại', e); }
            menPreviewState = null;
            selectedTimelineIndex = -1;
            timelineNodes = [];
            renderMenView();
            renderTimeline();
            updateFooterInfo();
            showToast('Đã xóa hồ sơ sinh lý nam và lịch sử.', 'success');
            return;
        }
        try {
            localStorage.removeItem(getDataKey());
            localStorage.removeItem(getHistoryKey());
        } catch (e) {
            console.warn('Xóa dữ liệu thất bại', e);
        }
        selectedTimelineIndex = -1;
        timelineNodes = [];
        resetHSD();
        const activeTab = getActiveTab();
        if (activeTab && !activeTab.isAdaptive) {
            fillHSDWithDashPlaceholders();
        }
        renderAll();
        renderTimeline();
        updateFooterInfo();
        const emptyEl = qs('#hs-empty-placeholder');
        if (emptyEl) {
            emptyEl.style.display = 'block';
            emptyEl.textContent = activeTab?.isAdaptive ? 'Đã xóa dữ liệu, có thể đồng bộ lại hoặc nhập.' : `【${activeTab?.name || ''}】đã xóa dữ liệu, có thể đồng bộ nhân vật này hoặc nhập.`;
        }
        showToast('Đã xóa dữ liệu và lịch sử của tab hiện tại.', 'success');
    }

    async function exportStatusHistory() {
        const cardName = getCurrentCardName() || 'UnknownCard';
        const activeTab = getActiveTab();
        const tabName = (activeTab?.name || 'Hồ sơ sinh lý nữ').replace(/[\\/:*?"<>|]/g, '_');
        const safeCardName = `${cardName}_${tabName}`.replace(/[\\/:*?"<>|]/g, '_');
        const now = new Date();
        const pad = (n) => String(n).padStart(2, '0');
        const timeStamp = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}`;
        const lastId = (typeof getLastMessageId === 'function') ? getLastMessageId() : 0;
        const payload = {
            card: cardName,
            exportedAt: now.toISOString(),
            lastMessageId: lastId,
            current: getSavedStatusRaw(),
            history: getHistory()
        };
        try {
            const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = targetDocument.createElement('a');
            a.href = url;
            a.download = `Bảng trạng thái nữ chính_${safeCardName}_${timeStamp}_tang ${lastId}.json`;
            targetDocument.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(() => URL.revokeObjectURL(url), 2000);
            showToast('Đã xuất dữ liệu thanh trạng thái.', 'success');
        } catch (err) {
            showToast('Xuất thất bại: ' + err.message, 'error');
        }
    }

    function importStatusHistory() {
        if (isSyncing || isBulkSyncing) { showToast('Đang đồng bộ, vui lòng thử lại sau.', 'warning'); return; }
        const input = targetDocument.createElement('input');
        input.type = 'file';
        input.accept = 'application/json';
        input.style.display = 'none';
        targetDocument.body.appendChild(input);
        input.addEventListener('change', (e) => {
            const file = e.target.files && e.target.files[0];
            input.remove();
            if (!file) return;
            const reader = new FileReader();
            reader.onload = async () => {
                // Trong lúc chọn tệp có thể đã bắt đầu đồng bộ (tự động), xác nhận lại trước khi ghi
                if (isSyncing || isBulkSyncing) { showToast('Đang đồng bộ, vui lòng thử lại sau.', 'warning'); return; }
                try {
                    const data = JSON.parse(reader.result);
                    if (!data || typeof data.current !== 'string' || !Array.isArray(data.history)) {
                        showToast('Nhập thất bại: định dạng tệp không đúng.', 'error');
                        return;
                    }
                    const womenTabNow = getActiveTab();
                    if (womenTabNow && womenTabNow.isWomen) {
                        let parsedWomen = null;
                        try { parsedWomen = JSON.parse(data.current || '{}'); } catch (e) { parsedWomen = null; }
                        if (!parsedWomen || !Array.isArray(parsedWomen.women)) {
                            showToast('Nhập thất bại: đây không phải dữ liệu hồ sơ sinh lý nữ.', 'error');
                            return;
                        }
                        if (parsedWomen.women.length > 32) {
                            showToast('Nhập thất bại: hồ sơ nữ vượt giới hạn 32 người.', 'error');
                            return;
                        }
                        saveStatusRaw(JSON.stringify(parsedWomen));
                        saveHistory(data.history.slice(0, 10));
                        womenPreviewState = null;
                        selectedTimelineIndex = -1;
                        renderWomenView();
                        renderTimeline();
                        updateFooterInfo();
                        showToast('Nhập hồ sơ sinh lý nữ thành công.', 'success');
                        return;
                    }
                    const menTabNow = getActiveTab();
                    if (menTabNow && menTabNow.isMen) {
                        let parsedMen = null;
                        try { parsedMen = JSON.parse(data.current || '{}'); } catch (e) { parsedMen = null; }
                        if (!parsedMen || !Array.isArray(parsedMen.men)) {
                            showToast('Nhập thất bại: đây không phải dữ liệu hồ sơ sinh lý nam.', 'error');
                            return;
                        }
                        if (parsedMen.men.length > 32) {
                            showToast('Nhập thất bại: hồ sơ nam vượt giới hạn 32 người.', 'error');
                            return;
                        }
                        saveStatusRaw(JSON.stringify(parsedMen));
                        saveHistory(data.history.slice(0, 10));
                        menPreviewState = null;
                        selectedTimelineIndex = -1;
                        renderMenView();
                        renderTimeline();
                        updateFooterInfo();
                        showToast('Nhập hồ sơ sinh lý nam thành công.', 'success');
                        return;
                    }
                    saveStatusRaw(data.current);
                    saveHistory(data.history.slice(0, 10));
                    selectedTimelineIndex = -1;
                    const match = data.current.match(/<heroine_status>([\s\S]*?)(?:<\/heroine_status>|$)/i);
                    if (match) {
                        parseHeroineStatus('<heroine_status>' + match[1].trim() + '</heroine_status>');
                        renderAll();
                        const emptyEl = qs('#hs-empty-placeholder');
                        if (emptyEl) emptyEl.style.display = 'none';
                    }
                    renderTimeline();
                    updateFooterInfo();
                    showToast('Nhập dữ liệu thanh trạng thái thành công.', 'success');
                } catch (err) {
                    showToast('Nhập thất bại: ' + err.message, 'error');
                }
            };
            reader.readAsText(file);
        });
        input.click();
    }

    // ==================== Đồng bộ theo lựa chọn / Quản lý toàn bộ ====================
    function toggleTabChecked(id) {
        const tab = tabs.find(t => t.id === id);
        if (!tab) return;
        const activeEl = (shadow && shadow.activeElement)
            || (targetDocument && targetDocument.activeElement) || null;
        const wasFocused = !!(activeEl && activeEl.getAttribute
            && activeEl.getAttribute('data-tab-check') === id);
        tab.checked = tab.checked === false;
        saveTabsList(tabs);
        renderTabBar();
        if (wasFocused) {
            const again = qs('.char-tab-check[data-tab-check="' + id + '"]');
            if (again && again.focus) { try { again.focus(); } catch (e) {} }
        }
    }

    function toggleAllTabs() {
        const allOn = tabs.every(t => t.checked !== false);
        tabs.forEach(t => { t.checked = !allOn; });
        saveTabsList(tabs);
        renderTabBar();
        showToast(allOn ? 'Đã bỏ chọn tất cả.' : 'Đã chọn tất cả các bảng trạng thái.', 'info');
    }

    // auto=true: tự động đồng bộ (cfgOverride là cấu hình đã lưu), không mở trang cài đặt, không ghi lại cấu hình, không có lựa chọn thì im lặng
    async function syncCheckedTabs(repair = false, { cfgOverride = null, auto = false } = {}) {
        if (isSyncing || isBulkSyncing) return 'busy';
        const checked = tabs.filter(t => t && t.checked !== false);
        if (!checked.length) {
            if (!auto) showToast('Hãy chọn trước các bảng trạng thái cần ' + (repair ? 'sửa' : 'đồng bộ') + '.', 'warning');
            return 'empty';
        }
        const cfg = cfgOverride ? { ...cfgOverride } : collectConfigFromUI();
        const cfgError = validateConfig(cfg);
        if (cfgError) {
            showToast(auto ? 'Tự động đồng bộ chưa chạy: ' + cfgError : cfgError, 'error');
            if (!auto) switchToSettings();
            return 'error';
        }
        if (!cfgOverride) saveConfig(cfg);
        const syncBtn = qs('#btn-sync-status');
        const repairBtn = qs('#btn-repair-status');
        if (syncBtn) { syncBtn.disabled = true; syncBtn.classList.add('syncing'); }
        if (repairBtn) repairBtn.disabled = true;
        const prevSyncTarget = syncTargetTabId;
        const runStartedAt = Date.now();
        let ok = 0;
        let failed = 0;
        let skipped = 0;
        isBulkSyncing = true;
        syncCfgOverride = cfgOverride ? cfg : null;
        // Tự động đồng bộ thực sự bắt đầu: thông báo trực tiếp (không qua syncToast để tránh bị tắt tiếng ở chế độ tự động)
        if (auto) showToast('Đang tự động đồng bộ, đừng gửi tin nhắn để tránh ảnh hưởng preset hiện tại của Tavern.', 'warning');
        try {
            for (let i = 0; i < checked.length; i++) {
                const tab = checked[i];
                syncTargetTabId = tab.id;
                const info = qs('#footer-info');
                if (info) info.textContent = withAutoSyncPrefix((repair ? 'sửa' : 'đồng bộ') + ' ' + (i + 1) + '/' + checked.length + ' · ' + tab.name);
                let res = 'error';
                try {
                    if (tab.isWomen) res = await syncWomenArchive(repair);
                    else if (tab.isMen) res = await syncMenArchive(repair);
                    else res = await syncStatusFromAPI(false, repair);
                } catch (e) {
                    console.warn('[Thanh trạng thái nữ chính] Đồng bộ thất bại', e);
                    res = 'error';
                }
                if (res === 'success' || res === 'partial') ok++;
                else if (res === 'empty') { if (!auto) skipped++; } // Tự động đồng bộ: hồ sơ không có dữ liệu không tính là bỏ qua
                else if (res === 'busy') skipped++;
                else failed++;
            }
        } finally {
            isBulkSyncing = false;
            syncCfgOverride = null;
            syncTargetTabId = prevSyncTarget;
            // Ghi lại thời điểm bắt đầu của lần đồng bộ này (thủ công hoặc tự động): lần đồng bộ bắt đầu sau câu trả lời đã bao gồm câu trả lời đó
            lastCompletedSyncStartedAt = runStartedAt;
            if (syncBtn) { syncBtn.disabled = false; syncBtn.classList.remove('syncing'); }
            if (repairBtn) repairBtn.disabled = false;
            renderActiveTab();
            updateFooterInfo();
        }
        showToast((auto ? 'Tự động · ' : '') + (repair ? 'Sửa xong: ' : 'Đồng bộ xong: ') + 'Thành công ' + ok + ', thất bại ' + failed + (skipped ? ', bỏ qua ' + skipped : ''),
            (failed || skipped) ? 'warning' : 'success');
        return failed ? 'partial' : 'success';
    }

