    function clearBook() {
        if (isSyncing || isBulkSyncing) { showToast('Đang đồng bộ, vui lòng xóa sạch lại sau.', 'warning'); return; }
        try {
            if (window.parent && typeof window.parent.confirm === 'function') {
                if (!window.parent.confirm('Nên bấm “Xuất toàn bộ” để lưu trữ trước.\n\nXác nhận xóa sạch toàn bộ thanh trạng thái (gồm mọi tab, dữ liệu và lịch sử)? Thao tác này không thể khôi phục.')) return;
            }
        } catch (e) {}
        try {
            tabs.forEach(t => {
                localStorage.removeItem(getDataKey(t.id));
                localStorage.removeItem(getHistoryKey(t.id));
            });
        } catch (e) { console.warn('Xóa sạch thất bại', e); }
        saveTabsList([
            { id: ADAPTIVE_TAB_ID, name: 'Hồ sơ sinh lý nữ', isAdaptive: true, isWomen: true, checked: true },
            { id: MEN_TAB_ID, name: 'Hồ sơ sinh lý nam', isAdaptive: true, isMen: true, checked: true }
        ]);
