        renderTabBar();
        renderActiveTab();
        updateFooterInfo();
        showToast('Đã xóa sạch toàn bộ, các tab đã được đặt lại.', 'success');
    }

    // ==================== Phản hồi thanh trạng thái vào nội dung chính ====================
    function buildHeroineFeedbackText(raw) {
        const snapshot = JSON.parse(JSON.stringify(HSD));
        if (raw) {
            resetHSD();
            const matched = String(raw).match(/<heroine_status>([\s\S]*?)(?:<\/heroine_status>|$)/i);
            if (matched) parseHeroineStatus('<heroine_status>' + matched[1].trim() + '</heroine_status>');
        }
        try {
        const st = HSD.status.spaceTime;
        const pf = HSD.status.profile;
        const ch = HSD.status.charm;
        const state = HSD.privacy.state;
        const breast = HSD.privacy.breast;
        const excretion = HSD.privacy.excretion;
        const psy = HSD.mind.pregPsy;
        const pregStage = HSD.pregnancy.pregStage;
        const gestSac = HSD.pregnancy.gestSac;
        const fetus = HSD.pregnancy.fetus;
        const deliveryState = HSD.delivery.deliveryState;
        const deliveryProgress = HSD.delivery.deliveryProgress;

        const val = (arr, idx) => {
            if (!arr || arr[idx] === undefined || arr[idx] === null) return '';
            const v = String(arr[idx]).trim();
            return v === '' || v === 'Không' || v === 'Không có dữ liệu' ? '' : v;
        };

        const lines = [];

        let hasAny = false;

        if (st.length > 0) {
            hasAny = true;
            const date = val(st, 0);
            const time = val(st, 1);
            const loc = val(st, 2);
            const weather = val(st, 3);
            const cycle = val(st, 4);
            const lastPeriod = val(st, 5);
            const ovulation = val(st, 6);
            const dangerWindow = val(st, 7);
            let days = val(st, 8);
            const ga = val(st, 9);

            if (days && !/ngày$/.test(days)) days = days + ' ngày';

            lines.push('【Thời gian, không gian và chu kỳ thai kỳ】');
            lines.push(`Ngày: ${date || 'Không'}; Giờ: ${time || 'Không'}; Địa điểm: ${loc || 'Không'}; Thời tiết: ${weather || 'Không'}.`);
            if (cycle || lastPeriod || days || ga) {
                let period = 'Giai đoạn chu kỳ:' + (cycle || 'Không') + '; ';
                period += 'Kỳ kinh cuối: ' + (lastPeriod || 'Không') + '; cách nay ' + (days || 'Không') + '; ';
                if (ovulation) period += 'Dự đoán ngày rụng trứng: ' + ovulation + '; ';
                if (dangerWindow) period += 'Khoảng nguy hiểm: ' + dangerWindow + '; ';
                if (ga) period += 'Thai kỳ: ' + ga + '; ';
                lines.push(period);
            }
            lines.push('');
        }

        if (pf.length > 0) {
            hasAny = true;
            const name = val(pf, 0);
            const lookAge = val(pf, 1);
            const actualAge = val(pf, 2);
            const bloodType = val(pf, 4);
            lines.push('【Trạng thái nhân vật】');
            lines.push(`Họ tên: ${name || 'Không'}; Tuổi thật: ${actualAge || 'Không'}; Tuổi bề ngoài: ${lookAge || 'Không'}; Nhóm máu: ${bloodType || 'Không'}.`);
            lines.push('');
        }

        if (ch.length > 0) {
            hasAny = true;
            const appearance = val(ch, 0);
            const style = val(ch, 1);
            const socialEval = val(ch, 3);
            const sexualAppeal = val(ch, 4);
            const bodyScent = val(ch, 5);
            const privateScent = val(ch, 6);
            lines.push('【Sức hút và khí chất】');
            lines.push(`Ngoại hình: ${appearance || 'Không'}; Phong cách sức hút: ${style || 'Không'}.`);
            lines.push(`Đánh giá xã hội: ${socialEval || 'Không'}; Sức hấp dẫn tình dục: ${sexualAppeal || 'Không'}.`);
            if (bodyScent || privateScent) {
                lines.push(`Mùi hương cơ thể: ${bodyScent || 'Không'}; Mùi vùng kín: ${privateScent || 'Không'}.`);
            }
            lines.push('');
        }

        if (state.length > 0) {
            hasAny = true;
            const currentPose = val(state, 0);
            const mood = val(state, 2);
            const libido = val(state, 3);
            const wetness = val(state, 4);
            const clitoral = val(state, 5);
            const semen = val(state, 11);
            const fertilized = val(state, 12);
            const remaining = val(state, 13);
            lines.push('【Sinh lý và dục vọng tức thời】');
            lines.push(`Tư thế hiện tại: ${currentPose || 'Không'}; Cảm xúc: ${mood || 'Không'}.`);
            lines.push(`Ham muốn tình dục: ${libido || 'Không'}; Độ ẩm vùng kín: ${wetness || 'Không'}; Âm vật cương: ${clitoral || 'Không'}.`);
            if (semen) lines.push(`Tinh dịch trong cơ thể: ${semen}.`);
            if (fertilized || remaining) lines.push(`Trứng thụ tinh: đã thụ tinh ${fertilized || '0'}, còn chờ thụ tinh ${remaining || '0'}.`);
            lines.push('');
        }

        if (psy.length >= 9) {
            hasAny = true;
            const bellyExpose = val(psy, 0);
            const publicSuspect = val(psy, 1);
            const selfAware = val(psy, 2);
            const fertilizationFear = val(psy, 3);
            const fetusAccept = val(psy, 4);
            const maternalSprout = val(psy, 5);
            const fatherGuess = val(psy, 6);
            const babyCountGuess = val(psy, 7);
            const genderPref = val(psy, 8);
            lines.push('【Tâm lý thai kỳ và trạng thái ẩn】');
            lines.push(`Lộ bụng bầu: ${bellyExpose || 'Không'}; Người ngoài nghi ngờ mang thai: ${publicSuspect || 'Không'}; Tự nhận ra mang thai: ${selfAware || 'Không'}.`);
            lines.push(`Sợ thụ thai: ${fertilizationFear || 'Không'}; Chấp nhận thai nhi: ${fetusAccept || 'Không'}; Tình mẫu tử nảy sinh: ${maternalSprout || 'Không'}.`);
            if (fatherGuess || babyCountGuess || genderPref) {
                lines.push(`Đoán cha đứa bé: ${fatherGuess || 'Không'}; Ước đoán số thai: ${babyCountGuess || 'Không'}; Giới tính mong muốn: ${genderPref || 'Không'}.`);
            }
            lines.push('');
        }

        if (breast.length > 0 || excretion.length > 0) {
            hasAny = true;
            lines.push('【Gánh nặng cơ thể】');
            if (breast.length > 0) {
                const milk = val(breast, 0);
                if (milk) lines.push(`Dung tích sữa tuyến vú: ${milk}.`);
            }
            if (excretion.length > 0) {
                const urine = val(excretion, 0);
                const feces = val(excretion, 2);
                if (urine) lines.push(`Nước tiểu trong bàng quang: ${urine}.`);
                if (feces) lines.push(`Phân trong trực tràng: ${feces}.`);
            }
            lines.push('');
        }

        if (pregStage.length > 0 || gestSac.length > 0 || fetus.length > 0) {
            hasAny = true;
            lines.push('【Thai kỳ và sinh nở】');
            if (pregStage.length > 0) {
                const fertilizeDate = val(pregStage, 0);
                const fertilizePos = val(pregStage, 1);
                const implantDate = val(pregStage, 4);
                const birthDate = val(pregStage, 8);
                let stage = '';
                if (fertilizeDate) stage += `Thụ tinh: ${fertilizeDate}`;
                if (fertilizePos) stage += `; Tư thế thụ tinh: ${fertilizePos}`;
                if (implantDate) stage += `; Làm tổ: ${implantDate}`;
                if (birthDate) stage += `; Sinh/dự sinh: ${birthDate}`;
                if (stage) lines.push(stage + '.');
            }
            if (gestSac.length > 0) {
                const eggCount = val(gestSac, 0);
                const genderDist = val(gestSac, 1);
                const speciesDist = val(gestSac, 2);
                const sacStruct = val(gestSac, 3);
                const placentaPos = val(gestSac, 4);
                const spermProvider = val(gestSac, 5);
                let sac = `Số trứng thụ tinh: ${eggCount || 'Không'}`;
                if (genderDist) sac += `; Phân bố giới tính: ${genderDist}`;
                if (speciesDist) sac += `; Phân bố loài: ${speciesDist}`;
                if (sacStruct) sac += `; Màng đệm - màng ối: ${sacStruct}`;
                if (placentaPos) sac += `; Vị trí bám nhau: ${placentaPos}`;
                if (spermProvider) sac += `; Người cung cấp tinh trùng: ${spermProvider}`;
                lines.push(sac + '.');
            }
            if (fetus.length > 0) {
                const fetalCount = val(fetus, 0);
                const fetalGender = val(fetus, 1);
                const fetalPos = val(fetus, 3);
                const develop = val(fetus, 4);
                const active = val(fetus, 5);
                const movementPref = val(fetus, 6);
                const fetalAtmo = val(fetus, 7);
                let f = `Số thai: ${fetalCount || 'Không'}`;
                if (fetalGender) f += `; Giới tính: ${fetalGender}`;
                if (fetalPos) f += `; Ngôi thai: ${fetalPos}`;
                if (develop) f += `; Phát triển: ${develop}`;
                if (active) f += `; Hoạt động: ${active}`;
                if (movementPref) f += `; Cử động thai ưa thích: ${movementPref}`;
                if (fetalAtmo) f += `; Bầu không khí trong tử cung: ${fetalAtmo}`;
                lines.push(f + '.');
            }
            lines.push('');
        }

        if (deliveryState.length > 0 || deliveryProgress.length > 0) {
            hasAny = true;
            if (deliveryState.length > 0) {
                const cervix = val(deliveryState, 0);
                const deliveryPose = val(deliveryState, 1);
                const deliveryFeel = val(deliveryState, 2);
                const deliveryEmo = val(deliveryState, 3);
                const duration = val(deliveryState, 4);
                const contraction = val(deliveryState, 5);
                const laborSource = val(deliveryState, 6);
                let d = `Cổ tử cung: ${cervix || 'Không'}`;
                if (deliveryPose) d += `; Tư thế sinh: ${deliveryPose}`;
                if (deliveryFeel) d += `; Cảm giác: ${deliveryFeel}`;
                if (deliveryEmo) d += `; Cảm xúc: ${deliveryEmo}`;
                if (duration) d += `; Thời gian kéo dài: ${duration}`;
                if (contraction) d += `; Cơn co: ${contraction}`;
                if (laborSource) d += `; Nguồn sức rặn: ${laborSource}`;
                lines.push(d + '.');
            }
            if (deliveryProgress.length > 0) {
                const delivered = val(deliveryProgress, 0);
                const delivering = val(deliveryProgress, 1);
                const waiting = val(deliveryProgress, 2);
                if (delivered) lines.push(`Đã sinh: ${delivered}.`);
                if (delivering) lines.push(`Đang sinh: ${delivering}.`);
                if (waiting) lines.push(`Đã lọt khung chờ sinh: ${waiting}.`);
            }
            lines.push('');
        }

        if (!hasAny) return '';
        return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
        } finally {
            Object.assign(HSD, snapshot);
        }
    }

    function setChatInputText(text) {
        try {
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/setinput ${escapeForST(text)}`);
                showToast('Bản tóm tắt đã được điền vào ô nhập, có thể chỉnh sửa tiếp rồi gửi.', 'success');
                return true;
            }
            console.warn('[ heroine_status_widget ] triggerSlash giao diện chưa sẵn sàng.');
        } catch (e) {
            console.error('Điền phản hồi thất bại:', e);
            showToast('Phản hồi thất bại: ' + e.message, 'error');
        }
        return false;
    }

    const getCheckedHeroineTabs = () => tabs.filter(t => t && t.checked !== false && !t.isWomen && !t.isMen);
    const getCheckedArchiveTabs = () => tabs.filter(t => t && t.checked !== false && (t.isWomen || t.isMen));

    // Hàm thuần: trả về khối phản hồi hồ sơ nữ chính hoàn chỉnh; không có lựa chọn hoặc không có dữ liệu thì trả về ''
    function buildHeroineFeedbackBlock() {
        const parts = [];
        getCheckedHeroineTabs().forEach(tab => {
            const raw = getSavedStatusRaw(tab.id);
            if (!raw) return;
            const text = buildHeroineFeedbackText(raw);
            if (text) parts.push('▌' + tab.name + '\n' + text);
        });
        if (!parts.length) return '';
        return '<<<Phản hồi hồ sơ nữ chính>>>\n----\n' + parts.join('\n\n') + '\n----\n<<<Kết thúc phản hồi hồ sơ nữ chính>>>';
    }

    function feedbackHeroineToChat() {
        if (!getCheckedHeroineTabs().length) { showToast('Hãy chọn bảng trạng thái nữ chính trước.', 'warning'); return; }
        const block = buildHeroineFeedbackBlock();
        if (!block) { showToast('Các bảng trạng thái đã chọn chưa có dữ liệu dùng được, hãy đồng bộ trước.', 'warning'); return; }
        setChatInputText(block);
    }

    function buildArchiveFeedbackText(kind, tabId) {
        const isWomen = kind === 'women';
        const state = isWomen ? readWomenState(tabId) : readMenState(tabId);
        const list = isWomen ? state.women : state.men;
        const groups = isWomen ? WOMEN_GROUPS : MEN_GROUPS;
        const fields = isWomen ? WOMEN_FIELDS : MEN_FIELDS;
        const present = list.filter(p => p.presence !== 'left');
        if (!present.length) return '';
        const lines = [];
        present.forEach(p => {
            lines.push('▌' + (p.fields[0] || 'Chưa đặt tên'));
            groups.forEach(g => {
                const parts = [];
                g.fields.forEach(label => {
                    const idx = fields.indexOf(label);
                    let v = p.fields[idx];
                    if (!v || v === 'Không') return;
                    if (label === 'Danh sách con cái') {
                        const rows = parseChildRows(v);
                        if (!rows.length) return;
                        v = rows.map(r => r[0] + ' (' + r[1] + ', ' + r[2] + ', ' + r[3] + ')').join(', ');
                    }
                    parts.push(label + ': ' + v);
                });
                if (parts.length) lines.push('【' + g.title + '】' + parts.join('; ') + '.');
            });
            lines.push('');
        });
        return lines.join('\n').trim();
    }

    // Hàm thuần: trả về khối phản hồi hồ sơ sinh lý hoàn chỉnh; không có lựa chọn hoặc không có dữ liệu thì trả về ''
    function buildArchiveFeedbackBlock() {
        const parts = [];
        getCheckedArchiveTabs().forEach(tab => {
            const text = buildArchiveFeedbackText(tab.isWomen ? 'women' : 'men', tab.id);
            if (text) parts.push('【' + (tab.isWomen ? 'Hồ sơ sinh lý nữ' : 'Hồ sơ sinh lý nam') + '】\n' + text);
        });
        if (!parts.length) return '';
        return '<<<Phản hồi hồ sơ sinh lý>>>\n----\n' + parts.join('\n\n') + '\n----\n<<<Kết thúc phản hồi hồ sơ sinh lý>>>';
    }

    function feedbackArchiveToChat() {
        if (!getCheckedArchiveTabs().length) { showToast('Hãy chọn hồ sơ sinh lý (nữ hoặc nam) trước.', 'warning'); return; }
        const block = buildArchiveFeedbackBlock();
        if (!block) { showToast('Các hồ sơ sinh lý đã chọn chưa có dữ liệu dùng được, hãy đồng bộ trước.', 'warning'); return; }
        setChatInputText(block);
    }

    // Ghép văn bản phản hồi tự động theo autoFeedbackContent; không có dữ liệu thì trả về ''
    function buildAutoFeedbackText(cfg) {
        const content = AUTO_FEEDBACK_CONTENTS.includes(cfg && cfg.autoFeedbackContent) ? cfg.autoFeedbackContent : 'both';
        const blocks = [];
        if (content !== 'archive') blocks.push(buildHeroineFeedbackBlock());
        if (content !== 'heroine') blocks.push(buildArchiveFeedbackBlock());
        return blocks.filter(Boolean).join('\n\n');
    }

    // ==================== Tự động hóa (sự kiện Tavern Helper) ====================
    const HAS_TAVERN_EVENTS = typeof eventOn === 'function' && typeof tavern_events !== 'undefined';
    const AUTO_SYNC_TYPES = ['normal', 'regenerate', 'swipe', 'continue'];
    const AUTO_SYNC_DEBOUNCE_MS = 1500;
    const AUTO_SYNC_WAIT_MAX_MS = 60000;
    const AUTO_FEEDBACK_INJECT_ID = 'hsw_auto_feedback';
    const autoEventStops = [];
    let autoSyncTimer = null;
    let autoSyncRequestedAt = 0; // Thời điểm câu trả lời gần nhất kích hoạt tự động đồng bộ
    let autoSyncWaitTimer = null;
    let autoInjectWarned = false;
    let autoInjectTimer = null;
    const AUTO_FEEDBACK_INJECT_TTL_MS = 5 * 60 * 1000;

    // Đọc một tầng; thất bại thì trả về null
    function getChatMessageSafe(messageId) {
        try {
            if (typeof getChatMessages !== 'function' || messageId === undefined || messageId === null) return null;
            const list = getChatMessages(messageId);
            return (Array.isArray(list) && list[0]) || null;
        } catch (e) {
            return null;
        }
    }

    // Khi giao diện chèn không khả dụng thì lùi về “Nối vào nội dung”
    function getEffectiveFeedbackMode(cfg) {
        if (cfg.autoFeedbackMode === 'append') return 'append';
        if (typeof injectPrompts === 'function') return 'inject';
        if (!autoInjectWarned) {
            autoInjectWarned = true;
            console.warn('[Thanh trạng thái nữ chính] injectPrompts không khả dụng, phản hồi tự động chuyển sang nối vào tin nhắn người chơi.');
        }
        return 'append';
    }

    // Chống dội: các sự kiện trả lời liên tiếp gộp thành một lần tự động đồng bộ
    function scheduleAutoSync() {
        if (autoSyncTimer) clearTimeout(autoSyncTimer);
        autoSyncTimer = setTimeout(runAutoSync, AUTO_SYNC_DEBOUNCE_MS);
    }

    // Khi đang đồng bộ: thăm dò chờ kết thúc rồi chạy bù một lần (chờ tối đa khoảng 60 giây)
    function waitThenAutoSync() {
        if (autoSyncWaitTimer) return; // Đang chờ rồi, gộp lại
        const start = Date.now();
        autoSyncWaitTimer = setInterval(() => {
            if (!isSyncing && !isBulkSyncing) {
                clearInterval(autoSyncWaitTimer);
                autoSyncWaitTimer = null;
                scheduleAutoSync();
            } else if (Date.now() - start > AUTO_SYNC_WAIT_MAX_MS) {
                clearInterval(autoSyncWaitTimer);
                autoSyncWaitTimer = null;
                console.warn('[Thanh trạng thái nữ chính] Chờ lần đồng bộ hiện tại kết thúc quá thời gian, đã bỏ lần tự động đồng bộ này.');
            }
        }, 1000);
    }

    async function runAutoSync() {
        autoSyncTimer = null;
        const cfg = getConfig();
        if (!cfg.autoSync) return;
        if (isSyncing || isBulkSyncing) { waitThenAutoSync(); return; }
        // Sau câu trả lời đã có một lần đồng bộ (như đồng bộ thủ công) bắt đầu và hoàn tất thì không đồng bộ lặp lại
        if (lastCompletedSyncStartedAt > autoSyncRequestedAt) {
            console.log('[Thanh trạng thái nữ chính] Sau câu trả lời đã đồng bộ xong, bỏ qua lần tự động đồng bộ này.');
            return;
        }
        try {
            // Dùng cấu hình đã lưu (cách chạy theo cài đặt; trong lúc “Chạy gốc” sẽ tạm chuyển preset hiện tại của Tavern, khi bắt đầu sẽ nhắc người chơi)
            const res = await syncCheckedTabs(false, { cfgOverride: { ...cfg }, auto: true });
            console.log('[Thanh trạng thái nữ chính] Kết quả tự động đồng bộ:', res);
        } catch (e) {
            console.warn('[Thanh trạng thái nữ chính] Tự động đồng bộ thất bại', e);
        }
    }

    function onAutoSyncMessageReceived(messageId, type) {
        try {
            if (!getConfig().autoSync) return;
            if (!AUTO_SYNC_TYPES.includes(type || 'normal')) return;
            const msg = getChatMessageSafe(messageId);
            if (msg && (msg.role === 'user' || msg.is_user)) return;
            autoSyncRequestedAt = Date.now();
            scheduleAutoSync();
        } catch (e) {
            console.warn('[Thanh trạng thái nữ chính] Xử lý sự kiện tự động đồng bộ thất bại', e);
        }
    }

    // Gỡ phần chèn phản hồi tự động (gọi khi tạo xong / dừng / chuyển chat / hết hạn / gỡ script)
    function clearAutoFeedbackInjection() {
        if (autoInjectTimer) { clearTimeout(autoInjectTimer); autoInjectTimer = null; }
        try { if (typeof uninjectPrompts === 'function') uninjectPrompts([AUTO_FEEDBACK_INJECT_ID]); } catch (e) {}
    }

    // Chế độ “Chèn tạm thời”: chèn phản hồi trước lượt tạo chính, gỡ ngay sau khi tạo xong.
    // Không xét isSyncing: tự động đồng bộ thường diễn ra cùng lúc người chơi gửi tin nhắn tiếp theo, nếu xét sẽ đúng lúc bỏ mất trường hợp phổ biến nhất.
    // Yêu cầu đồng bộ của chính script đi qua generate() của Tavern Helper, không qua Generate() của Tavern, nên không kích hoạt sự kiện này;
    // phần chèn chỉ tồn tại trong lúc tạo chính, nếu lúc đó có yêu cầu đồng bộ cũng đọc được khối phản hồi thì cũng vô hại.
    function onAutoFeedbackBeforeGenerate(type, option, dryRun) {
        try {
            if (dryRun) return;
            const cfg = getConfig();
            if (!cfg.autoFeedback) return;
            if (type === 'quiet' || type === 'impersonate') return;
            if (option && option.quiet_prompt) return;
            if (getEffectiveFeedbackMode(cfg) !== 'inject') return;
            clearAutoFeedbackInjection();
            const text = buildAutoFeedbackText(cfg);
            if (!text) { console.log('[Thanh trạng thái nữ chính] Phản hồi tự động: chưa có dữ liệu dùng được, không chèn.'); return; }
            injectPrompts([{
                id: AUTO_FEEDBACK_INJECT_ID,
                position: 'in_chat',
                depth: 0,
                role: 'system',
                content: text,
                should_scan: false
            }]);
            // Dự phòng: khi mất sự kiện kết thúc tạo, khoảng 5 phút sau tự gỡ
            autoInjectTimer = setTimeout(() => {
                autoInjectTimer = null;
                clearAutoFeedbackInjection();
            }, AUTO_FEEDBACK_INJECT_TTL_MS);
            console.log('[Thanh trạng thái nữ chính] Phản hồi tự động: đã chèn tạm thời (' + text.length + ' ký tự).');
        } catch (e) {
            console.warn('[Thanh trạng thái nữ chính] Chèn phản hồi tự động thất bại', e);
        }
    }

    // Chế độ “Nối vào nội dung”: sau khi tin nhắn người chơi được ghi vào tầng thì nối phản hồi (đợi ghi xong để prompt dựng sau đó có chứa nó)
    async function onAutoFeedbackMessageSent(messageId) {
        try {
            const cfg = getConfig();
            if (!cfg.autoFeedback) return;
            if (getEffectiveFeedbackMode(cfg) !== 'append') return;
            if (typeof setChatMessages !== 'function') return;
            const msg = getChatMessageSafe(messageId);
            if (!msg || !(msg.role === 'user' || msg.is_user)) return;
            const body = String(msg.message || '');
            if (body.includes('<<<Phản hồi hồ sơ nữ chính>>>') || body.includes('<<<Phản hồi hồ sơ sinh lý>>>')) return;
            const text = buildAutoFeedbackText(cfg);
            if (!text) { console.log('[Thanh trạng thái nữ chính] Phản hồi tự động: chưa có dữ liệu dùng được, không nối.'); return; }
            await setChatMessages([{ message_id: messageId, message: body + '\n\n' + text }], { refresh: 'affected' });
            console.log('[Thanh trạng thái nữ chính] Phản hồi tự động: đã nối vào tầng ' + messageId + ' .');
        } catch (e) {
            console.warn('[Thanh trạng thái nữ chính] Nối phản hồi tự động thất bại', e);
        }
    }

    // Hủy lần tự động đồng bộ chưa chạy (đang chống dội / đang chờ)
    function cancelPendingAutoSync() {
        if (autoSyncTimer) { clearTimeout(autoSyncTimer); autoSyncTimer = null; }
        if (autoSyncWaitTimer) { clearInterval(autoSyncWaitTimer); autoSyncWaitTimer = null; }
        autoSyncRequestedAt = 0;
    }

    // Chuyển chat: các lần tự động đồng bộ chờ chạy và phần chèn phản hồi của chat cũ đều bị hủy
    function onAutomationChatChanged() {
        cancelPendingAutoSync();
        clearAutoFeedbackInjection();
    }

    function registerAutomationEvents() {
        if (!HAS_TAVERN_EVENTS) {
            console.warn('[Thanh trạng thái nữ chính] Không phát hiện giao diện sự kiện của Tavern Helper, tự động đồng bộ / phản hồi tự động không dùng được.');
            const hint = qs('#cfg-auto-events-hint');
            if (hint) hint.style.display = '';
            return;
        }
        const on = (eventType, listener) => {
            if (!eventType) return;
            try {
                const handle = eventOn(eventType, listener);
                if (handle && typeof handle.stop === 'function') autoEventStops.push(handle);
            } catch (e) {
                console.warn('[Thanh trạng thái nữ chính] Đăng ký sự kiện thất bại: ' + eventType, e);
            }
        };
        on(tavern_events.MESSAGE_RECEIVED, onAutoSyncMessageReceived);
        on(tavern_events.GENERATION_AFTER_COMMANDS, onAutoFeedbackBeforeGenerate);
        on(tavern_events.MESSAGE_SENT, onAutoFeedbackMessageSent);
        // Gỡ phần chèn khi lượt tạo chính kết thúc / dừng / chuyển chat
        on(tavern_events.GENERATION_ENDED, clearAutoFeedbackInjection);
        on(tavern_events.GENERATION_STOPPED, clearAutoFeedbackInjection);
        on(tavern_events.CHAT_CHANGED, onAutomationChatChanged);
    }

    function unregisterAutomationEvents() {
        autoEventStops.splice(0).forEach(h => { try { h.stop(); } catch (e) {} });
        cancelPendingAutoSync();
        clearAutoFeedbackInjection();
    }

    // ==================== Chuyển giao diện ====================
    // Snapshot cấu hình khi vào trang cài đặt (dùng để xét có sửa đổi chưa lưu khi rời đi)
    let settingsConfigSnapshot = null;
    // Vị trí cuộn của bảng trước khi vào cài đặt, khôi phục khi quay lại
    let dashboardScrollTop = 0;

    // Trạng thái nút biểu tượng ở đầu: nút ứng với trang hiện tại chuyển thành “Quay lại bảng”
    function setHeaderToggleButton(btn, active, activeTitle, idleTitle, idleHtml) {
        if (!btn) return;
        btn.title = active ? activeTitle : idleTitle;
        btn.setAttribute('aria-label', btn.title);
        btn.innerHTML = active ? '<i class="fas fa-arrow-left"></i>' : idleHtml;
    }
    function updateSettingsButtonState() {
        setHeaderToggleButton(qs('#btn-settings'), currentPanelView === 'settings', 'Quay lại bảng trạng thái', 'API Cài đặt', '<i class="fas fa-cog"></i>');
        setHeaderToggleButton(qs('#btn-dev-log'), currentPanelView === 'devlog', 'Quay lại bảng trạng thái', 'Xem câu trả lời gốc của mô hình', '🐞');
        replaceIcons();
    }

    // Thu thập và lưu cấu hình từ giao diện (dùng chung cho nút lưu trên cùng và tự lưu)
    function saveConfigFromUI() {
        const cfg = collectConfigFromUI();
        saveConfig(cfg);
        settingsConfigSnapshot = JSON.stringify(cfg);
        updateFooterInfo();
        return cfg;
    }

    // Rời trang cài đặt: có sửa đổi chưa lưu thì tự lưu, rồi ẩn trang cài đặt (dùng chung cho mọi đường thoát)
    function leaveSettingsIfNeeded() {
        if (currentPanelView !== 'settings') return;
        try {
            const current = JSON.stringify(collectConfigFromUI());
            if (settingsConfigSnapshot !== null && current !== settingsConfigSnapshot) {
                saveConfigFromUI();
                showToast('Đã tự lưu cấu hình', 'success');
            }
        } catch (e) {
            console.warn('[ heroine_status_widget ] Tự lưu cấu hình thất bại', e);
        }
        settingsConfigSnapshot = null;
        panel.classList.remove('settings-open');
        qs('#settings-view').classList.remove('active');
    }
    // Rời trang nhật ký nhà phát triển
    function leaveDevLogIfNeeded() {
        if (currentPanelView !== 'devlog') return;
        panel.classList.remove('devlog-open');
        qs('#devlog-view')?.classList.remove('active');
    }
    // Ghi lại vị trí cuộn của bảng trước khi vào trang con
    function rememberDashboardScroll() {
        if (currentPanelView !== 'dashboard') return;
        const scroller = qs('#panel-scroll');
        if (scroller) dashboardScrollTop = scroller.scrollTop;
    }

    function switchToDashboard() {
        const wasSubView = currentPanelView !== 'dashboard';
        leaveSettingsIfNeeded();
        leaveDevLogIfNeeded();
        currentPanelView = 'dashboard';
        panel.classList.remove('settings-open', 'devlog-open');
        qs('#dashboard-view').style.display = 'block';
        qs('#settings-view').classList.remove('active');
        qs('#devlog-view')?.classList.remove('active');
        if (wasSubView) {
            updateSettingsButtonState();
            const scroller = qs('#panel-scroll');
            if (scroller) scroller.scrollTop = dashboardScrollTop;
        }
    }
    function switchToSettings() {
        const scroller = qs('#panel-scroll');
        // Đang ở trang cài đặt thì không tải lại, tránh đè mất sửa đổi chưa lưu
        if (currentPanelView === 'settings') {
            if (scroller) scroller.scrollTop = 0;
            return;
        }
        rememberDashboardScroll();
        leaveDevLogIfNeeded();
        currentPanelView = 'settings';
        panel.classList.add('settings-open');
        qs('#dashboard-view').style.display = 'none';
        qs('#settings-view').classList.add('active');
        loadConfigToUI();
        settingsConfigSnapshot = JSON.stringify(collectConfigFromUI());
        updateSettingsButtonState();
        if (scroller) scroller.scrollTop = 0;
    }
    function switchToDevLog() {
        if (!DEV_MODE || !qs('#devlog-view')) return;
        const scroller = qs('#panel-scroll');
        if (currentPanelView !== 'devlog') {
            rememberDashboardScroll();
            leaveSettingsIfNeeded();
            currentPanelView = 'devlog';
            panel.classList.add('devlog-open');
            qs('#dashboard-view').style.display = 'none';
            qs('#devlog-view').classList.add('active');
            updateSettingsButtonState();
        }
        renderDevLog();
        if (scroller) scroller.scrollTop = 0;
    }

    // Khi đang tự động đồng bộ giữ tiền tố nhắc; kết thúc rồi (syncCfgOverride đã xóa) thì khôi phục chữ thường
    function updateFooterInfo() {
        updateFooterInfoBase();
        if (syncCfgOverride) {
            const el = qs('#footer-info');
            if (el) el.textContent = withAutoSyncPrefix(el.textContent);
        }
    }

    function updateFooterInfoBase() {
        try {
            const tab = getActiveTab();
            if (tab && tab.isWomen) {
                const st = readWomenState();
                const clock = [st.date, st.time].filter(Boolean).join(' ');
                const leftCount = st.women.filter(w => w.presence === 'left').length;
                qs('#footer-info').textContent = 'Hồ sơ nữ: ' + st.women.length + ' người' + (leftCount ? ' (rời cảnh ' + leftCount + ')' : '') + (clock ? ' · ' + clock : ' · chờ đồng bộ');
                return;
            }
            if (tab && tab.isMen) {
                const st = readMenState();
                const clock = [st.date, st.time].filter(Boolean).join(' ');
                const leftCount = st.men.filter(w => w.presence === 'left').length;
                qs('#footer-info').textContent = 'Hồ sơ nam: ' + st.men.length + ' người' + (leftCount ? ' (rời cảnh ' + leftCount + ')' : '') + (clock ? ' · ' + clock : ' · chờ đồng bộ');
                return;
            }
            const raw = getSavedStatusRaw();
            if (raw) {
                const m = raw.match(/\[SpaceTime\|([^|\]]+)\|([^|\]]+)/);
                if (m) {
                    qs('#footer-info').textContent = `Trạng thái gần nhất: ${m[1]} ${m[2]}`;
                    return;
                }
                qs('#footer-info').textContent = 'Đã có dữ liệu thanh trạng thái';
                return;
            }
            qs('#footer-info').textContent = 'Đang chờ đồng bộ lần đầu';
        } catch (e) {
            qs('#footer-info').textContent = 'Đang chờ đồng bộ lần đầu';
        }
    }

    // ==================== Mở/đóng bảng ====================
    // Xét điện thoại màn hình dọc: giữ đồng nhất với breakpoint 760px của CSS
    function isMobileLayout() {
        try { return (targetWindow.innerWidth || 0) <= 760; } catch (e) { return false; }
    }

    function openPanel() {
        currentState = 'PANEL_OPEN';
        ball.classList.add('hidden');
        panel.inert = false;
        panel.classList.add('show');
        if (isMobileLayout()) {
            // Điện thoại dọc: tràn toàn màn hình, căn góc trên trái
            panel.style.left = '0px';
            panel.style.top = '0px';
        } else {
            const panelWidth = panel.offsetWidth || PANEL_WIDTH;
            const panelHeight = panel.offsetHeight || 600;
            const pLeft = Math.max(SAFE_MARGIN, (targetWindow.innerWidth - panelWidth) / 2);
            const pTop = Math.max(SAFE_MARGIN, (targetWindow.innerHeight - panelHeight) / 2);
            panel.style.left = pLeft + 'px';
            panel.style.top = pTop + 'px';
            enforceBounds(panel, false);
        }
        switchToDashboard();
    }
    function closePanel() {
        // Khi đóng ở trang cài đặt / nhật ký thì đi theo quy trình quay lại bảng trước (tự lưu, đặt lại trạng thái)
        if (currentPanelView !== 'dashboard') switchToDashboard();
        currentState = 'IDLE';
        panel.classList.remove('show');
        panel.inert = true;
        ball.classList.remove('hidden');
        enforceBounds(ball, true);
    }

    // ==================== Ràng buộc biên ====================
    function enforceBounds(el, isBall) {
        // Bảng toàn màn hình không còn chỗ để di chuyển, cố định góc trên trái
        if (!isBall && isMobileLayout()) {
            el.style.left = '0px';
            el.style.top = '0px';
            return;
        }
        const w = el.offsetWidth;
        const h = el.offsetHeight;
        if (!w || !h) return;
        let left = parseFloat(el.style.left) || 0;
        let top = parseFloat(el.style.top) || 0;
        const maxLeft = targetWindow.innerWidth - w - SAFE_MARGIN;
        const maxTop = isBall
            ? targetWindow.innerHeight - h - SAFE_MARGIN
            : targetWindow.innerHeight - h - SAFE_MARGIN;
        el.style.left = Math.max(SAFE_MARGIN, Math.min(left, maxLeft)) + 'px';
        el.style.top = Math.max(SAFE_MARGIN, Math.min(top, maxTop)) + 'px';
    }

    // ==================== Tính năng kéo thả ====================
    function makeDraggable(element, handle, isBall) {
        let startX = 0;
        let startY = 0;
        let initialLeft = 0;
        let initialTop = 0;
        let dragScale = 1;
        let isDragging = false;
        let gestureActive = false;
        let activePointer = null;
        let lastMoveEvent = null;
        const usePointer = !!targetWindow.PointerEvent;

        const pointOf = (e) => {
            if (e.touches && e.touches[0]) return { x: e.touches[0].clientX, y: e.touches[0].clientY };
            if (e.changedTouches && e.changedTouches[0]) return { x: e.changedTouches[0].clientX, y: e.changedTouches[0].clientY };
            return { x: e.clientX, y: e.clientY };
        };

        const readScale = () => {
            try {
                const z = parseFloat(targetWindow.getComputedStyle(element).zoom);
                if (Number.isFinite(z) && z > 0) return z;
            } catch (e) {}
            return 1;
        };

        const onDown = (e) => {
            if (isBall && currentState !== 'IDLE') return;
            if (!isBall && currentState !== 'PANEL_OPEN' && currentState !== 'PANEL_DRAGGING') return;
            // Bảng trên điện thoại dọc là toàn màn hình, kéo bảng chỉ đẩy nội dung ra khỏi tầm nhìn
            if (!isBall && isMobileLayout()) return;
            if (e.pointerType === 'mouse' && e.button !== 0) return;
            // Nút/ô nhập trên thanh tiêu đề bảng trả lại cho chính control đó, không bắt đầu kéo
            if (!isBall && e.target && e.target.closest &&
                e.target.closest('button, a, input, select, textarea, label')) return;
            const p = pointOf(e);
            startX = p.x;
            startY = p.y;
            const rect = element.getBoundingClientRect();
            dragScale = readScale();
            initialLeft = parseFloat(element.style.left);
            initialTop = parseFloat(element.style.top);
            if (!Number.isFinite(initialLeft)) initialLeft = rect.left / dragScale;
            if (!Number.isFinite(initialTop)) initialTop = rect.top / dragScale;
            isDragging = false;
            gestureActive = true;
            activePointer = e.pointerId != null ? e.pointerId : 'legacy';
            if (usePointer && handle.setPointerCapture && e.pointerId != null) {
                try { handle.setPointerCapture(e.pointerId); } catch (err) {}
            }
            // Gắn cả vào tay cầm và document: khi bắt (capture) thành công sự kiện chỉ kích hoạt một lần ở tay cầm,
            // khi bắt thất bại/bị máy chủ ngắt vẫn nhận được move từ document.
            [handle, targetDocument].forEach((t) => {
                if (usePointer) {
                    t.addEventListener('pointermove', onMove, { passive: false });
                    t.addEventListener('pointerup', onUp);
                    t.addEventListener('pointercancel', onUp);
                } else {
                    t.addEventListener('mousemove', onMove, { passive: false });
                    t.addEventListener('touchmove', onMove, { passive: false });
                    t.addEventListener('mouseup', onUp);
                    t.addEventListener('touchend', onUp);
                }
            });
            handle.addEventListener('lostpointercapture', onUp);
            if (isBall) e.preventDefault();
        };

        const onMove = (e) => {
            if (!gestureActive) return;
            if (e === lastMoveEvent) return;
            lastMoveEvent = e;
            if (activePointer !== null && e.pointerId != null && e.pointerId !== activePointer) return;
            const p = pointOf(e);
            const rawDx = p.x - startX;
            const rawDy = p.y - startY;
            if (!isDragging) {
                if (Math.sqrt(rawDx * rawDx + rawDy * rawDy) > CLICK_DIST_THRESHOLD) {
                    isDragging = true;
                    element.classList.add('dragging');
                    currentState = isBall ? 'BALL_DRAGGING' : 'PANEL_DRAGGING';
                } else return;
            }
            if (e.cancelable) e.preventDefault();
            // Ghi style trực tiếp: không phụ thuộc requestAnimationFrame (iframe của script có thể bị giảm tần suất)
            element.style.left = (initialLeft + rawDx / dragScale) + 'px';
            element.style.top = (initialTop + rawDy / dragScale) + 'px';
        };

        const onUp = () => {
            if (!gestureActive) return;
            gestureActive = false;
            const targets = [targetDocument, handle];
            targets.forEach((t) => {
                t.removeEventListener('pointermove', onMove);
                t.removeEventListener('pointerup', onUp);
                t.removeEventListener('pointercancel', onUp);
                t.removeEventListener('mousemove', onMove);
                t.removeEventListener('touchmove', onMove);
                t.removeEventListener('mouseup', onUp);
                t.removeEventListener('touchend', onUp);
            });
            handle.removeEventListener('lostpointercapture', onUp);
            try {
                if (usePointer && handle.releasePointerCapture && activePointer !== 'legacy' && activePointer != null) {
                    handle.releasePointerCapture(activePointer);
                }
            } catch (err) {}
            if (!isDragging) {
                if (isBall) openPanel();
            } else {
                element.classList.remove('dragging');
                if (isBall) {
                    snapBallToEdge();
                } else {
                    currentState = 'PANEL_OPEN';
                    enforceBounds(element, false);
                }
            }
            isDragging = false;
            activePointer = null;
            lastMoveEvent = null;
        };

        if (usePointer) {
            handle.addEventListener('pointerdown', onDown);
        } else {
            handle.addEventListener('mousedown', onDown);
            handle.addEventListener('touchstart', onDown, { passive: false });
        }
        handle.style.touchAction = 'none';
    }

    function snapBallToEdge() {
        const rect = ball.getBoundingClientRect();
        const targetLeft = (rect.left + rect.width / 2) < (targetWindow.innerWidth / 2)
            ? SAFE_MARGIN
            : targetWindow.innerWidth - rect.width - SAFE_MARGIN;
        ball.style.left = targetLeft + 'px';
        setTimeout(() => { if (currentState === 'BALL_DRAGGING') currentState = 'IDLE'; }, 250);
        currentState = 'IDLE';
    }

    // ==================== Điều chỉnh cửa sổ ====================
    targetWindow.addEventListener('resize', debounce(() => {
        if (currentState === 'PANEL_OPEN') {
            // Khi từ toàn màn hình điện thoại chuyển về kích thước desktop thì căn giữa lại (ở trạng thái toàn màn hình left/top luôn là 0)
            if (!isMobileLayout() && parseFloat(panel.style.left) === 0 && parseFloat(panel.style.top) === 0) {
                const w = panel.offsetWidth || PANEL_WIDTH;
                const h = panel.offsetHeight || 600;
                panel.style.left = Math.max(SAFE_MARGIN, (targetWindow.innerWidth - w) / 2) + 'px';
                panel.style.top = Math.max(SAFE_MARGIN, (targetWindow.innerHeight - h) / 2) + 'px';
            }
            enforceBounds(panel, false);
        } else if (currentState === 'IDLE') enforceBounds(ball, true);
    }, 150));

    // ==================== Gắn sự kiện ====================
    qs('#btn-close-panel').addEventListener('click', (e) => { e.stopPropagation(); closePanel(); });
    // Nút bánh răng là công tắc: bấm lần nữa trong trang cài đặt sẽ quay lại bảng
    qs('#btn-settings').addEventListener('click', (e) => {
        e.stopPropagation();
        if (currentPanelView === 'settings') switchToDashboard();
        else switchToSettings();
    });
    qs('#btn-book-export').addEventListener('click', (e) => { e.stopPropagation(); exportBook(); });
    qs('#btn-book-import').addEventListener('click', (e) => { e.stopPropagation(); importBook(); });
    qs('#btn-book-clear').addEventListener('click', (e) => { e.stopPropagation(); clearBook(); });
    qs('#btn-add-tab').addEventListener('click', (e) => { e.stopPropagation(); promptAndAddTab(); });
    qs('#btn-check-all').addEventListener('click', (e) => { e.stopPropagation(); toggleAllTabs(); });
    qs('#btn-add-woman').addEventListener('click', (e) => { e.stopPropagation(); promptAddWoman(); });
    qs('#women-view').addEventListener('click', handleWomenViewClick);
    qs('#btn-add-men').addEventListener('click', (e) => { e.stopPropagation(); promptAddMan(); });
    qs('#men-view').addEventListener('click', handleMenViewClick);
    qs('#btn-feedback-archive').addEventListener('click', (e) => { e.stopPropagation(); feedbackArchiveToChat(); });
    qs('#btn-feedback-heroine').addEventListener('click', (e) => { e.stopPropagation(); feedbackHeroineToChat(); });
    qs('#btn-back-dashboard-top').addEventListener('click', (e) => { e.stopPropagation(); switchToDashboard(); });
    qs('#btn-sync-status').addEventListener('click', (e) => {
        e.stopPropagation();
        if (currentPanelView !== 'dashboard') {
            showToast('Hãy quay lại bảng trạng thái rồi mới đồng bộ', 'info');
            return;
        }
        e.currentTarget.blur();
        syncCheckedTabs(false);
    });
    qs('#btn-repair-status').addEventListener('click', (e) => {
        e.stopPropagation();
        if (currentPanelView !== 'dashboard') {
            showToast('Hãy quay lại bảng trạng thái rồi mới sửa', 'info');
            return;
        }
        e.currentTarget.blur();
        syncCheckedTabs(true);
    });
    qs('#btn-revert-history').addEventListener('click', (e) => { e.stopPropagation(); revertToSelectedTimeline(); });
    qs('#btn-clear-history').addEventListener('click', (e) => { e.stopPropagation(); clearAllStatusAndHistory(); });
    qs('#btn-export-history').addEventListener('click', (e) => { e.stopPropagation(); exportStatusHistory(); });
    qs('#btn-import-history').addEventListener('click', (e) => { e.stopPropagation(); importStatusHistory(); });
    qs('#btn-connect-api').addEventListener('click', (e) => { e.stopPropagation(); connectApi(); });
    qs('#btn-test-mode-connection').addEventListener('click', (e) => { e.stopPropagation(); testModeConnection(); });
    if (DEV_MODE) {
        qs('#dev-log-select').addEventListener('change', (e) => { e.stopPropagation(); renderDevLog(parseInt(e.target.value, 10)); });
        qs('#dev-log-copy-response').addEventListener('click', (e) => { e.stopPropagation(); copyText(qs('#dev-log-response').value); });
        qs('#dev-log-copy-request').addEventListener('click', (e) => { e.stopPropagation(); copyText(qs('#dev-log-request').value); });
        qs('#dev-log-export').addEventListener('click', (e) => {
            e.stopPropagation();
            const blob = new Blob([JSON.stringify(getDevLog(), null, 2)], { type: 'application/json' });
            const a = targetDocument.createElement('a');
            a.href = URL.createObjectURL(blob);
            a.download = `Thanh trạng thái nữ chính - Nhật ký nhà phát triển-${Date.now()}.json`;
            targetDocument.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(() => URL.revokeObjectURL(a.href), 1000);
        });
        qs('#dev-log-clear').addEventListener('click', (e) => {
            e.stopPropagation();
            if (!confirm('Xóa toàn bộ nhật ký nhà phát triển?')) return;
            saveDevLog([]);
            renderDevLog();
        });
        // 🐞 nút là công tắc: bấm lần nữa trong trang nhật ký sẽ quay lại bảng
        qs('#btn-dev-log').addEventListener('click', (e) => {
            e.stopPropagation();
            if (currentPanelView === 'devlog') switchToDashboard();
            else switchToDevLog();
        });
        qs('#btn-back-dashboard-devlog').addEventListener('click', (e) => { e.stopPropagation(); switchToDashboard(); });
        qs('#btn-devlog-refresh').addEventListener('click', (e) => { e.stopPropagation(); renderDevLog(); });
        renderDevLog();
    }
    const onSaveConfigClick = (e) => {
        e.stopPropagation();
        saveConfigFromUI();
        showToast('API Lưu cấu hình thành công!', 'success');
    };
    qs('#btn-save-config-top').addEventListener('click', onSaveConfigClick);

    // Esc: trong trang cài đặt / nhật ký thì quay lại bảng trạng thái (không kích hoạt khi bộ gõ đang soạn chữ)
    const onSettingsEscKey = (e) => {
        if (e.key !== 'Escape' && e.key !== 'Esc') return;
        if (e.isComposing || e.keyCode === 229) return;
        if (!container.isConnected) return; // Phiên bản cũ đã bị gỡ (script tải lại) thì không phản hồi
        if (currentState !== 'PANEL_OPEN' || currentPanelView === 'dashboard') return;
        // Chỉ phản hồi khi tiêu điểm nằm trong bảng này hoặc không có ô nhập nào được chọn, tránh giành phím của chính Tavern: Esc
        const path = typeof e.composedPath === 'function' ? e.composedPath() : [];
        const inWidget = path.includes(container);
        const active = targetDocument.activeElement;
        const idle = !active || active === targetDocument.body || active === container;
        if (!inWidget && !idle) return;
        // Tiêu điểm ở trong bảng mới chặn sự kiện; không có tiêu điểm thì chỉ quay lại bảng, Esc vẫn tiếp tục giao cho Tavern xử lý
        if (inWidget) {
            e.preventDefault();
            e.stopPropagation();
        }
        switchToDashboard();
    };
    targetDocument.addEventListener('keydown', onSettingsEscKey, true);
    qs('#cfg-api-mode').addEventListener('change', (e) => { e.stopPropagation(); updateApiModeUI(); });
    qs('#cfg-profile-select').addEventListener('change', (e) => { e.stopPropagation(); updateProfileHint(); });
    qs('#cfg-preset-select').addEventListener('change', (e) => { e.stopPropagation(); updateApiModeUI(); });
    qs('#cfg-preset-format').addEventListener('change', (e) => { e.stopPropagation(); updatePresetHint(); });
    qs('#cfg-preset-run').addEventListener('change', (e) => { e.stopPropagation(); updatePresetHint(); });
    qs('#cfg-preset-api').addEventListener('change', (e) => { e.stopPropagation(); updateApiModeUI(); });
    qs('#cfg-auto-feedback').addEventListener('change', (e) => { e.stopPropagation(); updateAutomationUI(); });
    ['#cfg-auto-sync', '#cfg-auto-feedback-content', '#cfg-auto-feedback-mode'].forEach(sel => {
        qs(sel).addEventListener('change', (e) => e.stopPropagation());
    });
    qs('#btn-refresh-presets').addEventListener('click', (e) => {
        e.stopPropagation();
        const count = getPresetNamesSafe().length;
        renderPresetOptions(qs('#cfg-preset-select').value || '');
        showToast(count ? `Đã làm mới, có tổng cộng ${count} preset Chat Completion` : 'Không đọc được danh sách preset, hãy chắc chắn đã bật Tavern Helper', count ? 'success' : 'warning');
    });
    qs('#btn-reset-builtin-preset').addEventListener('click', async (e) => {
        e.stopPropagation();
        const exists = getPresetNamesSafe().includes(BUILTIN_PRESET_NAME);
        if (exists && !confirm(`Sẽ dùng nội dung tích hợp của script để ghi đè preset “${BUILTIN_PRESET_NAME}”, các sửa đổi của bạn với prompt trong đó (như “Phong cách nội dung”) sẽ mất. Tiếp tục?`)) return;
        try {
            await installBuiltinPreset(true);
            renderPresetOptions(qs('#cfg-preset-select').value || '');
            showToast(exists ? 'Đã đặt lại preset tích hợp' : 'Đã cài preset tích hợp', 'success');
        } catch (err) {
            showToast('Ghi preset tích hợp thất bại: ' + err.message, 'error');
        }
    });
    qs('#btn-refresh-profiles').addEventListener('click', (e) => {
        e.stopPropagation();
        const count = getSupportedProfilesSafe().length;
        renderProfileOptions(qs('#cfg-profile-select').value || '');
        showToast(count ? `Đã làm mới, có tổng cộng ${count} cấu hình kết nối khả dụng` : 'Không tìm thấy cấu hình kết nối Tavern khả dụng', count ? 'success' : 'warning');
    });
    qs('#cfg-model-select').addEventListener('change', (e) => {
        const val = e.target.value;
        if (val) {
            qs('#cfg-model-name').value = val;
        }
    });
    // Endpoint tùy chỉnh khi mất tiêu điểm/sửa đổi thì chuẩn hóa tại chỗ, để người dùng thấy địa chỉ gốc sau khi sửa
    const normalizeBaseUrlInput = (e) => {
        const fixed = normalizeBaseUrl(e.target.value);
        if (fixed !== e.target.value) e.target.value = fixed;
    };
    qs('#cfg-base-url').addEventListener('change', normalizeBaseUrlInput);
    qs('#cfg-base-url').addEventListener('blur', normalizeBaseUrlInput);

    // Khi ô nhập trong trang cài đặt mất tiêu điểm, đảm bảo trang chính không bị cuộn
    qsa('.form-input').forEach(inp => {
        inp.addEventListener('blur', () => {
            setTimeout(() => {
                try {
                    targetWindow.scrollTo(0, 0);
                    targetDocument.body.scrollTop = 0;
                } catch (e) {}
            }, 120);
        });
    });

    // ==================== Khởi tạo ====================
    makeDraggable(ball, ball, true);
    makeDraggable(panel, qs('#panel-header'), false);
    initTabs();
    initChartToggles();

    // Khởi tạo tab nhân vật
    tabs = loadTabs();
    if (!tabs.some(t => t.id === ADAPTIVE_TAB_ID)) {
        tabs.unshift({ id: ADAPTIVE_TAB_ID, name: 'Hồ sơ sinh lý nữ', isAdaptive: true, isWomen: true });
        saveTabsList(tabs);
    }
    renderTabBar();
    renderActiveTab();
    loadConfigToUI();
    updateFooterInfo();
    // Tự động đồng bộ / phản hồi tự động: sự kiện chỉ đăng ký một lần, khi kích hoạt sẽ xét theo cấu hình đã lưu có chạy hay không
    registerAutomationEvents();
    // Lần tải đầu tiên âm thầm cài preset tích hợp (đã có thì không động vào, giữ sửa đổi của người dùng)
    ensureBuiltinPresetSafe().then(installed => {
        if (installed) renderPresetOptions(qs('#cfg-preset-select').value || '');
    });
    enforceBounds(ball, true);
    replaceIcons();

    // ==================== Gỡ script ====================
    $(window).on('pagehide', () => {
        try { unregisterAutomationEvents(); } catch (e) {}
        try { targetDocument.removeEventListener('keydown', onSettingsEscKey, true); } catch (e) {}
        let targetDoc = document;
        try { if (window.parent && window.parent.document) targetDoc = window.parent.document; } catch (e) {}
        const orphan = targetDoc.getElementById(WIDGET_ID);
        if (orphan) orphan.remove();
    });

})();
